/* Bestiarium – Super Powers Companion (Gallerie der Schurken, Zivilisten, Gruppen). Quelle SUP, Seitenversatz 2 */
(window.SW_KR = window.SW_KR || []).push.apply(window.SW_KR, [{"n": "Atlanteaner", "k": "Humanoide", "w": 0, "s": ["SUP"], "p": 98, "bk": "sw_sup", "o": 2, "g": "Atlanteaner", "d": ["Atlanteaner sind ein stolzes, aber tragisches Volk, oft fremdenfeindlich gegenüber Außenstehenden und den „Oberflächenbewohnern“, die sie für die Zerstörung der Weltmeere verantwortlich machen. Das „Meervolk“ gleicht den Menschen im Aussehen, abgesehen von bläulicher Haut, Kiemen und manchmal kleinen Flossen. Sie sind stärker und robuster als Menschen aufgrund des Drucks und der Härten der Meerestiefe und können sich per Telepathie mit anderen Atlanteanern verständigen.", "Atlanteaner haben verschiedene Fahrzeuge für lange Strecken unter Wasser (daher die Fertigkeit Fahren statt Boote fahren). Nutze die Werte entsprechender Oberflächenfahrzeuge, meist mit einem Drittel der angegebenen Höchstgeschwindigkeit. Marines reisen oft in die Schlacht und werden von Gegenstücken der Mako-Angriffs-U-Boote (S. 19) unterstützt.", "Typische atlantische Bürger sind stolze und edle Wesen, begierig, ihrem Volk gegen die vielen Bedrohungen seiner Unterwasserreiche zu dienen."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W8"], ["Stärke", "W8"], ["Verstand", "W8"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W8, Fahren W4, Heimlichkeit W8, Kämpfen W6, Schießen W6, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "5", "ro": "6", "x": [["Handicaps", "Abhängigkeit (Wasser), Loyal"], ["Talente", "Superkräfte (2)"], ["Ausrüstung", "Verschieden."]], "sf": [["Wasserlebewesen", "Atlanteaner können im Wasser nicht ertrinken und bewegen sich beim Schwimmen mit voller Bewegungsweite."], ["Telepathie (2)", "Reichweite 24“ (48 m).", 1]]}, {"n": "Atlantischer Marine", "k": "Humanoide", "w": 0, "s": ["SUP"], "p": 98, "bk": "sw_sup", "o": 2, "g": "Atlanteaner", "d": ["Atlantische Marines sind die Kriegerkaste ihrer oft starren und imperialen Gesellschaften."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W10"], ["Stärke", "W10"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W10, Fahren W6, Heimlichkeit W8, Kämpfen W10, Schießen W8, Wahrnehmung W8, Überreden W6", "b": "6", "pa": "7", "ro": "11 (4)", "x": [["Handicaps", "Arrogant, Vorsichtig, Abhängigkeit (Wasser)"], ["Talente", "Volles Rohr!, Superkräfte (2)"], ["Ausrüstung", "Schwere Kampfrüstung (+4*), Kraftdreizack (Schaden Stä+W6, PB 2, Reichweite +1, +1 auf Entwaffnungsversuche; Reichweite 20/40/80, Schaden 3W6, PB 4, FR 1), Netzwerfer (Reichweite 5/10/20, Schaden Spezial, FR 1)."]], "sf": [["Wasserlebewesen", "Atlanteaner können im Wasser nicht ertrinken und bewegen sich beim Schwimmen mit voller Bewegungsweite."], ["Telepathie (2)", "Reichweite 24“ (48 m).", 1]]}, {"n": "Atlantischer Champion", "k": "Humanoide", "w": 0, "s": ["SUP"], "p": 99, "bk": "sw_sup", "o": 2, "g": "Atlanteaner", "d": ["Diese atlantischen Krieger führen vielleicht einen Trupp Marines an oder schließen sich zusammen, um besonders gefährliche Bedrohungen zu bekämpfen. Sie sind mächtige Krieger und starke Psioniker. Das Profil unten führt die am häufigsten gewählten Kräfte auf, doch manche spezialisieren sich auf andere Gebiete wie Gedankenkontrolle oder Telekinese."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W12"], ["Stärke", "W12"], ["Verstand", "W8"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W8, Athletik W12, Fahren W6, Fokus W10, Heimlichkeit W6, Kämpfen W12, Wahrnehmung W8, Überreden W6", "b": "6", "pa": "8", "ro": "16 (4)", "x": [["Handicaps", "Vorsichtig, Abhängigkeit (Wasser), Skrupellos (Leicht)"], ["Talente", "Kräftig, Mutig, Kampfreflexe, Volles Rohr!, Superkräfte (15)"], ["Ausrüstung", "Schwere Kampfrüstung (+4*), Kraftdreizack (Schaden Stä+2W6, PB 2, Reichweite +1, +1 auf Entwaffnungsversuche; Reichweite 20/40/80, Schaden 3W6, PB 4, FR 1), Netzwerfer (Reichweite 5/10/20, Schaden Spezial, FR 1)."]], "sf": [["Wasserlebewesen", "Atlanteaner können im Wasser nicht ertrinken und bewegen sich beim Schwimmen mit voller Bewegungsweite."], ["Nahkampfangriff (2)", "Stä+W6.", 1], ["Betäuben (8)", "Telepathischer Schrei. GFS. Selektiv.", 1], ["Telepathie (2)", "Reichweite 24“ (48 m).", 1], ["Zähigkeit +3 (3)", "Konditionierung.", 1]]}, {"n": "Bürger", "k": "Humanoide", "w": 0, "s": ["SUP"], "p": 100, "bk": "sw_sup", "o": 2, "g": "Zivilisten und Kriminelle", "d": ["Das sind die Leute, die die allgemeine Bevölkerung der Stadt ausmachen: Ladenbesitzer, Barkeeper und so weiter. Wie alle anderen kämpfen sie sich von Woche zu Woche durch, sind aber im Allgemeinen gesetzestreu und es wert, bei einem Superschurken-Angriff gerettet zu werden."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W6"], ["Stärke", "W6"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W4, Athletik W4, Fahren W4, Heimlichkeit W4, Kämpfen W4, Schießen W4, Wahrnehmung W6, Überreden W4", "b": "6", "pa": "4", "ro": "5", "x": [["Ausrüstung", "Bürger besitzen verschiedene, zu ihrem Beruf passende Ausrüstung. Viele besitzen eine Schusswaffe oder zumindest ein Messer."]], "sf": []}, {"n": "Schläger", "k": "Humanoide", "w": 0, "s": ["SUP"], "p": 100, "bk": "sw_sup", "o": 2, "g": "Zivilisten und Kriminelle", "d": ["Die Welt ist voller gewöhnlicher Krimineller, Männer und Frauen, die verabscheuungswürdig genug sind, den Früchten fremder Mühen nachzustellen – seien es digitale Dateien, Autos oder Essen von deren Tisch. Unten stehen Werte für gewöhnliche Schläger. Die SL sollte sie passend zu Thema oder Rolle in der Geschichte anpassen und ihnen vielleicht einen farbenfrohen Anführer und Kostüme geben. Typische Ausrüstung ist bei jedem Eintrag aufgeführt, doch die SL sollte die Schurken auf ihre Aufgabe und ihre Gegner zuschneiden. Schläger, die gegen superkräftige Helden antreten, sind fast immer mit Impulsgewehren bewaffnet, während eine außerirdische Horde, die kosmische Verteidiger besiegen soll, wahrscheinlich Impulskanonen zur Unterstützung hat.", "Das sind typische Bandenmitglieder oder Schläger, die mehr auf Muskeln als auf Hirn setzen. Die meisten Banden ab fünf Mitgliedern werden von einer Wildcard angeführt und haben vielleicht auch einen „Brecher“ oder „großen Kerl“ mit höherer Stärke und Kämpfen, dem Talent Kräftig und der Spezialfähigkeit Widerstandsfähig."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W6"], ["Stärke", "W6"], ["Verstand", "W4"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W8, Athletik W6, Diebeskunst W8, Einschüchtern W6, Fahren W6, Heimlichkeit W4, Kämpfen W6, Schießen W6, Wahrnehmung W6, Überreden W4", "b": "6", "pa": "5", "ro": "6", "x": [["Handicaps", "Gierig (Leicht), Fies"], ["Talente", "Raufbold"], ["Ausrüstung", "Messer oder kleine Keule (Stä+W4) oder Pistole (Reichweite 12/24/48, Schaden 2W6, PB 1)."]], "sf": []}, {"n": "Leutnant", "k": "Humanoide", "w": 0, "s": ["SUP"], "p": 100, "bk": "sw_sup", "o": 2, "g": "Zivilisten und Kriminelle", "d": ["Leutnants sind etwas schlauer als die einfachen Schläger, die sie anführen. Sie dienen einem größeren Boss und fürchten ihn oder sie meist weit mehr als die Behörden. Dieses Profil sollte als Ausgangspunkt für benannte Charaktere mit einigen besonderen Talenten dienen, vielleicht sogar einer niederstufigen Superkraft, je nach Setting. Ein Leutnant namens Hammer könnte zum Beispiel einen verbesserten Nahkampfangriff haben, während ein anderer, der als „Der Aal“ bekannt ist, glitschig und schwer zu treffen ist. Beides sind keine echten Superschurken, aber sie haben etwas Zusätzliches, das sie einprägsam und etwas herausfordernder macht."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W6"], ["Stärke", "W6"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W6, Diebeskunst W8, Einschüchtern W8, Fahren W6, Heimlichkeit W6, Kämpfen W8, Schießen W6, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "6", "ro": "6", "x": [["Handicaps", "Loyal"], ["Talente", "Raufbold, Anführer, Gassenwissen"], ["Ausrüstung", "Springmesser (Stä+W4), .45er Pistole (Reichweite 12/24/48, Schaden 2W6+1, PB 2). Wenn ein Leutnant weiß, dass er gegen einen Super antreten könnte, trägt er stattdessen eine passende Impulswaffe."]], "sf": []}, {"n": "Boss", "k": "Humanoide", "w": 1, "s": ["SUP"], "p": 100, "bk": "sw_sup", "o": 2, "g": "Zivilisten und Kriminelle", "d": ["Das sind die Halunken, die Straßenbanden, Kartelle und andere relativ „normale“ Organisationen leiten. Die meisten haben einige Superschurken als Muskelkraft zur Hand oder sind selbst Supers mit Kräften, die zum Thema oder Ruf ihrer Bande passen."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W8"], ["Stärke", "W8"], ["Verstand", "W8"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W10, Athletik W6, Diebeskunst W10, Einschüchtern W10, Fahren W8, Heimlichkeit W8, Kämpfen W10, Provozieren W8, Schießen W8, Wahrnehmung W8, Überreden W8", "b": "6", "pa": "8", "ro": "8 (2)", "x": [["Handicaps", "Gierig (Schwer), Gesucht (Schwer)"], ["Talente", "Block, Charismatisch, Kampfreflexe, Anführer, Inspirieren, Nerven aus Stahl, Gassenwissen"], ["Ausrüstung", "Körperpanzerung (Weste, +2*), Impulspistole (Reichweite 10/20/30, Schaden 3W6, PB 4) oder MP (FR auf 3 erhöht)."]], "sf": []}, {"n": "Streifenpolizist", "k": "Humanoide", "w": 0, "s": ["SUP"], "p": 101, "bk": "sw_sup", "o": 2, "g": "Polizeikräfte", "d": ["Die erste Verteidigungslinie der Welt sind ihre Polizisten. Diese tapferen Männer und Frauen reagieren täglich auf Gefahren und befassen sich mit dem Schlimmsten, was die Gesellschaft zu bieten hat – und das alles ohne Superkräfte.", "Das ist der durchschnittliche Streifenpolizist, Sicherheitsbeamte oder private Wachmann. Er ist oft der Erste, der auf Ärger oder einen Tatort reagiert, und ist meist überfordert, wenn es darum geht, superkräftige Bedrohungen abzuwehren."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W6"], ["Stärke", "W6"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W6, Einschüchtern W6, Fahren W6, Heimlichkeit W4, Kämpfen W6, Schießen W6, Wahrnehmung W4, Überreden W6", "b": "6", "pa": "5", "ro": "9 (4)", "x": [["Handicaps", "Verpflichtung (Leicht — Schützen und Dienen)"], ["Talente", "Beziehungen (Polizeibehörde oder Konzern), Gassenwissen"], ["Ausrüstung", "Schwere Körperpanzerung (Weste, +4*), 9mm-Handfeuerwaffe (Reichweite 12/24/48, Schaden 2W6, FR 1, PB 1), Schlagstock (Stä+W4), Handschellen."]], "sf": []}, {"n": "Ermittler", "k": "Humanoide", "w": 0, "s": ["SUP"], "p": 101, "bk": "sw_sup", "o": 2, "g": "Polizeikräfte", "d": ["Ermittler können Polizisten oder Privatdetektive, Starreporter oder andere Schnüffler sein, denen die Helden bei ihrer Arbeit begegnen. Ein Ermittler ist oft ein großartiger Verbündeter oder ein hartnäckiger, beharrlicher Feind!"], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W6"], ["Stärke", "W6"], ["Verstand", "W8"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W8, Athletik W6, Einschüchtern W8, Fahren W6, Heimlichkeit W4, Kämpfen W6, Recherche W8, Schießen W6, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "5", "ro": "5", "x": [["Handicaps", "—"], ["Talente", "Beziehungen (Strafverfolgung oder Presse), Ermittler, Gassenwissen"], ["Ausrüstung", "9mm-Handfeuerwaffe (Reichweite 12/24/48, Schaden 2W6, FR 1, PB 1)."]], "sf": []}, {"n": "SPCR-Einheit", "k": "Humanoide", "w": 0, "s": ["SUP"], "p": 101, "bk": "sw_sup", "o": 2, "g": "Polizeikräfte", "d": ["Die SPCR-Einheit (Super Power Crime Response, Einsatzkommando für Superkraft-Verbrechen) ist ein hochtrainiertes, ausgezeichnetes Team mit den hochtechnisiertesten Waffen und Rüstungen. Diese tapferen Männer und Frauen stürzen sich in die Gefahr, wenn der durchschnittliche Polizist oder Wachmann unterlegen ist. Viele SPCR-Einheiten arbeiten mit lokalen Strafverfolgungsbehörden zusammen, manche gehören zu Militärorganisationen oder sogar zu privaten, schlagkräftigen Konzern-Sicherheitskräften."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W10"], ["Stärke", "W8"], ["Verstand", "W8"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W8, Einschüchtern W8, Fahren W6, Fliegen W6, Heimlichkeit W4, Kämpfen W10, Provozieren W6, Schießen W10, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "7", "ro": "11 (4)", "x": [["Handicaps", "Loyal, Schwur (Schwer — ihrem Land, ihrer Stadt oder ihren Arbeitgebern dienen)"], ["Talente", "Mutig, Meisterschütze, Ruhige Hände"], ["Ausrüstung", "Schwere Kampfrüstung (+4*), Betäubungsknüppel (Stä+W4, siehe S. 16), Impuls-Blastergewehr (Reichweite 20/40/80, Schaden 3W6, FR 1, PB 4, SW). Manche haben außerdem Energieschilde (Parade +2, Bewegungsweite –1, Deckung –4, gewährt einen kostenlosen Aufnehmen-Wurf mit Fokus W10 gegen alle körperlichen Angriffe, siehe S. 14)."]], "sf": []}, {"n": "Alchemist", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 102, "bk": "sw_sup", "o": 2, "d": ["Nicholas Foucault ist der direkte Nachkomme des berühmten Alchemisten, dessen Namen er trägt. Er nutzt seine Kräfte nicht zum Wohl der Menschheit, sondern um seine eigene Erforschung neuer chemischer Formeln zu finanzieren. Obwohl Nicholas glaubt, seine Mixturen seien reine Wissenschaft und der Rest der Welt verstehe sein familiäres Genie einfach nicht, steckt in seinen Formeln tatsächlich mehr als ein Hauch von Magie.", "Der Alchemist hat die Verabreichungsmethoden seines Vorfahren stark verbessert. Er muss keinen Beutel voller Glasgranaten und Lederzerstäuber mehr mit sich herumtragen. Mit Hilfe des Fixers (S. 125) hat Nicholas ein „alchemistisches Verteilungssystem“ (ADS) entwickelt, einen Rucksack voller seltsamer Chemikalien, die sich sofort mischen und aus einer seiner beiden Handgelenkwaffen versprühen lassen. Das Gerät ist fest an seinen Körper geschnallt und besteht aus haltbaren, selbstversiegelnden Materialien (Härte 14, Gerätemodifikator –1)."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W8"], ["Stärke", "W6"], ["Verstand", "W12+1"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W8, Fahren W6, Fokus W12, Heilen W4, Heimlichkeit W6, Kämpfen W6, Naturwissenschaften W12, Reparieren W8, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "5", "ro": "8 (2)", "x": [["Machtniveau", "III"], ["Handicaps", "Arrogant, Kraftneutralisierung (Rotes Quecksilber), Skrupellos (Leicht), Rachsüchtig (Leicht)"], ["Talente", "Kampfreflexe, Superkräfte (45)"], ["Ausrüstung", "Körperanzug (+2), alchemistisches Verteilungssystem (ADS, siehe die verschiedenen Kräfte unten)."]], "sf": [["Verfall (5)", "Flächeneffekt (MFS). Gerät (ADS, konzentrierte Säure). Stark.", 1], ["Verstricken (6)", "Flächeneffekt (MFS). Gerät (ADS, fortschrittlicher Epoxidkleber). Stark.", 1], ["Heilung (2)", "Gerät (ADS, schnellheilende Salben).", 1], ["Geschärfte Sinne (3)", "Gehör. Restlichtsicht. Geruch. Röntgensicht. Gerät (Helm-Display).", 1], ["Eigenschaft erhöhen/senken (9)", "Zusätzliche Empfänger (4). Beliebige Eigenschaft. Macht. Gerät (ADS, radioaktive Übertragungsdämpfe).", 1], ["Negation (9)", "Flächeneffekt (MFS). Volles Spektrum. Gerät (ADS, radioaktiver Blocker). Stark.", 1], ["Fernkampfangriff (11)", "Fokus. Schaden 4W6, PB 6. Nur Kegel. Gerät (ADS, Feuer).", 1]]}, {"n": "Arrowhead", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 103, "bk": "sw_sup", "o": 2, "d": ["Für Judith Marks, eine olympische Bogenschützin, zählte nichts mehr als der Sieg. Wenn jemand ihrem Rekord auch nur nahekam, spürte sie ihn auf und schoss ihm einen Pfeil an eine Stelle, die einen langen, qualvollen Tod garantierte. Als die Behörden ihr schließlich auf die Schliche kamen, verschwand sie.", "Ein Jahr später tauchte Marks mit einem neuen Bogen und einem neuen Namen wieder auf: Arrowhead. Heute tötet sie gegen Bezahlung und gilt als eine der tödlichsten Auftragsmörderinnen auf dem Markt, obwohl viele glauben, dass es noch immer nicht sicher ist, ihren Rekord anzutasten."], "a": [["Geschicklichkeit", "W12"], ["Konstitution", "W8"], ["Stärke", "W8"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W6, Diebeskunst W10, Einschüchtern W8, Fahren W8, Fokus W8, Heimlichkeit W6, Kämpfen W12, Provozieren W6, Schießen W12+4, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "10", "ro": "8 (2)", "x": [["Machtniveau", "II"], ["Defensen", "–2"], ["Handicaps", "Gierig (Schwer), Skrupellos (Schwer), Rachsüchtig (Schwer)"], ["Talente", "Aufmerksamkeit, Volltreffer, Meisterschütze, Ruhige Hände, Der Beste (Fernkampfangriff), Superkräfte (30)"], ["Ausrüstung", "Kampfrüstung (+2*), Compoundbogen (Reichweite 12/24/48, Schaden Stä+W6, PB 1; oder als Fernkampfangriff, siehe unten)."]], "sf": [["Wachsamkeit (2)", "Ignoriert 3 Punkte der Angriffsabzüge eines Gegners. Gerät (Sensoren und Helm-Display).", 1], ["Ausweichen –2 (2)", "–2, um von Fernkampfangriffen getroffen zu werden.", 1], ["Verstricken (3)", "Bedingt durch Schießen (Bogen und Pfeile). Stark. (Stumpfe Fesselpfeile verursachen keinen Schaden.)", 1], ["Geschärfte Sinne (2)", "Adleraugen. Infrarotsicht. Restlichtsicht. Gerät (Helm-Display).", 1], ["Parade +2 (2)", "Training.", 1], ["Fernkampfangriff (13)", "Schießen. Reichweite 12/24/48, Schaden 3W6, FR 3, PB 6. Gerät (Explosivpfeile).", 1], ["Superfertigkeit (6)", "Kämpfen +2, Schießen +4.", 1]]}, {"n": "Asmodeus", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 104, "bk": "sw_sup", "o": 2, "d": ["Prinz der Äußeren Reiche, Eroberer von neun Galaxien, Verschlinger der Menschen – Asmodeus ist eine kosmische Macht, der in weiten Teilen des bekannten Universums nichts gleichkommt. Er herrscht über die Dämonenebene Stygia und schmiedet von seinem gewaltigen Thron aus seine finsteren, schrecklichen Pläne. Asmodeus strebt die vollständige Versklavung allen Lebens an. Erst dann, so behauptet er, werde der Tyrann von Stygia endlich Frieden finden.", "Asmodeus ist alterslos und zeitlos, doch selbst er kann die Launen des kosmischen Gesetzes nicht kontrollieren. Seine Armeen können Stygia nur unter bestimmten Umständen verlassen, etwa bei einer Planetenkonstellation oder wenn törichte Kultisten, die glauben, ihn kontrollieren zu können, dunkle Rituale vollenden. Die Champions der Erde haben Asmodeus bei jedem Invasionsversuch besiegt. Das erzürnt den Prinzen jenseits aller Vernunft, und nun ist die Versklavung der Erde sein größter und überwältigendster Wunsch.", "Wenn der Eroberer erscheint, folgt Dunkelheit. Schwarze Flammen brennen in seinen gespaltenen Fußstapfen. Seine Gestalt ist den Vorstellungen der Menschen entnommen: ein klischeehafter Teufel, über fünf Meter groß, mit Ziegenbeinen und karmesinroter Haut, die so heftig brennt, dass sie fast schwarz wirkt. Auf seinem Haupt sitzen gewaltige Stierhörner. Seine abscheulichen Augen sind schwarz wie Kohle. Die wenigen, die genau hingesehen haben, schwören, dass sie die schreienden Seelen sehen können, die er verschlungen hat. Er trägt einen langen Umhang, getränkt vom Blut von Jahrtausenden. Seine Stimme ist kalt wie eine sterbende Sonne.", "Die einzige Furcht des Tyrannen ist reines Licht, dem er selten begegnet, da er selbst Dunkelheit beschwören und kontrollieren kann."], "a": [["Geschicklichkeit", "W12"], ["Konstitution", "W12+2"], ["Stärke", "W12+4"], ["Verstand", "W12+2"], ["Willenskraft", "W12+2"]], "f": "Allgemeinwissen W10, Athletik W6, Fokus W12, Heimlichkeit W4, Kämpfen W12+2, Okkultismus W10, Provozieren W8, Wahrnehmung W12+2, Überleben W8, Überreden W4", "b": "8", "pa": "11", "ro": "32 (12)", "x": [["Machtniveau", "V"], ["Handicaps", "Blutrünstig, Angetrieben (Schwer — glaubt, das Universum müsse versklavt werden), Anfälligkeit für Naturgewalten (Licht), Skrupellos (Schwer)"], ["Talente", "Aufmerksamkeit, Champion (Böse), Kampfreflexe, Experte (Wahrnehmung, Verstand, Willenskraft), Flink, Wirklich schwer zu töten, Block (Verb.), Erstschlag (Verb.), Raserei (Verb.), Kühler Kopf (Verb.), Nerven aus Stahl (Verb.), Rundumschlag (Verb.), Zäh wie Leder, Meister (Kämpfen), Mächtiger Hieb, Schnell, Superkräfte (75), Den Treffer einstecken"], ["Ausrüstung", "Großschwert „Der Wille des Tyrannen“ (Stä+W12+5W6, PB 10, Parade –1, Schwere Waffe)."]], "sf": [["Zusätzliche Aktionen (5)", "Ignoriert pro Zug bis zu zwei Punkte Mehrfachaktionsabzüge.", 1], ["Alterslos (3)", "Sehr alt."], ["Rüstung +12 (10)", "Schwere Rüstung.", 1], ["Wachsamkeit (5)", "Ignoriert 5 Punkte der Angriffsabzüge eines Gegners.", 1], ["Verdammnis", "Asmodeus kehrt in den Abgrund zurück, wenn er Kampfunfähig ist."], ["Atmet nicht (2)", "Asmodeus steht über solch sterblichen Belangen!", 1], ["Isst nicht (1)", "Habt ihr nicht gehört? Asmodeus hat keinen Bedarf an solch sterblichen Nichtigkeiten!", 1], ["Energiekontrolle (8)", "Dunkelheit. Zusätzlicher Machttyp (Feuer). Flächeneffekt (GFS).", 1], ["Furcht –2 (4)", "Stark.", 1], ["Zäh (2)", "Ein zweites Ergebnis Angeschlagen verursacht keine Wunde.", 1], ["Nahkampfangriff (16)", "Schaden Stä+3W6. Schwere Waffe. Spezialwaffe (Großschwert +2W6, PB 8, Gerät, Schwere Waffe).", 1], ["Fernkampfangriff (22)", "Feuer. Reichweite 12/24/48, Schaden 6W6, PB 12.", 1], ["Größe 5 (Groß)", "Asmodeus ist 5,4 m groß und kann eine zusätzliche Wunde einstecken."], ["Zähigkeit +6 (6)", "Dämonische Konstitution."], ["Unaufhaltsam", "Der Schurke erleidet durch jeden schädigenden Angriff höchstens eine Wunde (nach dem Aufnehmen), es sei denn, die Aktionskarte des Angreifers ist ein Joker."]]}, {"n": "Baba Yaga", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 105, "bk": "sw_sup", "o": 2, "d": ["Baba Yaga, die Hexen-Ogerin der russischen Mythologie, die in einer Hütte auf Hühnerbeinen umherstolziert, ist quicklebendig. Sie verlässt ihr legendäres Heim auf ihrem magischen Mörser mit Stößel, um ihr Land zu bestreifen und sich an Menschenfleisch zu laben. Den slawischen Völkern ist sie als jemand bekannt, den man fürchtet und in verzweifeltsten Lagen um Hilfe anfleht.", "Baba ist eine seltsame Gestalt, die das slawische Volk zugleich beschützt und jagt. Wenn „ihre Kinder“ bedroht werden, beschützt die Hexe die Herde. Solchen Schutz gewährt sie „unhöflichen“ Eindringlingen nicht, besonders Kindern. Besonders grausam ist sie zu denen, die magische Fähigkeiten zeigen. Wenn sie von anderen mit mystischem Talent hört, sucht sie sie auf – vielleicht durch einen Sklaven wie den Hexenjäger (S. 177) – und vernichtet (oder bevorzugt: verschlingt) sie.", "Baba ist eine verdrehte, groteske Gestalt – der Preis für ihre langen Jahrhunderte der Grausamkeit. Wenn sie einen Reisenden beruhigen oder ein Dorf für Informationen unterwandern will, nutzt sie ihren Verkleidungszauber, um als schönes junges Mädchen oder vertrauenswürdige Matrone zu erscheinen. Mit Baba lässt sich verhandeln, doch der Preis ist meist höher, als die meisten zahlen wollen. Sie heilt vielleicht die chronische Krankheit eines Angehörigen oder bekämpft für ein Dorf eine schreckliche Bedrohung, verlangt dafür aber die Opferung eines ahnungslosen Menschen mit aufkeimendem magischem Talent."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W12"], ["Stärke", "W12"], ["Verstand", "W12+2"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W6, Einschüchtern W8, Fokus W12, Heimlichkeit W10, Kämpfen W8, Okkultismus W12+4, Wahrnehmung W10, Zaubern W12+2, Überleben W10", "b": "6", "pa": "6", "ro": "12 (at full size)", "x": [["Machtniveau", "IV"], ["Defensen", "–4 (Fernkampf)"], ["Handicaps", "Arrogant, Skrupellos (Schwer), Hässlich (Schwer), Rachsüchtig (Schwer)"], ["Talente", "Arkaner Hintergrund (Magie), Erstschlag, Raserei, Schwer zu töten, Kühler Kopf (Verb.), Nerven aus Stahl, Superkräfte (60), Naturbursche"], ["Zauber", "Barriere, Tierfreund, Blenden, Eigenschaft erhöhen/senken, Verwirrung, Dunkelsicht, Ablenkung, Arkanes entdecken/verbergen, Verkleiden, Bannen, Wahrsagung, Machtpunkte entziehen, Elementarmanipulation, Verstricken, Schutz vor Naturgewalten, Fernsicht, Furcht, Heilung, Illusion, Licht/Dunkelheit, Objekt auslesen, Schutz, Marionette, Gestaltwandeln, Trägheit/Beschleunigung, Schlummer, Geräusch/Stille, Sprachen sprechen, Betäuben, Verbündeten beschwören, Telekinese, Teleportation, Wandkrabbler, Zombie (Machtpunkte: 60)"], ["Ausrüstung", "Fliegender Mörser mit Stößel in Menschengröße (siehe Flug), tanzende Hütte."]], "sf": [["Alterslos (3)", "Sehr alt (+2 auf Verstand und Allgemeinwissen).", 1], ["Ausweichen –4 (4)", "–4, um von Fernkampfangriffen getroffen zu werden.", 1], ["Flug (2)", "Bewegungsweite 45 (48 km/h). Gerät (Hütte oder Mörser mit Stößel). Sie manövriert mit Geschicklichkeit. Unbeholfen.", 1], ["Wachstum (14)", "Stufe 4 (Größe 4 (3,6 m groß), +4 auf Größe, Stärke und Robustheit). Schlagen (ignoriert 4 Punkte Größenabzüge).", 1], ["Besessenheit (6)", "Alternatives Attribut (Zaubern).", 1], ["Stoßen (4)", "Alternatives Attribut (Zaubern). Stark.", 1], ["Fernkampfangriff (15)", "Zaubern. Reichweite 12/24/48, Schaden 5W6, PB 4. Darf die Kegelschablone nutzen.", 1], ["Verlangsamen (5)", "Zusätzliche Empfänger +3.", 1], ["Superfertigkeit (3)", "Zaubern +3.", 1], ["Superzauberei (4)", "Baba Yaga ist eine Hexe.", 1], ["Unaufhaltsam", "Der Schurke erleidet durch jeden schädigenden Angriff höchstens eine Wunde (nach dem Aufnehmen), es sei denn, die Aktionskarte des Angreifers ist ein Joker."]]}, {"n": "Beachhead", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 106, "bk": "sw_sup", "o": 2, "d": ["Sergeant Dirk Davis war auf einer Geheimmission, als sein Team der Gefangennahme nahe war. Davis forderte einen Luftschlag an, doch eine Schattenbehörde der US-Regierung beschloss stattdessen, alle Spuren ihrer Aktivitäten zu beseitigen. Sie ließen einen experimentellen, neutronenbasierten Mikro-Taktikgefechtskopf abfeuern. Davis wusste, was kam, und befahl seinen Männern zu rennen. Sie schafften es nicht, doch Dirk sprang in letzter Sekunde in eine Sandgrube und überlebte irgendwie. Als er zu sich kam, war sein Körper mit dem Sand verschmolzen, und er war fortan der rachsüchtige Schurke, der als Beachhead bekannt ist."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W10"], ["Stärke", "W12"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W10, Boote fahren W6, Einschüchtern W10, Fahren W8, Fokus W10, Heimlichkeit W10, Kriegskunst W10, Kämpfen W12, Wahrnehmung W8, Überreden W6", "b": "6", "pa": "8", "ro": "20", "x": [["Machtniveau", "III"], ["Handicaps", "Auffälliges Aussehen (aus Sand bestehend), Anfälligkeit für Naturgewalten (Wasser), Loyal, Rachsüchtig (Schwer)"], ["Talente", "Kräftig, Kampfreflexe, Nerven aus Stahl (Verb.), Superkräfte (45)"], ["Ausrüstung", "Keine."]], "sf": [["Veränderte Form (8)", "Sand. Greifer. Reichweite +2. Zähflüssig. Nachgeben.", 1], ["Graben (3)", "Bewegungsweite 6. Tunnelbauer.", 1], ["Umweltresistenz (1)", "Erde.", 1], ["Explodieren (4)", "Sandexplosion. Schaden 5W10. Flächeneffekt (GFS). Großer Knall. Sicherung. Vorübergehende Auflösung.", 1], ["Wachstum (4)", "Stufe 2 (+2 auf Größe, Stärke und Robustheit). Dauerhaft.", 1], ["Nahkampfangriff (6)", "Stä+3W6.", 1], ["Fernkampfangriff (7)", "Sandstrahl. Fokus. Schaden 3W6. Nur Kegelschablone. Schwere Waffe.", 1], ["Superattribut (2)", "Stärke +1.", 1], ["Zähigkeit +10 (10)", "Körper aus Fels und Sand.", 1]]}, {"n": "The Black Hole", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 107, "bk": "sw_sup", "o": 2, "d": ["Die Wissenschaftsgemeinde pries Dr. Emil Munroes brillante Forschung, doch sie schnappte entsetzt nach Luft, als er tatsächlich ein Mini-Schwarzes-Loch erschuf! Das Experiment veränderte Munroes Molekularstruktur und verwandelte ihn in ein Wesen aus reiner Energie – Energie, die aus einem Schwarzen Loch selbst geboren wurde. Wenn Munroes Verstand stabil ist, sucht er nach einem Weg, seinen Körper zu heilen und ihn wieder in Fleisch zu verwandeln. Er will seine Fähigkeiten jedoch nicht aufgeben, und das ständige Scheitern hat ihn in den Wahnsinn getrieben.", "Emil verübelt besonders die verschiedenen Wissenschaftler und Organisationen, die ihn vor den Gefahren seiner Forschung gewarnt hatten. Er taucht oft wutentbrannt auf Forschungs- oder Technikmessen auf, um gegen einen Feind oder eine vermeintliche Kränkung loszuschlagen, oder überfällt Labore und Konzerne, die angeblich Technologie besitzen, die seine Missgestalt heilen könnte."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W12"], ["Stärke", "W8"], ["Verstand", "W10"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W8, Athletik W6, Einschüchtern W10, Fokus W12, Heimlichkeit W8, Kämpfen W6, Naturwissenschaften W12, Wahrnehmung W10, Überreden W4", "b": "6", "pa": "5", "ro": "20 (12)", "x": [["Machtniveau", "IV"], ["Handicaps", "Fremdgestalt (Körper aus reiner, lichtloser Energie), Skrupellos (Schwer), Dünnhäutig (Schwer)"], ["Talente", "Kampfreflexe, Gefahrensinn, Nerven aus Stahl (Verb.), Gelehrter (Naturwissenschaften), Superkräfte (75)"], ["Ausrüstung", "Keine."]], "sf": [["Absorption (14)", "Kraft. Zusätzliche Machttypen (alle). Reflexion. Übertragung.", 1], ["Rüstung +12 (6)", "Verzerrungseffekt.", 1], ["Energiekontrolle (12)", "Kraft. Flächeneffekt (GFS). Macht.", 1], ["Flug (19)", "Nahe Lichtgeschwindigkeit, –10 auf Treffer. Lichtgeschwindigkeit.", 1], ["Fernkampfangriff (20)", "Fokus. 6W6. Flächeneffekt (GFS) oder Kegel. Schwere Waffe.", 1], ["Raumfahrer (2)", "Das Schwarze Loch kann im Weltraum überleben.", 1], ["Superfertigkeit (2)", "Fokus +2.", 1]]}, {"n": "Blackguard", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 108, "bk": "sw_sup", "o": 2, "d": ["Axel Grates Eltern wurden von abscheulichen Kultisten ermordet, die einen uralten, namenlosen Gott der Zerstörung erwecken wollten. Als der Junge heranwuchs, machte sich der gequälte Jugendliche auf, die Mörder seiner Eltern aufzuspüren, hinterließ dabei eine Spur der Verwüstung und wurde schließlich zum Selbstjustiz-Schurken „Blackguard“. Blackguards blutiger Kreuzzug endete, als der Kult sich versammelte, um seinen überirdischen Avatar zu beschwören. Der gequälte Champion blieb schließlich siegreich und befreite sogar die lange gefolterten Seelen seiner Eltern.", "Axel stieg aus der titanischen Verwüstung und fand sich der Doom Guard gegenüber. Zu seiner Überraschung bot ihm der Anführer des Teams, Warden, eine Hand statt einer Faust an. Blackguard erhielt eine Begnadigung dafür, die Welt gerettet zu haben – aber nur, wenn er der Doom Guard beitrat. Blackguard ringt mit seiner Rolle als Held, hat es aber bisher geschafft, seine brodelnde Wut auf seine Feinde zu richten. Er gerät oft mit Warden aneinander, sieht in ihm aber insgeheim den Vater, den er vor so langer Zeit verloren hat."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W8"], ["Stärke", "W8"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W8, Diebeskunst W8, Einschüchtern W8, Fliegen W8, Fokus W8, Heimlichkeit W8, Kämpfen W10, Okkultismus W8, Provozieren W6, Schießen W8, Wahrnehmung W8, Überreden W4", "b": "6", "pa": "9", "ro": "10 (2)", "x": [["Machtniveau", "II"], ["Handicaps", "Angetrieben (Schwer — dunkle Kulte besiegen), Grimmig, Skrupellos (Leicht), Geheimidentität"], ["Talente", "Schläger, Erstschlag, Nerven aus Stahl, Superkräfte (30)"], ["Ausrüstung", "Kampfrüstung (+2*), Impulspistolen (Reichweite 10/20/40, Schaden 2W6, PB 2), Kraftfäustlinge (Stä+W4+W6, siehe S. 16), Enterhaken, Fernglas, Funkgerät, Rauchgranaten ×4, Umhang (gepanzert, verschleiernd), Netzwerfer."]], "sf": [["Wachsamkeit (5)", "Ignoriert 5 Punkte der Angriffsabzüge eines Gegners. Intensives Training.", 1], ["Eigenschaft erhöhen/senken (1)", "Stärke. Gerät (Druckluftinjektor und Kartuschen mit experimentellen Steroiden). Macht. Einschränkung (nur Eigenschaft erhöhen).", 1], ["Scharfschütze (2)", "Meisterschütze.", 1], ["Furcht (2)", "Furchteinflößendes Stirnrunzeln.", 1], ["Zäh (2)", "Schmerzunempfindlich.", 1], ["Geschärfte Sinne (1)", "Gehör. Infrarotsicht. Gerät (Kapuze mit eingebauten Scannern).", 1], ["Illusion (7)", "Ablenkung. Filmqualität. Verschleierung. Gerät (Holoscheiben).", 1], ["Gedankenschild (2)", "Stark. Gerät (Schreckenskapuze mit Anti-Telepathie-Futter).", 1], ["Negation (5)", "Volles Spektrum. Berührung erforderlich. Stark. Gerät (Kraftumkehrfeld in den Handschellen).", 1], ["Parade +2 (2)", "Reflexverstärkende Implantate.", 1], ["Superfertigkeit (1)", "+1 Fokus. (Gadget-Meister).", 1]]}, {"n": "Blood Widow", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 109, "bk": "sw_sup", "o": 2, "d": ["Debbie Dalton war Klatschkolumnistin und Filmkritikerin für jedes Käseblatt, das ihre reißerischen Enthüllungen druckte. Diese Karriere endete, als sie das Schockende von „Radioaktive Mutantenspinnen 3“ verriet. Das ruinierte das beliebte Franchise und stürzte das Studio in den Bankrott. Die rachsüchtige Schöpferin der Mutantenspinnen-Reihe gab ihr letztes Geld dafür aus, Tausende echte Spinnen zu sammeln und zu bestrahlen – und ließ sie dann in Debbies Wohnung los! Die Kritikerin erwachte schreiend, gebissen von tausend leuchtenden Spinnentieren voller seltsamer radioaktiver Toxine. In dieser Nacht wurde Blood Widow geboren.", "Heute verdient Debbie ihren Lebensunterhalt als Auftragsmörderin und Terroristin, auch wenn sie gelegentlich einen blutigen Amoklauf gegen Hollywood und Prominente unternimmt, die sie für ihr schreckliches Schicksal verantwortlich macht. Als Schauspielerin scheiterte Debbie, kennt aber genug Maske, Kostümierung und Darstellungstechniken, um sich als Crewmitglied auszugeben und sich auf Hollywood-Sets, Preisverleihungen und Ähnliches einzuschleichen. Ironischerweise wurde Debbies Rache an der Schöpferin der Mutantenspinnen-Reihe zu einer sehr erfolgreichen, aber von Kritikern verrissenen Mega-Serie."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W8"], ["Stärke", "W6"], ["Verstand", "W6"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W8, Athletik W4, Darbietung W8, Diebeskunst W10, Fahren W8, Fokus W8, Heimlichkeit W6, Kämpfen W10, Provozieren W4, Wahrnehmung W8, Überreden W12+2", "b": "6", "pa": "10", "ro": "8 (2)", "x": [["Machtniveau", "II"], ["Defensen", "–2"], ["Handicaps", "Monologisierer, Tick (eitel), Gassenwissen, Stur, Rachsüchtig (Schwer)"], ["Talente", "(Sehr) Attraktiv, Charismatisch, Superkräfte (30)"], ["Ausrüstung", "Körperanzug (+2)."]], "sf": [["Wachsamkeit (4)", "Ignoriert 4 Punkte der Angriffsabzüge eines Gegners.", 1], ["Ausweichen –2 (2)", "–2, um von Fernkampfangriffen getroffen zu werden.", 1], ["Verstricken (7)", "Spinnennetze. Flächeneffekt (MFS). Stark.", 1], ["Nahkampfangriff (5)", "Stä+2W6. Biss (+W4).", 1], ["Parade +3 (3)", "Voraussicht.", 1], ["Gift (3)", "Bedingt durch Kämpfen mit Nahkampfangriff, Biss. Tödlich. Stark.", 1], ["Superfertigkeit (2)", "Überreden +2.", 1], ["Übernatürliche Reflexe (3)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffe, die dies normalerweise nicht erlauben, mit –2 ausweichen.", 1], ["Wandkrabbler (1)", "Debbie hat winzige insektenartige Haken an den Handflächen.", 1]]}, {"n": "Boomer", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 110, "bk": "sw_sup", "o": 2, "d": ["Dick McClure wanderte durch ein Aborigine-Reservat in Australien, als er auf einen seltsamen schwarzblauen Bumerang stieß, der vor Macht summte. Dick hob das Ding auf und wurde sofort von einer schrecklichen Präsenz besessen. „Boomer“ begeht nun Raubüberfälle, Coups und willkürliche Akte des Vandalismus und flüstert dabei wahnhaft mit dem Bumerang. Vielleicht bereitet die Wesenheit darin Boomer auf irgendeine schreckliche, katastrophale Tat vor – oder vielleicht versucht er verzweifelt, die Aufmerksamkeit von Helden zu erregen, die ihm helfen, das Grauen abzuschütteln!"], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W8"], ["Stärke", "W6"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W12+2, Fahren W8, Heimlichkeit W6, Kämpfen W8, Okkultismus W4, Provozieren W10, Reparieren W6, Schießen W6, Wahrnehmung W6, Überreden W4", "b": "6", "pa": "6", "ro": "9", "x": [["Machtniveau", "I"], ["Handicaps", "Wahnvorstellungen (Leicht — spricht mit dem Bumerang), Gierig (Schwer), Fies"], ["Talente", "Glück, Meisterschütze, Schnell, Superkräfte (15)"], ["Ausrüstung", "Keine."]], "sf": [["Wachsamkeit (1)", "Ignoriert 3 Punkte der Angriffsabzüge eines Gegners. Gerät (verfluchter Bumerang).", 1], ["Flug (2)", "Bewegungsweite 24 (16 Meilen/h = 26 km/h). Gerät (verfluchter Bumerang). Einschränkung (Boomer kann seinen Bumerang nicht werfen, während er fliegt).", 1], ["Fernkampfangriff (7)", "Athletik. Reichweite 12/24/48, Schaden 4W6. Gerät (verfluchter Bumerang).", 1], ["Supertalent (1)", "Meisterschütze. Gerät (verfluchter Bumerang).", 1], ["Superfertigkeit (3)", "Athletik +5. Gerät (verfluchter Bumerang).", 1], ["Zähigkeit +3 (1)", "Mystischer Schutz. Gerät (verfluchter Bumerang).", 1]]}, {"n": "Brimstone", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 111, "bk": "sw_sup", "o": 2, "d": ["Jose Gonzalez war Feuerwehrmann in Los Angeles, als ein Irrer die Stadt bombardierte. Eine der Bomben traf das Chemielager, das er zu retten versuchte, und übergoss ihn mit brennendem Schwefel. Während der Schwefel sein Fleisch und den Großteil seines Verstandes auflöste, wurde Jose zu einem Wesen aus lebendem Feuer. Obwohl die chemische Reaktion in seinem Körper sich verlangsamt hat, ist sie nicht gestoppt. Es ist nur eine Frage der Zeit, bis er vollständig verzehrt ist. Bis dahin lebt er als Brimstone, ein wahnsinniger Schurke, gehüllt in ständige Flammen, der die Welt niederbrennen will."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W8"], ["Stärke", "W10"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W8, Diebeskunst W6, Einschüchtern W6, Fahren W8, Fokus W10, Heimlichkeit W6, Kämpfen W8, Schießen W6, Wahrnehmung W8, Überreden W4", "b": "6", "pa": "6", "ro": "6", "x": [["Machtniveau", "III"], ["Handicaps", "Fremdgestalt (feuriger Körper), Anfälligkeit für Naturgewalten (Wasser), Angewohnheit (Schwer — muss alles um sich herum verbrennen), Todkrank"], ["Talente", "Extraktion (Verb.), Superkräfte (45)"], ["Ausrüstung", "Keine."]], "sf": [["Absorption (10)", "Feuer. Zusätzliche Machttypen (alle). Achillesferse (Magie, Mental). Meisterschaft (Feuer).", 1], ["Veränderte Form (3)", "Feuer. Nachgeben.", 1], ["Schadensfeld (13)", "Feuer. Schaden 4W6. Flächeneffekt (GFS). Schwere Waffe. Dauerhaft.", 1], ["Energiekontrolle (7)", "Feuer. Flächeneffekt (GFS).", 1], ["Fernkampfangriff (12)", "Feuer. Fokus. Reichweite 12/24/48, Schaden 5W6. Schwere Waffe. Tödlich.", 1]]}, {"n": "Chainsaw", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 112, "bk": "sw_sup", "o": 2, "d": ["Anders als die meisten Superschurken träumt Chainsaw (alias Piotr Kopovski) nicht von Weltherrschaft, finanziellem Reichtum oder anderen hehren Zielen. Er will für eines in Erinnerung bleiben: die höchste Opferzahl eines Massenmörders in einer langen, blutigen Karriere. Piotr weiß, dass er nicht klug genug ist, um lange der Gefangennahme zu entgehen, und verdingt sich daher oft bei anderen mit mehr Macht oder besseren Verbindungen. Ihm geht es weit mehr um die langfristige Opferzahl als um den kurzfristigen Leichenberg."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W8"], ["Stärke", "W12"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W4 Driving W8, Athletik W6, Diebeskunst W4, Einschüchtern W6, Fokus W6, Heimlichkeit W8, Kämpfen W12, Wahrnehmung W8, Überreden W4", "b": "6", "pa": "8", "ro": "12 (4)", "x": [["Machtniveau", "II"], ["Handicaps", "Blutrünstig, Angewohnheit (Leicht — poliert ständig seine Kettensäge), Rachsüchtig (Schwer)"], ["Talente", "Block (Verb.), Rundumschlag (Verb.), Superkräfte (30)"], ["Ausrüstung", "Körperpanzer (+4*), Schädelmaske, diamantbesetzte Kettensäge (Stä+5W6, PB 4)."]], "sf": [["Zusätzliche Aktionen (5)", "Ignoriert pro Zug bis zu zwei Punkte Mehrfachaktionsabzüge.", 1], ["Furcht –2 (3)", "Stark. Gerät (Maske).", 1], ["Furchtlos (2)", "Piotr ist seine eigene Horrorshow.", 1], ["Nahkampfangriff (6)", "Stä+3W6.", 1], ["Superattribut (8)", "Geschicklichkeit +1, Stärke +2, Konstitution +1.", 1], ["Supertalent (4)", "Block (Verb.)", 1], ["Zähigkeit +2 (2)", "Dick und muskulös.", 1]]}, {"n": "Clone", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 113, "bk": "sw_sup", "o": 2, "d": ["Clone, alias Michaela Donaldson, ist eine von vielen Kopien derselben Person, die verschiedene Dimensionen bewohnen. Im Kampf kopiert sie bevorzugt die Kraft eines Gegners, neutralisiert die Fähigkeiten des Originals, beschwört einen oder zwei dimensionale Zwillinge und lässt ihren Gegner dann die Auswirkungen seiner eigenen Kräfte erleiden – verdoppelt oder gar verdreifacht. Clone wurde mit ihren Kräften geboren und hat keine Ahnung, woher sie stammen, vermutet aber, dass die wilden Geschichten ihrer Mutter über Entführungen durch Außerirdische ein Körnchen Wahrheit enthalten."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W6"], ["Stärke", "W6"], ["Verstand", "W10"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W6, Diebeskunst W6, Fahren W6, Fokus W10, Heimlichkeit W8, Kämpfen W8, Provozieren W10, Wahrnehmung W8, Überreden W4", "b": "6", "pa": "6", "ro": "5", "x": [["Machtniveau", "II"], ["Handicaps", "Angewohnheit (Leicht — spricht mit sich selbst), Übermütig, Skrupellos (Schwer), Rachsüchtig (Schwer)"], ["Talente", "Aufmerksamkeit, Ausweichen, Rückzug, Schnell, Superkräfte (30)"], ["Ausrüstung", "Keine."]], "sf": [["Wachsamkeit +2 (2)", "Ignoriert 2 Punkte Angriffsabzüge.", 1], ["Nachahmer (10)", "Stufe 8. Verbunden mit Negation. Übergenau.", 1], ["Duplizierung (10)", "Stufe 2. Beförderung.", 1], ["Eigenschaft erhöhen/senken (2)", "Beliebige Eigenschaft. Absaugen. Berührung erforderlich. Einschränkung (nur Eigenschaft senken).", 1], ["Negation (6)", "Volles Spektrum.", 1]]}, {"n": "The Controller", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 114, "bk": "sw_sup", "o": 2, "d": ["Der New Yorker Verbrecherboss Alfred „Big Al“ Mazetti verschwand, als die V’sori Manhattan in eine Gefängnisinsel verwandelten. Sein Sohn Felix erbte, was vom Imperium übrig war, während er am M.I.T. noch seinen Master in Informatik beendete. Felix zog nach Star City, übernahm das Geschäft seines Vaters, erweiterte die Aktivitäten der Mafia um Cyberverbrechen und schuf schließlich das Kraken-Verbrechersyndikat, in dem er als „The Controller“ bekannt ist.", "Mit Hilfe des Fixers (S. 125) baute Felix eine Kraftrüstung, die seine Fähigkeit steigert, in Computersysteme einzudringen, zu fliegen und sogar zu kämpfen – was er für unerlässlich hält, um das Aushängeschild eines modernen internationalen Verbrechersyndikats zu sein. Die künstliche Intelligenz der Doom Guard, Cassandra, hat bemerkt, dass Felix seinen Anzug dieser Tage kaum noch ablegt, und vermutet, dass die KI des Anzugs Mazettis Geist übernommen hat und der wahre Controller ist."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W6"], ["Stärke", "W6"], ["Verstand", "W12"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W8, Athletik W6, Diebeskunst W10, Elektronik W12+2, Fahren W8, Fokus W10, Hacken W10, Heimlichkeit W10, Kämpfen W8, Recherche W10, Schießen W6, Wahrnehmung W10, Überreden W6", "b": "6", "pa": "6", "ro": "23 (18)", "x": [["Machtniveau", "IV"], ["Handicaps", "Arrogant, Skrupellos (Schwer), Rachsüchtig (Schwer)"], ["Talente", "Attraktiv, Beziehungen, Kühler Kopf (Verb.), Gelehrter (Elektronik, Hacken), Superkräfte (60), Gassenwissen"], ["Ausrüstung", "Controller-Anzug (siehe die verschiedenen Kräfte unten)."]], "sf": [["Rüstung +18 (12)", "Gerät (Anzug). Schwere Rüstung.", 1], ["Rundfunk (7)", "Kanalsurfer. Gerät (Anzug). Manipulation (Deepfakes). Reichweite (1.600 km).", 1], ["Flug (7)", "Bewegungsweite 45 (48 km/h). Gerät (Anzug).", 1], ["Illusion (11)", "Hologramme. Flächeneffekt (GFS). Gerät (Anzug). Ablenkung. Filmqualität. Verschleierung. Systemschock.", 1], ["Schnittstelle (4)", "Codeknacker. Gerät (Anzug). Schnell.", 1], ["Fernkampfangriff (19)", "Laser. Fokus. Schaden 4W6, PB 10, FR 3. Gerät (Anzug).", 1]]}, {"n": "The Crab", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 115, "bk": "sw_sup", "o": 2, "d": ["Sam Watkins war ein Umweltaktivist, der keine Scheu hatte, Gewalt gegen jene einzusetzen, die seiner Meinung nach den Planeten schädigten. Seine Feinde erwischten ihn schließlich und kippten Sam auf eine Giftmülldeponie voller Winkerkrabben. Heraus kam ein verwirrter, wahnsinniger Mischling aus Mensch und Krabbe. Wenn Sam klar bei Verstand ist, nimmt er Interessen ins Visier, die seiner Ansicht nach den Planeten vergiften, meist an oder nahe dem Ozean. Gelegentlich wütet er in Küstenstädten und ist zur Geißel von Tourismus und Industrie geworden, wo immer er auftaucht."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W10"], ["Stärke", "W12+2"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W8, Athletik W12, Einschüchtern W8, Fokus W6, Heimlichkeit W6, Kämpfen W12, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "9", "ro": "17 (10)", "x": [["Machtniveau", "II"], ["Handicaps", "Zwei linke Hände, Auffälliges Aussehen (Krabbenmensch), Fies, Skrupellos (Schwer), Schwur (Schwer — den Planeten um jeden Preis beschützen)"], ["Talente", "Raserei, Superkräfte (30), Beidhändiger Kampf"], ["Ausrüstung", "Keine."]], "sf": [["Wasserlebewesen (2)", "Schwimm-Bewegungsweite 6, atmet unter Wasser.", 1], ["Rüstung +10 (5)", "Panzer.", 1], ["Geschärfte Sinne (1)", "Gehör.", 1], ["Nahkampfangriff (10)", "Stä+3W6. Klauen (+W6, PB 2).", 1], ["Parade +1 (1)", "Große Scheren.", 1], ["Superattribut (8)", "Stärke +3, Konstitution +1.", 1], ["Superfertigkeit (3)", "Athletik +1, Kämpfen +1, Einschüchtern +1.", 1]]}, {"n": "Initiat der Purpurfaust", "k": "Humanoide", "w": 0, "s": ["SUP"], "p": 116, "bk": "sw_sup", "o": 2, "g": "Die Purpurfaust", "d": ["Die Faust ist eine geheime, weltweite Verbrecherorganisation mit Sitz in Osaka, Japan, bestehend aus geschickten und tödlichen Kampfkünstlern. Sie hat ihre eigene geheime Agenda, ist aber mit der berüchtigten Kyoto-Yakuza unter Fantamu (S. 124) verbündet und dient ihr. „Meister“ befehligen unabhängige „Fäuste“ von Söldnern auf der ganzen Welt. Manche behaupten, ein „Uralter und Ehrwürdiger Lord“ verbinde die Zellen von einem verborgenen Tempel in der Wildnis aus, doch bisher ist diese Theorie unbewiesen.", "Initiaten haben ihre Ausbildung abgeschlossen und wollen sich vor ihren Meistern beweisen. Man sollte sie nie unterschätzen, besonders nicht, wenn man ihnen in großen Gruppen begegnet."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W8"], ["Stärke", "W8"], ["Verstand", "W6"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W6, Athletik W10, Diebeskunst W10, Fahren W4, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W8, Überleben W6, Überreden W6", "b": "6", "pa": "9", "ro": "6", "x": [["Handicaps", "Skrupellos (Schwer), Schwur (Schwer — dem Clan dienen)"], ["Talente", "Assassine, Block, Erstschlag, Kampfkünstler, Superkräfte (15), Dieb"], ["Ausrüstung", "Ninja-to (Stä+2W6), Shuriken (Reichweite 3/6/12, Stärke+W4+W6)."]], "sf": [["Wachsamkeit (2)", "Ignoriert 2 Punkte der Angriffsabzüge eines Gegners.", 1], ["Springen (4)", "4“ senkrecht, 8“ waagerecht. Abprallen. Tod von oben.", 1], ["Nahkampfangriff (4)", "+W6 auf Kämpfen-Angriffe. Wurfwaffen.", 1], ["Parade +2 (2)", "Ninja-Training.", 1], ["Übernatürliche Reflexe (3)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen.", 1]]}, {"n": "Meister der Purpurfaust", "k": "Humanoide", "w": 0, "s": ["SUP"], "p": 116, "bk": "sw_sup", "o": 2, "g": "Die Purpurfaust", "d": ["Meister sind die Geschicktesten des Ordens und führen Gruppen von Initiaten auf ihren Missionen an, die sich zu Elite-Angriffstrupps zusammenschließen, um mächtigere Feinde oder schwierigere Herausforderungen zu bewältigen."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W10"], ["Stärke", "W8"], ["Verstand", "W8"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W10, Diebeskunst W10, Fahren W4, Heimlichkeit W10, Kämpfen W12, Wahrnehmung W8, Überleben W6, Überreden W6", "b": "6", "pa": "12", "ro": "12", "x": [["Handicaps", "Gierig (Schwer), Skrupellos (Schwer), Schwur (Leicht — bricht selten Verträge)"], ["Talente", "Assassine, Block (Verb.), Chi, Erstschlag, Kampfkünstler, Kampfkunstmeister, Superkräfte (25), Dieb, Lieblingswaffe"], ["Ausrüstung", "Ninja-to (Stä+2W6), Shuriken (Reichweite 3/6/12, Stä+W4+W6)."]], "sf": [["Wachsamkeit (2)", "Ignoriert 2 Punkte der Angriffsabzüge eines Gegners.", 1], ["Ausweichen –4 (4)", "–4, um von Fernkampfangriffen getroffen zu werden.", 1], ["Springen (4)", "4“ senkrecht, 8“ waagerecht. Abprallen. Tod von oben.", 1], ["Nahkampfangriff (6)", "+W6 auf Kämpfen-Angriffe. Wurfwaffen.", 1], ["Parade +1 (1)", "Ninja-Training.", 1], ["Zähigkeit +5 (5)", "Mystisches Training.", 1], ["Übernatürliche Reflexe (3)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen.", 1]]}, {"n": "Crusader", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 117, "bk": "sw_sup", "o": 2, "d": ["Dr. Piers Walsh entdeckte bei Ausgrabungen einer Burg im Heiligen Land ein altes Kreuzritter-Grab. Als er das nahezu perfekt erhaltene Schwert des toten Ritters zog, sprach er ein Dankgebet. Sofort erfüllte göttliche Energie den Arzt, eine Rüstung aus glänzendem Kettenhemd erschien aus dem Nichts an seinem Körper, und er wusste instinktiv, dass er die Macht zu heilen besaß. Walsh wurde zu Crusader – einem Superhelden.", "Crusader hat keine Superkräfte, solange sein Schwert nicht gezogen und ein Gebet gesprochen wurde. Crusader ist ein Held und kein Schurke, hat aber eine sehr schwarz-weiße Persönlichkeit und stellt sich womöglich gegen die Spielercharaktere, wenn er ihr Handeln für nicht rein genug hält."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W12"], ["Stärke", "W12"], ["Verstand", "W8"], ["Willenskraft", "W12"]], "f": "Allgemeinwissen W6, Athletik W6, Fahren W4, Fokus W10, Heimlichkeit W8, Kämpfen W12+2, Okkultismus W8, Recherche W6, Reiten W6, Wahrnehmung W6, Überreden W8", "b": "6", "pa": "19", "ro": "18 (10)", "x": [["Machtniveau", "IV"], ["Handicaps", "Ehrenkodex, Verwandlung (muss sein Schwert ziehen und ein Gebet sprechen), Angewohnheit (Leicht — murmelt ständig Gebete), Loyal"], ["Talente", "Champion, Charismatisch, Kampfreflexe, Block (Verb.), Superkräfte (60), Lieblingswaffe (verzaubertes Langschwert)"], ["Ausrüstung", "Verzaubertes Kettenhemd (siehe unten), heiliges Langschwert (Stä+W8+5W6, Schwere Waffe), mittlerer Schild (Parade +2)."]], "sf": [["Rüstung +10 (4)", "Gerät (verzaubertes Kettenhemd).", 1], ["Wachsamkeit (4)", "Ignoriert 4 Punkte der Angriffsabzüge eines Gegners.", 1], ["Furchtlos (2)", "Immun gegen Furcht.", 1], ["Heilung (11)", "Heilen. Erschöpfung. Erfrischen. Berührung erforderlich. Wiederherstellung. Wiederauferstehung.", 1], ["Nahkampfangriff (12)", "Stä+2W6. Spezialwaffe (Langschwert +3W6, Gerät, Schwere Waffe, Zerschmettern).", 1], ["Parade +5 (5)", "Schwertmeister.", 1], ["Regeneration (5)", "Crusader würfelt stündlich auf natürliche Heilung.", 1], ["Superattribut (12)", "Geschicklichkeit +1, Willenskraft +1, Stärke +2, Konstitution +2.", 1], ["Superfertigkeit (2)", "Kämpfen +2.", 1], ["Übernatürliche Reflexe (3)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen.", 1]]}, {"n": "Stygische Höllenhunde", "k": "Dämonen", "w": 0, "s": ["SUP"], "p": 118, "bk": "sw_sup", "o": 2, "g": "Die Dunkle Brut", "d": ["Die Dunkle Brut sind die Legionen von Stygia. Asmodeus (S. 104) und seine Kriegsherren befehligen Horden dieser Schrecken, wenn sie eine unglückselige Welt überfallen. Einige der häufigsten sind unten aufgeführt. Stygische Höllenhunde werden auf Zivilbevölkerungen losgelassen oder um Schrecken zu verbreiten. Geflügelte Schrecken werden entsandt, um sie anzuführen oder stärkere Ziele auszuschalten – etwa lästige Helden!", "Stygische Höllenhunde sind doggengroße Kriegsbestien, die von den Herren des Abgrunds auf ahnungslose Bevölkerungen losgelassen werden. Sie sind für die stygischen Herren relativ leicht zu beschwören und zu kontrollieren."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W10"], ["Stärke", "W12"], ["Verstand", "W4 (A)"], ["Willenskraft", "W6"]], "f": "Athletik W8, Einschüchtern W6, Heimlichkeit W10, Wahrnehmung W12, Überleben W6", "b": "10", "pa": "7", "ro": "11 (4)", "x": [["Handicaps", "Blutrünstig"], ["Talente", "Aufmerksamkeit, Raserei (Verb.)"], ["Ausrüstung", "Keine."]], "sf": [["Rüstung +4", "Schuppenhaut."], ["Biss", "Stä+W6, PB 2."], ["Infrarotsicht", "Halbiert Beleuchtungsabzüge beim Angriff auf Gegner mit Wärmesignatur."], ["Rudeltaktik", "Stygische Höllenhunde addieren ihren Gang-Up-Bonus zum Schaden sowie den üblichen Bonus auf Kämpfen."], ["Geschwindigkeit", "W10 Sprintwürfel."]]}, {"n": "Strygoth", "k": "Dämonen", "w": 0, "s": ["SUP"], "p": 118, "bk": "sw_sup", "o": 2, "g": "Die Dunkle Brut", "d": ["Diese geflügelten Schrecken sind im Kampf grausam und berechnend und suchen sich zuerst nach Möglichkeit schwächere Gegner, Heiler und Unterstützer aus."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W10"], ["Stärke", "W12+2"], ["Verstand", "W6"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W4, Athletik W10, Einschüchtern W10, Heimlichkeit W10, Kämpfen W10, Provozieren W10, Wahrnehmung W6", "b": "6", "pa": "8", "ro": "17 (4)", "x": [["Handicaps", "Blutrünstig, Anfälligkeit für Naturgewalten (Licht)"], ["Talente", "Block, Raserei (Verb.), Superkräfte (8)"], ["Ausrüstung", "Keine."]], "sf": [["Rüstung +4", "Schuppenhaut."], ["Biss/Klauen", "Stä+W10, PB 4."], ["Flug", "Bewegungsweite 12."], ["Infrarotsicht", "Halbiert Beleuchtungsabzüge beim Angriff auf Gegner mit Wärmesignatur."], ["Schreckensstrahl (8)", "Dunkelheit. Athletik. Reichweite 12/24/48, Schaden 3W6, PB 4, FR 1.", 1], ["Größe 2", "3 m groß."], ["Zähigkeit +4", "Dicke, dichte Körper."]]}, {"n": "Himmlischer Schrecken", "k": "Dämonen", "w": 1, "s": ["SUP"], "p": 119, "bk": "sw_sup", "o": 2, "g": "Die Dunkle Brut", "d": ["Himmlische Schrecken sind die wütenden Schrecken der Heimatdimensionen der Dunklen Brut. Sie sind stark genug, es mit Helden kosmischer Stufe aufzunehmen, und ein Zirkel solcher Kreaturen reicht aus, um selbst ein Super-Team zu bedrohen.", "Himmlische Schrecken sind etwas wie riesige, schwebende Kraken. Sie dienen jedem Wesen, dem es gelungen ist, sie herbeizurufen – oder tun zumindest so. Ehrlich gesagt kann kein Sterblicher ihren unergründlichen Geist begreifen."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W12+6"], ["Stärke", "W12+12"], ["Verstand", "W8"], ["Willenskraft", "W12"]], "f": "Allgemeinwissen W12, Athletik W12, Einschüchtern W12, Heimlichkeit W10, Kämpfen W12+2, Provozieren W12, Wahrnehmung W10", "b": "6", "pa": "11", "ro": "32", "x": [["Handicaps", "Blutrünstig, Anfälligkeit für Naturgewalten (Licht)"], ["Talente", "Block (Verb.), Gegenangriff, Erstschlag, Mächtiger Hieb, Superkräfte (14), Rundumschlag (Verb.)"], ["Ausrüstung", "Keine."]], "sf": [["Wachsamkeit", "Ignoriert bis zu 5 Punkte Angriffsabzüge.", 1], ["Atmet nicht", "Wie die Kraft mit dem Modifikator Extrem.", 1], ["Zäh", "Schrecken erleiden keine Wunde durch zweimaliges Angeschlagen."], ["Schreckensstrahl", "Dunkelheit. Reichweite 12/24/48, Schaden 6W6, PB 8, FR 1. Nutzt Athletik."], ["Furcht –2", "Der Anblick der massigen, grotesken Gestalt eines Schreckens erfordert eine Furchtprobe mit –2."], ["Flug", "Bewegungsweite 12."], ["Infrarotsicht", "Halbiert Beleuchtungsabzüge beim Angriff auf Gegner mit Wärmesignatur."], ["Gedankenkontrolle", "Stark.", 1], ["Größe 13 (Gigantisch)", "Ein Himmlischer Schrecken ist so groß wie ein mammutgroßer Krake mit rund 40 m Durchmesser. Er hat drei zusätzliche Wunden, und seine Angriffe sind Schwere Waffen."], ["Schlagen", "Himmlische Schrecken ignorieren 4 Punkte Größenabzüge beim Angriff auf kleinere Kreaturen."], ["Tentakel", "Vier Tentakelaktionen, Reichweite 5, +2 Ringen, Klauenspitzen verursachen Stä+3W6 Schaden."], ["Zähigkeit +8 (8)", "Massige Gestalt."], ["Unaufhaltsam", "Der Schrecken erleidet durch jeden schädigenden Angriff höchstens eine Wunde (nach dem Aufnehmen), es sei denn, die Aktionskarte des Angreifers ist ein Joker."]]}, {"n": "Dark Star", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 120, "bk": "sw_sup", "o": 2, "d": ["Dr. Nicola-Jane Bartez war eine von Dr. Emil Munroes Kollegen (siehe Das Schwarze Loch, S. 107). Sie war auch verzweifelt in ihn verliebt, und als er seine bizarre Verwandlung durchmachte, eilte sie zu Hilfe. Die verzerrenden Auswirkungen des Mini-Schwarzen-Lochs wirkten bei ihr anders und verliehen ihr Macht über Licht und Dunkelheit, verdrehten aber auch ihren Verstand. Sie begleitet das Schwarze Loch oft bei seinen Amokläufen und sucht nach einem Heilmittel, das ihren Geliebten wieder in Fleisch verwandelt. Die beiden sind schrecklich und grausam gegenüber der „Intelligenzia“, die sie verspottete oder ihnen nun im Weg steht."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W10"], ["Stärke", "W8"], ["Verstand", "W12"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W4, Athletik W6, Fahren W6, Fokus W10, Heilen W10, Heimlichkeit W4, Kämpfen W8, Naturwissenschaften W12, Wahrnehmung W10, Überreden W4", "b": "6", "pa": "6", "ro": "7", "x": [["Machtniveau", "III"], ["Handicaps", "Auffälliges Aussehen (gemusterte Haut), Wahnvorstellungen (Schwer — hasst jeden, der das Schwarze Loch kritisiert oder sich ihm widersetzt), Skrupellos (Schwer)"], ["Talente", "Kampfreflexe, Gelehrter (Naturwissenschaften), Superkräfte (45)"], ["Ausrüstung", "Keine."]], "sf": [["Wachsamkeit (5)", "Stufe 2. Ignoriert 2 Punkte der Angriffsabzüge eines Gegners durch dessen Kräfte, Aktionen oder Fähigkeiten.", 1], ["Energiekontrolle (15)", "Dunkelheit. Zusätzlicher Machttyp (Licht). Flächeneffekt (GFS). Schwere Waffe. Macht.", 1], ["Umweltresistenz (4)", "Dunkelheit. Licht. Immunität.", 1], ["Flug (12)", "Schallgeschwindigkeit, –6 auf Treffer. Unbeholfen.", 1], ["Raumfahrer (3)", "Dunkler Stern kann im Weltraum überleben und ihre Kraft auf eine weitere Person ausdehnen. Übertragbar.", 1], ["Superattribut (6)", "Geschicklichkeit +2, Konstitution +1.", 1]]}, {"n": "Decay", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 121, "bk": "sw_sup", "o": 2, "d": ["Alastair Blake war ein Elitedieb, spezialisiert auf Industriespionage, meist für Hightech-Superschurken und deren Tech-Gangs. Vor einigen Jahren beauftragte ihn eine Gang, in eine Firma einzubrechen und eine neue Geheimtechnologie zu stehlen. Dabei erfuhr Alastair, dass das Ziel seines Diebstahls die „Methusalem-Formel“ war. Er hatte nie einen Auftrag gebrochen, doch wenn die Forschungsnotizen stimmten, würde ihn das Serum ewig leben lassen! Die Unsterblichkeit lockte. Alastair injizierte sich die einzige Probe. Schon nach Augenblicken erkannte er seinen Fehler. Der Prototyp funktionierte nicht. Stattdessen erzeugte er einen verderbenden Zeitstrom um das Subjekt. Nun altert jeder und alles, was der Dieb berührt, mit stark erhöhter Geschwindigkeit.", "Alastair wurde wahnsinnig durch die Unfähigkeit, einen anderen Menschen zu berühren, ohne ihn altern zu lassen, oder Essen zu sich zu nehmen, ohne dass es sauer und verfault schmeckt. Das Verderbnisfeld altert auch sein eigenes Fleisch, doch er hat entdeckt, dass das Absorbieren bestimmter Strahlungsarten seine Jugend wiederherstellt – für eine Weile. Alastair verstrickt sich oft in die Pläne anderer Hightech-Schurken und der Gang, die er verraten hat, auf der Suche nach einem Weg, den Methusalem-Effekt zu beenden und seine Menschlichkeit wiederzuerlangen."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W6"], ["Stärke", "W4"], ["Verstand", "W12"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W10, Athletik W10, Diebeskunst W10, Einschüchtern W6, Elektronik W10, Fahren W10, Fokus W10, Hacken W8, Heimlichkeit W6, Kämpfen W8, Provozieren W6, Wahrnehmung W8, Überreden W6", "b": "6", "pa": "7", "ro": "5", "x": [["Machtniveau", "II"], ["Handicaps", "Ehrenkodex, Alt (außer er hat kürzlich Strahlung absorbiert), Grimmig, Skrupellos (Leicht)"], ["Talente", "Nerven aus Stahl, Superkräfte (30)"], ["Ausrüstung", "Keine."]], "sf": [["Absorption (4)", "Strahlung. Übertragung.", 1], ["Verfall (4)", "Zeitverzerrung. Midas-Berührung. Stark. Verbunden mit Fernkampfangriff.", 1], ["Umweltresistenz (3)", "Strahlung. Immunität. Alastair ignoriert radioaktive Angriffe und Attacken.", 1], ["Parade +1 (1)", "Reflexe.", 1], ["Fernkampfangriff (8)", "Fokus. Reichweite 12/24/48, Schaden 4W6. Tödlich. (Chronalstoß.)", 1], ["Regeneration (5)", "Stufe 4 (einmal pro Stunde). Nachwachsen. Einschränkung (muss in den letzten 24 Stunden Strahlung absorbiert haben, um sie zu aktivieren).", 1], ["Teleportation (2)", "Bis zu 12“. Schnelle Teleportation.", 1], ["Übernatürliche Reflexe (3)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen.", 1]]}, {"n": "Electron", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 123, "bk": "sw_sup", "o": 2, "d": ["Carol Benchley ist eine versierte Computerhackerin, die in schlechte Gesellschaft geriet und anfing, Banken und Konzerne zu betrügen. Beim Einbruch in eine geheime Regierungseinrichtung entdeckte sie die Baupläne eines erstaunlichen Anzugs, der ihr die Kontrolle über Elektrizität verleiht. Sie stahl die Datei, löschte das Original und baute den Anzug. Nun überfällt sie Konzerne (und besonders Banken) als Electron – die „Geißel der Wirtschaft“.", "Carol hatte eine kurze Affäre mit dem Hackerkollegen Felix Mazetti (S. 114), doch ihre Rivalität führte zu einer unschönen Trennung, und nun sind die beiden erbitterte Feinde. Wenn jemand Mazettis Kraken-Syndikat angreifen will, ist Electron oft diejenige, die angerufen wird."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W6"], ["Stärke", "W6"], ["Verstand", "W10"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W8, Athletik W4, Diebeskunst W6, Fahren W6, Fokus W8, Hacken W12, Heimlichkeit W4, Kämpfen W6, Reparieren W10, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "5", "ro": "15 (10)", "x": [["Machtniveau", "III"], ["Defensen", "–3 (Fernkampf)"], ["Handicaps", "Gierig (Schwer), Kraftneutralisierung (Leicht — starke Magnete), Rachsüchtig (Schwer)"], ["Talente", "Beziehungen (Hacker), Gelehrter (Hacken und Reparieren), Superkräfte (45)"], ["Ausrüstung", "Elektrizitätskontroll-Anzug (siehe unten)."]], "sf": [["Rüstung +10 (4)", "Gerät (Elektroanzug).", 1], ["Wachsamkeit (2)", "Ignoriert 2 Punkte der Angriffsabzüge eines Gegners.", 1], ["Schadensfeld (8)", "Elektrizität. Schaden 3W6. Flächeneffekt (GFS). Gerät (Elektroanzug).", 1], ["Ausweichen –3 (3)", "–3, um von Fernkampfangriffen getroffen zu werden.", 1], ["Energiekontrolle (9)", "Elektrizität. Flächeneffekt (GFS). Aufladen. Darf die Kegelschablone nutzen. Gerät (Elektroanzug). Material erforderlich.", 1], ["Umweltresistenz (2)", "Elektrizität. Gerät (Elektroanzug). Immunität.", 1], ["Flug (3)", "Bewegungsweite 12 (13 km/h). Gerät (Elektroanzug).", 1], ["Schnittstelle (4)", "Codeknacker. Gerät (Elektroanzug). Schnell.", 1], ["Fernkampfangriff (10)", "Fokus. Reichweite 12/24/48, Schaden 5W6. Gerät (Elektroanzug). Schwere Waffe. (Elektroblitze.)", 1]]}, {"n": "Fantamu", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 124, "bk": "sw_sup", "o": 2, "d": ["Akira Yokohama war einst ein hochdekoriertes Mitglied der japanischen Spezialeinheiten. Dann schlug er einen Vorgesetzten und wurde unehrenhaft entlassen. Wütend schloss sich Akira der ehrwürdigen Kyoto-Yakuza an und stieg schnell zu ihrem bekanntesten Vollstrecker mit Superkräften auf. Akira weitet seine Operationen weltweit aus und setzt Banden von Gewöhnlichen Kriminellen (S. 100) oder die Purpurfaust (S. 116) ein, wenn talentiertere Hilfe nötig ist. Die Expansion bringt ihn häufig in Konflikt mit Red Dragon (S. 146) und Kraken (S. 114). Er ist ein kalter, skrupelloser Killer, aber sein einmal gegebenes Wort hält er."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W8"], ["Stärke", "W12"], ["Verstand", "W8"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W4, Athletik W8, Diebeskunst W10, Einschüchtern W6, Fahren W10, Fokus W6, Heimlichkeit W6, Kämpfen W12+2, Provozieren W6, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "12", "ro": "12 (4)", "x": [["Machtniveau", "II"], ["Defensen", "–2 (Fernkampf)"], ["Handicaps", "Arrogant, Vorsichtig, Ehrenkodex, Loyal, Skrupellos (Schwer)"], ["Talente", "Block, Chi, Konter, Erstschlag (Verb.), Raserei, Kühler Kopf, Kampfkünstler (Verb.), Kampfkunstmeister, Superkräfte (30), Lieblingswaffe (Katana)"], ["Ausrüstung", "Schwere Kampfrüstung (+4*), Katana (Stä+3W6+1)."]], "sf": [["Wachsamkeit (4)", "Ignoriert 4 Punkte der Angriffsabzüge eines Gegners.", 1], ["Ausweichen –2 (2)", "–2, um von Fernkampfangriffen getroffen zu werden.", 1], ["Nahkampfangriff (4)", "Stä+2W6.", 1], ["Parade +2 (2)", "Kampfkunsttraining.", 1], ["Superattribut (4)", "Stärke +2.", 1], ["Supertalent (6)", "Block, Raserei, Kühler Kopf.", 1], ["Superfertigkeit (3)", "Kämpfen +2, Athletik +1.", 1], ["Zähigkeit +2 (2)", "Konditionierung.", 1], ["Übernatürliche Reflexe (3)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen.", 1]]}, {"n": "The Fixer", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 125, "bk": "sw_sup", "o": 2, "d": ["Liza Sutton ist die Tochter des ursprünglichen Fixers, alias Miss Mechanical. Sie ist ein wissenschaftliches Genie, das praktisch alles Vorstellbare erschaffen kann. Ihre Dienste sind allerdings nicht billig, und wer mit ihr zu tun hatte, weiß, dass man sie nie hintergehen sollte. Fixer ist nicht nur ein Schurke „hinter den Kulissen“ – sie nutzt ihre Geräte, um Geld und Teile für weitere Gadgets zu stehlen.", "Der Fixer führt oft eine Tech-Gang (S. 169) und schert sich wenig um deren Wohl oder Sicherheit. Der Fixer beschäftigt, verbündet sich mit oder manipuliert zahlreiche Superschurken für ihre Pläne, darunter: Alchemist (S. 102), Flux (S. 126), Nocturne (S. 157), Stealth (S. 166) und Whirling Dervish (S. 176)."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W6"], ["Stärke", "W6"], ["Verstand", "W12"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W6, Diebeskunst W8, Fahren W6, Fokus W10, Heimlichkeit W4, Kämpfen W8, Naturwissenschaften W12, Reparieren W12+1, Schießen W8, Wahrnehmung W8, Überreden W4", "b": "6", "pa": "6", "ro": "17 (12)", "x": [["Machtniveau", "III"], ["Defensen", "–5 (Fernkampf)"], ["Handicaps", "Gierig (Schwer), Fies, Skrupellos (Schwer), Rachsüchtig (Schwer)"], ["Talente", "Bastler, Kühler Kopf (Verb.), McGyver, Superkräfte (45)"], ["Ausrüstung", "Mikro-Werkzeugkasten, Teile für Reparaturen."]], "sf": [["Rüstung +12 (5)", "Gerät (Kraftfeldgürtel).", 1], ["Ausweichen –5 (4)", "–5, um von Fernkampfangriffen getroffen zu werden. Gerät (Ablenkungsfeld am Kraftfeldgürtel).", 1], ["Flug (5)", "Bewegungsweite 24 (26 km/h). Gerät (Repulsorgürtel). Wendig.", 1], ["Fernkampfangriff (10)", "Schießen. Reichweite 12/24/48, Schaden 5W6. Gerät (Blasterpistole).", 1], ["Superattribut (11)", "Geschicklichkeit +1, Verstand +3, Stärke +1, Konstitution +1. Gerät (Muskelaktuatoren).", 1], ["Superwissenschaft (4)", "Kann einen Benny für ein Machtkunststück ausgeben, ohne die neue Kraft auf eine ihrer bestehenden Kräfte stützen zu müssen.", 1], ["Superfertigkeit (3)", "Reparieren +2, Naturwissenschaften +1.", 1]]}, {"n": "Flux", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 126, "bk": "sw_sup", "o": 2, "d": ["Carla Boardman war eine frustrierte Wissenschaftlerin in einer staatlichen Forschungseinrichtung. Eines Tages wurde das Labor vom Schwarzen Loch angegriffen, und Carla wurde von den seltsamen Gravitationsstrahlen des Schurken getroffen. Als sich ihr Körper in den Ereignishorizont streckte, explodierte im Labor etwas und überschüttete sie mit kraftvoller Energie und Chemikalien. Als sich der Neonrauch verzog, konnte Carla ihren Körper dehnen und sogar einen knetartigen Zustand annehmen. Von da an war sie als Flux bekannt.", "Flux arbeitet oft für den Fixer und nutzt ihre Fähigkeiten, um sich irgendwo einzuschleichen und Technologie zu stehlen. Sie hasst das Schwarze Loch (S. 107) und Dark Star (S. 120) abgrundtief."], "a": [["Geschicklichkeit", "W12"], ["Konstitution", "W10"], ["Stärke", "W6"], ["Verstand", "W8"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W6, Fahren W6, Fokus W8, Heilen W6, Heimlichkeit W6, Kämpfen W8, Naturwissenschaften W8, Provozieren W8, Wahrnehmung W8, Überreden W6", "b": "8", "pa": "6", "ro": "12", "x": [["Machtniveau", "III"], ["Defensen", "–5 (Fernkampf)"], ["Handicaps", "Gierig (Leicht), Anfälligkeit für Naturgewalten (Kälte), Rachsüchtig (Leicht)"], ["Talente", "Flink, Raserei, Schnell, Rundumschlag (Verb.), Superkräfte (45), Den Treffer einstecken"], ["Ausrüstung", "Keine."]], "sf": [["Veränderte Form (10)", "Gummiartiger Körper. Greifer. Reichweite +4. Zähflüssig. Nachgeben.", 1], ["Ausweichen –5 (5)", "–5, um von Fernkampfangriffen getroffen zu werden.", 1], ["Umweltresistenz (4)", "Elektrizität. Biologisch. Erde. Metall.", 1], ["Nahkampfangriff (10)", "Stä+3W6, Schwere Waffe, Zerschmettern.", 1], ["Superattribut (10)", "Geschicklichkeit +3, Konstitution +2.", 1], ["Superfertigkeit (1)", "Kämpfen +1.", 1], ["Zähigkeit +5 (5)", "Gummiartiger Körper.", 1]]}, {"n": "Ghoul", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 127, "bk": "sw_sup", "o": 2, "d": ["Jeremiah Chesterton III wurde in Reichtum geboren und verbrachte seine Tage in verschwenderischem Prunk, umgeben vom Besten, was das Leben zu bieten hat. Die „unsichtbaren Menschen“, die für ihn arbeiteten, kümmerten ihn wenig. Einer dieser „Unsichtbaren“ wurde wegen eines geringfügigen Vergehens entlassen und sann auf Rache; er verfluchte Chesterton mit nagendem Hunger und einem ausgedörrten Körper. Als letzten Schliff poetischer „Gerechtigkeit“ wurde Chesterton wirklich unsichtbar.", "Nun schleicht der ehemalige Debütant durch die Schatten und muss wie ein Ghul aus der Folklore Aas fressen. Er kann sich nicht sichtbar machen, kann seine unheilige Gier nie stillen und lässt seine Wut an jedem aus, dem er begegnet."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W10"], ["Stärke", "W10"], ["Verstand", "W8"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W8, Athletik W6, Diebeskunst W6, Einschüchtern W6, Fahren W6, Fokus W8, Heimlichkeit W6, Kämpfen W8, Okkultismus W6, Wahrnehmung W8, Überleben W8, Überreden W4", "b": "8", "pa": "6", "ro": "9", "x": [["Machtniveau", "II"], ["Handicaps", "Blutrünstig, Auffälliges Aussehen (skelettiert), Tick (immer hungrig, frisst nur Aas), Hässlich (Schwer), Verwundbarkeit (Leicht — Licht)"], ["Talente", "Kampfreflexe, Rückzug, Raserei, Superkräfte (30)"], ["Ausrüstung", "Keine."]], "sf": [["Geschärfte Sinne (2)", "Geruch. Restlichtsicht.", 1], ["Unsichtbarkeit (6)", "Dauerhaft.", 1], ["Springen (3)", "4“ senkrecht, 8“ waagerecht. Tod von oben.", 1], ["Nahkampfangriff (7)", "Stä+2W6. Klauen (+W6).", 1], ["Betäuben (1)", "Bedingt durch Kämpfen (Nahkampfangriff, Klauen). Berührung erforderlich. Stark.", 1], ["Supertalent (2)", "Kampfreflexe.", 1], ["Superfertigkeit (1)", "Heimlichkeit +1.", 1], ["Untot (8)", "+2 Robustheit; +2 beim Erholen von Angeschlagen; atmet nicht; immun gegen Krankheit und Gift; kein zusätzlicher Schaden durch Gezielte Angriffe; ignoriert 1 Stufe Wundabzüge.", 1]]}, {"n": "Gladius", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 128, "bk": "sw_sup", "o": 2, "d": ["Markus Caputo war ein erfolgreicher Kämpfer im illegalen „Super-Grubenkampfring“. Ein wohlhabender Sponsor erkannte sein Talent, baute ihm eine Gladiatorenrüstung und warb ihn als Vollstrecker an. „Gladius“ hat sich seither anderen kriminellen Unternehmungen zugewandt, genießt es aber, andere Supers zu Einzelkämpfen herauszufordern – oft auf Kosten der Mission."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W12+2"], ["Stärke", "W12+4"], ["Verstand", "W6"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W10, Einschüchtern W10, Fahren W8, Fokus W8, Heimlichkeit W6, Kämpfen W12+2, Provozieren W6, Wahrnehmung W6, Überreden W4", "b": "6", "pa": "17", "ro": "19 (10)", "x": [["Machtniveau", "II"], ["Handicaps", "Arrogant, Tick (muss als Aktion „Daumen hoch“ oder „Daumen runter“ für jeden zeigen, der zuschaut, bevor er entscheidet, was er mit einem besiegten Gegner tut), Rachsüchtig (Schwer)"], ["Talente", "Block (Verb.), Gegenangriff, Rückzug, Erstschlag, Superkräfte (30)"], ["Ausrüstung", "Gladiatorenrüstung (siehe Kraft Rüstung), mittlerer Schild (+2 Parade), Gladius (Stä+4W6, Schwere Waffe), Netz (siehe S. 16)."]], "sf": [["Rüstung +10 (4)", "Gerät (Gladiatorenrüstung).", 1], ["Nahkampfangriff (6)", "Stä+2W6. Spezialwaffe (Gladius, +W6, Gerät, Schwere Waffe).", 1], ["Parade +4 (4)", "Training.", 1], ["Superattribut (7)", "Stärke +3, Konstitution +1. Gerät (Rüstung).", 1], ["Superfertigkeit (3)", "Kämpfen +3.", 1], ["Betäuben (3)", "Berührung erforderlich. Stark. (Schwertschlag.)", 1], ["Übernatürliche Reflexe (2)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen. Gerät (Sensoren in der Gladiatorenrüstung).", 1]]}, {"n": "Goliath", "k": "Monster", "w": 1, "s": ["SUP"], "p": 129, "bk": "sw_sup", "o": 2, "d": ["Das als Goliath bekannte Wesen lebt irgendwo tief im Marianengraben. Sie ist ein gewaltiges, echsenartiges Wesen mit Atomatem und titanischen Klauen. Goliath hat eine unheimliche Ähnlichkeit mit dem fiktiven Godzilla, ist aber definitiv kein Freund der Menschheit. Wenn Goliath oder ihresgleichen auftaucht, ruft die bedrohte Nation normalerweise die Doom Guard.", "Andere Riesenmonster: Superhelden werden häufig gerufen, um gegen turmhohe Monstrositäten zu kämpfen, die Städte bedrohen. Solche Kreaturen sind in ihrem Erscheinungsbild einzigartig – von enormen radioaktiven Echsen bis zu turmhohen Robotern. Manche haben mächtige Fernkampfangriffe, manche können fliegen, und manche bestehen vielleicht aus Umweltverschmutzung oder Schleim. Nutze Goliaths Profil als Grundlage für diese Wesen und füge dann weitere Superkräfte hinzu, wie es zur jeweiligen Kreatur passt. Riesenmonster werden oft von kleineren Kreaturen begleitet, vielleicht ihren Kindern, oder einfach von Kreaturen, die vor dem Zorn des Titanen fliehen. Hinweis: Für wirklich gigantische Kreaturen sieh dir unser anderes Buch Dawn of the Daikaiju! an."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W12+2"], ["Stärke", "W12+12"], ["Verstand", "W6 (A)"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W4, Athletik W8, Einschüchtern W10, Heimlichkeit W4, Kämpfen W10, Schießen W4, Wahrnehmung W6, Überreden W4", "b": "30", "pa": "7", "ro": "31 (10)", "x": [["Ausrüstung", "Keine."]], "sf": [["Rüstung +10", "Schwere Rüstung. (Schuppenhaut)"], ["Biss/Klauen", "Stä+2W12, PB 10."], ["Furcht", "Der Anblick eines Riesenmonsters verursacht beim ersten Sehen eine Furchtprobe."], ["Stampfen", "Höchstens einmal pro Zug können Riesenmonster in einer Großen Flächenschablone stampfen. Wer nicht ausweicht, erleidet Stä + Größe Schaden."], ["Fernkampfangriff", "Atomatem. Athletik. Reichweite 24/48/96, Schaden 5W10, PB 20. Flächeneffekt (GFS). Schwere Waffe."], ["Größe +12 (Gigantisch)", "Riesenmonster sind über dreißig Meter hoch. Sie haben Schwere Rüstung, ihre Angriffe zählen als Schwere Waffen, und sie können drei zusätzliche Wunden einstecken."], ["Schlagen", "Manche Riesenmonster sind im Kampf gegen kleinere Beute geübt. Dann ignorieren sie bis zu 4 Punkte Größenmodifikatoren."], ["Unaufhaltsam", "Der Schurke erleidet durch jeden schädigenden Angriff höchstens eine Wunde (nach dem Aufnehmen), es sei denn, die Aktionskarte des Angreifers ist ein Joker."]]}, {"n": "Grappler", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 130, "bk": "sw_sup", "o": 2, "d": ["Grappler, alias Donnie Pitzoni, wäre in den Reihen der Superschurken ein Niemand, wenn er allein operieren würde. Er kann nur einen Trick, doch genau das macht ihn für andere Schurken nützlich. Er wird dafür bezahlt, Ziele für Entführungen einzufangen oder Gegner zu fesseln, damit mächtigere Schurken sie windelweich prügeln können, ohne die eigene Haut zu riskieren. Grappler ist ein ausgemachter Mistkerl, der es genießt, seinen mächtigeren Feinden und Verbündeten auf die Nerven zu gehen."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W8"], ["Stärke", "W8"], ["Verstand", "W6"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W4, Athletik W8, Diebeskunst W8, Fahren W6, Fokus W4, Heimlichkeit W8, Kämpfen W8, Provozieren W10, Schießen W12, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "6", "ro": "6", "x": [["Machtniveau", "I"], ["Handicaps", "Große Klappe, Monologisierer, Phobie (Leicht — Krankenhäuser)"], ["Talente", "Akrobat, Rückzug, Erniedrigen, Der Beste (Verstricken), Superkräfte (15)"], ["Ausrüstung", "Enterhakenpistole (siehe unten)."]], "sf": [["Verstricken (8)", "Flächeneffekt (GFS). Alternatives Attribut (Schießen). Gerät (Enterhakenpistole). Stark.", 1], ["Superattribut (2)", "Geschicklichkeit +1.", 1], ["Superfertigkeit (1)", "Schießen +1.", 1], ["Schwingen (2)", "Bewegungsweite 12. Gerät (Enterhakenpistole). Starke Leine (900 kg).", 1], ["Übernatürliche Reflexe (2)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen. Gerät (Enterhakenpistole).", 1]]}, {"n": "Gravel", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 131, "bk": "sw_sup", "o": 2, "d": ["Gravel war Gefangener in einem der härtesten Gefängnisse der Galaxis. Er brach aus, stahl ein Schiff und stürzte vor einigen Jahren auf der Erde ab. Seither versucht er, den winzigen Menschen seine Überlegenheit zu beweisen, doch mehrere Niederlagen gegen die Verteidiger der Erde haben ihn in den Untergrund gezwungen – im wahrsten Sinne des Wortes. Gravel ist eine riesige Masse beweglicher Felsen mit glühenden roten Augen. Seine gewaltige Größe und Stärke erlauben es ihm, Tod und Verwüstung zu bringen, und sein Auftauchen gilt bei den Super-Teams der Welt als höchste Priorität."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W12"], ["Stärke", "W12+5"], ["Verstand", "W4"], ["Willenskraft", "W4"]], "f": "Allgemeinwissen W4, Athletik W8, Einschüchtern W10, Fliegen W8, Fokus W10, Heimlichkeit W6, Kämpfen W10, Wahrnehmung W4, Überreden W4", "b": "6", "pa": "7", "ro": "34 (16)", "x": [["Machtniveau", "IV"], ["Handicaps", "Fremdgestalt (lebender Fels), Verpeilt, Analphabet"], ["Talente", "Kampfreflexe, Schwer zu töten, Nerven aus Stahl (Verb.), Superkräfte (60)"], ["Ausrüstung", "Keine."]], "sf": [["Absorption (2)", "Erde.", 1], ["Rüstung +16 (12)", "Schwere Rüstung.", 1], ["Graben (4)", "Bewegungsweite 6. Blockbuster. Tunnelbauer.", 1], ["Erdbeben (4)", "Stark.", 1], ["Wachstum (13)", "Stufe 5. Größe 5 (4,5 m groß, Groß, +1 Wunde). Dauerhaft.", 1], ["Materiekontrolle (11)", "Erde. Flächeneffekt (GFS). Macht. Material erforderlich.", 1], ["Nahkampfangriff (9)", "Stä+3W6, Zerschmettern.", 1], ["Zähigkeit +5 (5)", "Felsige Gestalt.", 1]]}, {"n": "The Green Goddess", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 132, "bk": "sw_sup", "o": 2, "d": ["Rose Gardner war eine Umweltaktivistin, bevor sie mit dem geheimnisvollen Orb von Gaia (siehe unten) in Kontakt kam, einem mächtigen magischen Artefakt, das sie in eine halb menschliche, halb pflanzliche Monstrosität verwandelte. Nun ist sie darauf aus, die Menschheit für ihre hemmungslose Zerstörung der natürlichen Umwelt zu vernichten. In ihren wahnsinnigsten und rücksichtslosesten Momenten sucht die Grüne Göttin nach einem Verwüstungssamen (siehe S. 180). Das ist natürlich reiner Wahnsinn, da er zerstören wird, was sie zu beschützen sucht. Doch wenn sie besonders wütend ist, gewinnt Roses Wunsch die Oberhand, alles zu zerstören und das Universum „neu beginnen“ zu lassen. Wenn man ihr eine unglaubliche Tat menschlicher Güte zeigen kann, übernimmt womöglich ihre sterbliche Psyche wieder die Kontrolle und überredet sie, die selbstzerstörerische Suche aufzugeben."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W12"], ["Stärke", "W12+2"], ["Verstand", "W8"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W6, Einschüchtern W8, Fahren W6, Fokus W12, Heimlichkeit W10, Kämpfen W10, Provozieren W6, Wahrnehmung W6, Überreden W4", "b": "8", "pa": "8", "ro": "16 (8)", "x": [["Machtniveau", "IV"], ["Handicaps", "Fremdgestalt (halb Mensch, halb Pflanze), Zwei linke Hände, Blutrünstig, Abhängigkeit (Sonnenlicht), Anfälligkeit für Naturgewalten (Feuer)"], ["Talente", "Block, Kampfreflexe, Ausweichen, Erstschlag, Flink, Raserei (Verb.), Kühler Kopf, Rundumschlag (Verb.), Starker Wille, Superkräfte (60)"], ["Ausrüstung", "Keine."]], "sf": [["Rüstung +8 (8)", "Schwere Rüstung.", 1], ["Graben (2)", "Bewegungsweite 8.", 1], ["Verfall (8)", "Ätzender Pflanzensaft. Flächeneffekt (GFS). Stark.", 1], ["Furchtlos (2)", "Immun gegen Furcht und Einschüchtern. (Seelenlos.)", 1], ["Materiekontrolle (12)", "Pflanzen. Flächeneffekt (GFS). Macht.", 1], ["Nahkampfangriff (8)", "Stä+2W6, Schwere Waffe.", 1], ["Fernkampfangriff (13)", "Fokus. Schaden 5W6. Nur Kegelschablone. Streuung. (Dornensalve.)", 1], ["Reichweite (1)", "Die Göttin kann ihre langen Glieder ausstrecken.", 1], ["Superattribut (6)", "Stärke +3.", 1]]}, {"n": "Pod", "k": "Monster", "w": 0, "s": ["SUP"], "p": 133, "bk": "sw_sup", "o": 2, "g": "Die Grüne Göttin", "d": ["Pods sind die Leutnants der Grünen Göttin. Jeder ist eine Verbindung aus dem Willen der Göttin und dem Orb von Gaia, der sie erschaffen hat. Sie sind empfindungsfähig, intelligent und gerissen, und jede Manifestation trägt die Erinnerungen derer weiter, die vor ihr kamen. Pods können telepathisch mit der Grünen Göttin überall auf dem Planeten kommunizieren sowie mit allen Spores im Umkreis von 1,6 km."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W12"], ["Stärke", "W10"], ["Verstand", "W10"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W8, Einschüchtern W10, Fokus W10, Heimlichkeit W6, Kriegskunst W12, Kämpfen W10, Provozieren W8, Wahrnehmung W10, Überreden W4", "b": "6", "pa": "7", "ro": "13", "x": [["Handicaps", "Fremdgestalt (Pflanze), Zwei linke Hände, Anfälligkeit für Naturgewalten (Feuer)"], ["Talente", "Anführer, Gemeinsames Band, Inbrunst, Haltet die Stellung!, Inspirieren"], ["Ausrüstung", "Keine."]], "sf": [["Verstricken", "Flächeneffekt (MFS). Tödlich (3W6). Stark."], ["Umweltresistenz", "Pflanzen. Flächeneffekt (MFS). Immunität."], ["Materiekontrolle", "Pflanzen. Flächeneffekt (GFS)."], ["Keine lebenswichtigen Organe", "Der Pod besteht aus Pflanzenmaterial."], ["Fernkampfangriffe", "Dornensalve. Fokus. Reichweite 12/24/48, Schaden 4W6, PB 4, Kegelschablone, Tödlich, Streuung."], ["Regeneration", "Einmal pro Runde. Einschränkung (muss als Aktion einen Spore berühren und absorbieren (töten), um zu regenerieren)."], ["Zähigkeit +5", "Dicke, schwammige Haut."]]}, {"n": "Spore", "k": "Monster", "w": 0, "s": ["SUP"], "p": 133, "bk": "sw_sup", "o": 2, "g": "Die Grüne Göttin", "d": ["Spores sind die mächtigen, aber größtenteils geistlosen Diener der Grünen Göttin. Sie sind bemerkenswert stark und geschickt, haben aber keinen wahren Willen und keine Empfindungsfähigkeit. Das macht sie zu perfekten Dienern für die gewalttätigen Feldzüge der Göttin gegen die Menschheit. Spores können telepathisch mit anderen Pods oder Spores im Umkreis von 1,6 km kommunizieren."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W10"], ["Stärke", "W12+2"], ["Verstand", "W4"], ["Willenskraft", "W4"]], "f": "Allgemeinwissen W4, Athletik W6, Einschüchtern W10, Fokus W6, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W6, Überreden W4", "b": "6", "pa": "6", "ro": "13", "x": [["Handicaps", "Fremdgestalt (Pflanze), Zwei linke Hände, Verpeilt, Analphabet, Anfälligkeit für Naturgewalten (Feuer)"], ["Talente", "Beidhändig, Schwer zu töten"], ["Ausrüstung", "Keine."]], "sf": [["Umweltresistenz", "Pflanzen. Flächeneffekt (MFS). Immunität."], ["Nahkampfangriff", "Stä+2W6."], ["Keine lebenswichtigen Organe", "Der Spore ist eine lebende Pflanze."], ["Größe 1", "Spores sind 2,4 m groß."], ["Zähigkeit +5", "Dicke, schwammige Haut."]]}, {"n": "Grenadier", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 134, "bk": "sw_sup", "o": 2, "d": ["Grenadier ist ein Söldner auf Abruf und bringt jedem Auftraggeber ein beeindruckendes Granatenarsenal und eine kampferprobte Truppe von Söldnern ohne Superkräfte mit. Grenadier spricht nie über seine Vergangenheit, doch es gibt reichlich Hinweise, dass er in einer oder mehreren Armeen der Welt gedient hat. Im Kampf trägt er gepanzerte Kampfkleidung sowie ein Patronenband voller Granaten und einen Granatwerfer.", "Hinweis: Grenadier kann mit seinem Granatwerfer normale Granaten wie in seiner Ausrüstung aufgeführt abfeuern oder Negations- und Betäubungsgranaten über seine Kraft."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W10"], ["Stärke", "W6"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W6, Diebeskunst W10, Fahren W10, Fokus W10, Heimlichkeit W8, Kriegskunst W10, Kämpfen W10, Schießen W12+2, Wahrnehmung W10, Überleben W6, Überreden W4", "b": "6", "pa": "7", "ro": "15 (8)", "x": [["Machtniveau", "II"], ["Handicaps", "Arrogant, Fies, Skrupellos, Rachsüchtig (Schwer)"], ["Talente", "Kampfreflexe, Anführer, Haltet die Stellung!, Meisterschütze, Superkräfte (30)"], ["Ausrüstung", "Gepanzerter Anzug (siehe unten), Granatwerfer (Reichweite 24/48/96, Schaden 4W8, FR 1, MFS, Schwere Waffe)."]], "sf": [["Rüstung +8 (2)", "Gerät (gepanzerter Anzug). Teilschutz (–1).", 1], ["Wachsamkeit (2)", "Ignoriert 3 Punkte der Angriffsabzüge eines Gegners. Gerät (Helm-Display).", 1], ["Geschärfte Sinne (1)", "Adleraugen, Restlichtsicht. Gerät (Helm-Display).", 1], ["Negation (8)", "Flächeneffekt (GFS). Bedingt durch Schießen (Granatwerfer). Gerät (Granate). Volles Spektrum. Stark.", 1], ["Betäuben (5)", "Flächeneffekt (GFS). Bedingt durch Schießen (Granatwerfer). Gerät (Granate). Stark.", 1], ["Superattribut (6)", "Geschicklichkeit +1, Konstitution +2.", 1], ["Superfertigkeit (2)", "Schießen +2.", 1], ["Schwingen (2)", "Starke Leine (900 kg). Gerät (Enterhaken).", 1], ["Übernatürliche Reflexe (2)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen. Gerät (Helm-Display).", 1]]}, {"n": "Halifax", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 135, "bk": "sw_sup", "o": 2, "d": ["Halifax ist Asmodeus’ ältester Kriegsherr, und derjenige, an den sich der Eroberer am häufigsten um Rat wendet. Der General stammte aus einer der ersten Eroberungen Asmodeus’ und ist damit vielleicht so alt wie Stygias überlieferte Existenz. Unendlich gerissen erkannte Halifax, dass es zwecklos war, gegen den Dunklen Overlord zu kämpfen, und schwor ihm stattdessen Treue. Im Gegenzug verlieh Asmodeus dem alten Mann einen mächtigen Körper und zauberische Kräfte, die im bekannten Universum kaum ihresgleichen finden. Halifax trägt eine dunkelblaue Kapuzenrobe, die von unheimlichen Siegeln leuchtet. Sein Gesicht ist tiefblauschwarz, mit leuchtenden gelben Augen und blutigen Zähnen."], "a": [["Geschicklichkeit", "W12"], ["Konstitution", "W12"], ["Stärke", "W12"], ["Verstand", "W12"], ["Willenskraft", "W12"]], "f": "Allgemeinwissen W6, Athletik W6, Einschüchtern W8, Fokus W10, Heimlichkeit W8, Kriegskunst W12+2, Kämpfen W12, Okkultismus W21+2, Provozieren W10, Wahrnehmung W10, Zaubern W12+2, Überreden W4", "b": "6", "pa": "10", "ro": "17", "x": [["Machtniveau", "IV"], ["Defensen", "–4 (Fernkampf)"], ["Handicaps", "Fies, Monologisierer, Schwur (Schwer — Asmodeus dienen)"], ["Talente", "Arkaner Hintergrund (Magie), Anführer, Befehlsgewalt, Haltet die Stellung!, Superkräfte (60), Taktiker"], ["Mächte", "Bannen, Barriere, Blenden, Eigenschaft erhöhen/senken, Verwirrung, Dunkelsicht, Arkanes entdecken/verbergen, Bannen, Wahrsagung, Machtpunkte entziehen, Elementarmanipulation, Fernsicht, Fliegen, Illusion, Licht/Dunkelheit, Trägheit/Beschleunigung, Zuschlagen, Geräusch/Stille, Sprachen sprechen, Betäuben, Verbündeten beschwören, Telekinese, Gabe des Kriegers (Machtpunkte: 60)"], ["Ausrüstung", "Keine."]], "sf": [["Alterslos (3)", "Sehr alt.", 1], ["Verdammnis", "Halifax kehrt in den Abgrund zurück, wenn er Kampfunfähig ist."], ["Ausweichen –4 (4)", "–4, um von Fernkampfangriffen getroffen zu werden.", 1], ["Umweltresistenz (3)", "Magie. Immunität.", 1], ["Unsichtbarkeit (8)", "–4 auf Wahrnehmung oder Angriff.", 1], ["Parade +2 (2)", "Erfahrener Kämpfer.", 1], ["Fernkampfangriff (13)", "Zaubern. Reichweite 12/24/48 oder Kegelschablone, Schaden 5W6. (Dunkle Energiesalven.)", 1], ["Größe +1", "Halifax ist 2,4 m groß."], ["Superattribut (12)", "Geschicklichkeit +2, Stärke +2, Konstitution +2.", 1], ["Superfertigkeit (2)", "Zaubern +2.", 1], ["Superzauberei (4)", "Dämonische Magie.", 1], ["Zähigkeit +8 (8)", "Dichter, fremdartiger Körper.", 1], ["Unaufhaltsam", "Der Schurke erleidet durch jeden schädigenden Angriff höchstens eine Wunde (nach dem Aufnehmen), es sei denn, die Aktionskarte des Angreifers ist ein Joker."]]}, {"n": "Hammer", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 136, "bk": "sw_sup", "o": 2, "d": ["Dmitri Rasputinovichs Schwester Olga wurde vom russischen Verbrechersyndikat Red Dragon (S. 146) auf eine Droge namens „Malevolent“ gebracht. Die meisten werden einfach hoffnungslos abhängig, doch Olga wurde zur Superschurkin namens Sickle (S. 163). Wohin Olga geht, geht Dmitri, und um mitzuhalten, wusste er, dass er ebenfalls Malevolent nehmen musste. Er kannte die Risiken, hoffte aber, dass die Familiengene, die bei Olga gewirkt hatten, auch ihn durchbringen würden. Sie taten es. Er erlangte übermenschliche Stärke und Zähigkeit und schlug vor, dass er und seine Schwester „Superschurken“-Namen annehmen. Sie einigten sich auf Hammer und Sickle, ließen Spezialwaffen anfertigen und sind nun Red Dragons beste Vollstrecker. Hammer geht im Kampf gern der größten Bedrohung Auge in Auge entgegen, während seine Schwester in Hit-and-Run-Angriffen an den Rändern herumtänzelt."], "a": [["Geschicklichkeit", "W4"], ["Konstitution", "W12"], ["Stärke", "W12+2"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W8, Einschüchtern W8, Fahren W6, Fokus W6, Heimlichkeit W6, Kämpfen W8, Wahrnehmung W6, Überleben W8, Überreden W4", "b": "6", "pa": "7", "ro": "14", "x": [["Machtniveau", "II"], ["Handicaps", "Arrogant, Loyal, Fies"], ["Talente", "Kräftig, Nerven aus Stahl (Verb.), Superkräfte (30), Rundumschlag, Den Treffer einstecken"], ["Ausrüstung", "Vorschlaghammer (Stä+W10+3W6, Parade –1, Reichweite 1, Schwere Waffe)."]], "sf": [["Zäh (2)", "Ein zweites Ergebnis Angeschlagen verursacht keine Wunde.", 1], ["Springen (3)", "4“ senkrecht, 8“ waagerecht. Tod von oben.", 1], ["Nahkampfangriff (8)", "Stä+2W6. Spezialwaffe (Vorschlaghammer, +W6, Gerät, Schwere Waffe, Zerschmettern).", 1], ["Parade +2 (2)", "Geschick und Training.", 1], ["Superattribut (10)", "Stärke +3, Konstitution +2.", 1], ["Zähigkeit +5 (5)", "Gehärtete Haut.", 1]]}, {"n": "Hangman", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 137, "bk": "sw_sup", "o": 2, "d": ["Bert Nichols wurde zum Selbstjustiz-Kämpfer als Reaktion auf die wachsende Kriminalität in seiner Nachbarschaft. Anfangs fing er Verbrecher nur ein und übergab sie der Polizei, doch die Gerichte erwiesen sich als ineffizient, und die Gauner waren binnen Tagen wieder auf der Straße. Bert änderte seine Vorgehensweise, baute sein leichtes Nylonlasso und wurde zum Hangman. Leider wurde Hangmans Hang zur Gerechtigkeit zur Besessenheit. Heute sieht er jedes Verbrechen – selbst Müll auf die Straße zu werfen – mit Missfallen und bestraft jeden Gesetzesbrecher, dem er begegnet. Er nutzt seine „Schlinge der Gerechtigkeit“, um seine Feinde zu fesseln und dann hinzurichten."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W8"], ["Stärke", "W10"], ["Verstand", "W8"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W6, Athletik W12+4, Einschüchtern W10, Fahren W8, Fokus W6, Heimlichkeit W10, Kämpfen W10, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "9", "ro": "6", "x": [["Machtniveau", "II"], ["Handicaps", "Wahnvorstellungen (Leicht — er ist Richter, Geschworene und Henker), Skrupellos (Schwer), Rachsüchtig (Schwer)"], ["Talente", "Akrobat, Rückzug, Erstschlag, Schnell, Superkräfte (30)"], ["Ausrüstung", "Schlinge (siehe unten)."]], "sf": [["Wachsamkeit (3)", "Ignoriert 3 Punkte der Angriffsabzüge eines Gegners.", 1], ["Verstricken (8)", "Alternatives Attribut (Athletik). Gerät (Seil und Schlinge). Tödlich (Schaden 3W6). Stark.", 1], ["Parade +2 (2)", "Wirbelndes Seil.", 1], ["Fernkampfangriff (6)", "Athletik. Reichweite 12/24/48, Schaden 3W6. (Peitschenhieb.)", 1], ["Superattribut (4)", "Stärke +2.", 1], ["Superfertigkeit (6)", "Athletik +4, Kämpfen +2.", 1], ["Schwingen (1)", "Gerät (Schlinge).", 1]]}, {"n": "Hellcat", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 138, "bk": "sw_sup", "o": 2, "d": ["Emily Ellis erfuhr früh im Leben, dass sie magische Talente hatte. Sie war etwas Besonderes und entwickelte ihre beachtliche magische Fähigkeit unter der Anleitung des heldenhaften Meistermagiers Bewitcher, wobei sie lernte, ihre Kräfte zu bündeln und zu fokussieren. Sie kämpften an der Seite der Doom Guard, doch mit der Zeit begehrte sie gegen ihre Rolle als zweitmächtigste Zauberin der Welt auf. Ihre Eifersucht führte sie zu Torheit. Und diese wiederum zur Verdammnis. Sie schloss einen Handel mit Asmodeus, um mehr Macht als ihr Mentor zu erlangen. Asmodeus willigte ein, jedoch zu einem schrecklichen Preis, und schleppte Emily nach Stygia.", "Die höllische Verwandlung, die sie durchlitt, hat sie nahezu immun gegen Schaden gemacht, während ihre Bindung an das stygische Reich es ihr erlaubt, feurige dämonische Kobolde zu beschwören und Höllenfeuer zu entfesseln. Der Bewitcher folgte ihrer Spur in die öden Ebenen Stygias, doch das Mädchen, das er kannte, war fort. An ihrer Stelle stand Hellcat, ein Wesen aus Feuer und Wut. Entschlossen, sie zu erlösen, opferte er sich, um Hellcat zur Erde zurückzubringen, wo die Doom Guard Asmodeus’ Griff auf sie brach. Hellcat kämpft nun an ihrer Seite zum Wohl der Menschheit. Sie wird von einem brennenden Rachedurst getrieben, ihre eigenen teuflischen Kräfte sind eine ständige, bittere Erinnerung an den schrecklichen Handel, den sie einging … und den Preis, den er forderte."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W8"], ["Stärke", "W4"], ["Verstand", "W10"], ["Willenskraft", "W12"]], "f": "Allgemeinwissen W4, Athletik W8, Einschüchtern W8, Fokus W10, Heimlichkeit W4, Kämpfen W8, Okkultismus W10, Wahrnehmung W10, Überreden W4", "b": "6", "pa": "7", "ro": "15", "x": [["Machtniveau", "III"], ["Handicaps", "Pech, Feind (Schwer — Halifax), Rachsüchtig (Leicht), Verwundbarkeit (Schwer — Silber)"], ["Talente", "Attraktiv, Block, Ausweichen, Superkräfte (45), Schnell"], ["Ausrüstung", "Keine."]], "sf": [["Umweltresistenz (3)", "Feuer. Immunität.", 1], ["Flug (6)", "Bewegungsweite 24 (26 km/h). Wendig.", 1], ["Heilung (1)", "Einschränkung (Hellcat erleidet jedes Mal eine Stufe Erschöpfung, wenn sie diese Kraft nutzt).", 1], ["Handlanger (11)", "Bis zu drei Höllenfledermäuse. Herbeirufbar. Superkräfte (Wachsamkeit 3; Ausweichen –3; Flug Bewegungsweite 24, Wendig; Nahkampfangriff Stä+W6, Biss +W4).", 1], ["Fernkampfangriff (9)", "Reichweite 12/24/48, Schaden 3W6, PB 4. Darf die Kegelschablone nutzen. Schwere Waffe. Tödlich. (Höllenfeuersalven.)", 1], ["Regeneration (5)", "Infernalische Regeneration.", 1], ["Superzauberei (3)", "Rückschlag.", 1], ["Zähigkeit +9 (9)", "Undurchdringliches Fleisch.", 1]]}, {"n": "Hell’s Angel", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 139, "bk": "sw_sup", "o": 2, "d": ["Steve Nitro war ein aufstrebender Stern im Motorradrennsport, als ein Rivale sein Bike sabotierte. Was Nitro ausbremsen sollte, endete in einem schrecklichen Unfall – und seinem Tod. An den Toren der Hölle – denn er war „an den anderen Ort“ gelangt – schloss Nitro einen Handel mit Asmodeus. Er würde dem Herrscher des Abgrunds auf der Erde dienen, wenn er ins Leben zurückkehrte. Asmodeus erkannte Nitros Potenzial, verlieh ihm Kräfte und ein fantastisches „Höllenbike“ und schickte ihn als mörderischen Herold und Vollstrecker zurück in die sterbliche Welt.", "Nitro streift nun nach Belieben umher und schwelgt in seinem neuen Leben und seinen fantastischen Fähigkeiten. Wenn Asmodeus ihn jedoch ruft, um eine dunkle Aufgabe zu erledigen, muss er gehorchen oder sofort in die Eingeweide der Hölle zurückkehren."], "a": [["Geschicklichkeit", "W12"], ["Konstitution", "W12"], ["Stärke", "W12+2"], ["Verstand", "W8"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W6, Fahren W12, Fokus W10, Heimlichkeit W4, Kämpfen W10, Okkultismus W6, Reparieren W6, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "7", "ro": "15 (4)", "x": [["Machtniveau", "III"], ["Handicaps", "Auffälliges Aussehen (Skelett in Bikerleder), Skrupellos (Schwer), Kraftneutralisierung (geweihter Boden), Schwur (Schwer — den Herrschern der Hölle dienen)"], ["Talente", "Raserei, Superkräfte (45), Rundumschlag"], ["Ausrüstung", "Schwere Körperpanzerung (Weste, +4*), Motorrad (Höllenbike, siehe unten)."]], "sf": [["Umweltresistenz (3)", "Feuer. Immunität.", 1], ["Furcht –2 (4)", "Stark.", 1], ["Furchtlos (2)", "Nichts schreckt den „Höllen-Killer“.", 1], ["Nahkampfangriff (7)", "Stä+3W6, Schwere Waffe.", 1], ["Fernkampfangriff (10)", "Fokus. Reichweite 12/24/48, Schaden 3W6, FR 1, PB 8. (Höllenfeuer.)", 1], ["Superattribut (6)", "Stärke +2, Konstitution +1.", 1], ["Fahrzeug (10)", "Höllenbike. Größe 0, Handhabung +2, Höchstgeschwindigkeit 130 km/h, Robustheit 19 (12), Besatzung 1. Geschlossen. Handhabung +2. Superkräfte (30), siehe unten.", 1], ["Zähigkeit +3 (3)", "Höllische Energie.", 1], ["Rüstung +10 (5)", "Höllische Machart.", 1], ["Schadensfeld (13)", "Feuer. Schaden 4W6. Mittlere Flächenschablone. Selektiv.", 1], ["Umweltresistenz (3)", "Feuer. Immunität.", 1], ["Geschwindigkeit (9)", "Bewegungsweite 180 (385 km/h), –2 auf Treffer während der Bewegung.", 1]]}, {"n": "Hex", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 140, "bk": "sw_sup", "o": 2, "d": ["Shirley Banks wusste schon immer, dass sie seltsam war. Genauer gesagt wusste sie, dass die Welt um sie herum seltsam wurde, wenn sie ängstlich, aufgeregt oder wütend war. Ein unglücklicher Streit mit ihrer Mutter löste ihre Wut aus – und einen schrecklichen Unfall, der beinahe ihre ganze Nachbarschaft zerstörte. Shirley lief am nächsten Tag von zu Hause weg. Die nächsten Jahre lebte sie auf den Straßen von Legacy City unter dem Namen Hex. Die seltsamen Ereignisse und unerklärlichen Vorkommnisse, die sie umgaben, nahmen über die Jahre zu. Die KI der Doom Guard, Cassandra, entdeckte diese Anomalien und sagte eine Katastrophe voraus, wenn die Doom Guard sich nicht einmischte. Warden nahm Kontakt auf und gewann die aufgewühlte Jugendliche nach und nach für sich.", "Blackguard hat umfangreiche Testreihen zu Hex’ Fähigkeiten durchgeführt und festgestellt, dass ihre Kräfte auf Wahrscheinlichkeit beruhen und die Chance erhöhen oder senken, dass etwas geschieht. Es ist eine mächtige, aber gefährliche Fähigkeit, die sie nur unsicher im Griff hat, doch mit Hilfe der Doom Guard und Wardens lenkender Hand glaubt das Team, dass Hex eines Tages die mächtigste von allen werden könnte."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W6"], ["Stärke", "W6"], ["Verstand", "W6"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W8, Diebeskunst W6, Fokus W10, Heimlichkeit W8, Kämpfen W6, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "9", "ro": "5", "x": [["Machtniveau", "IV"], ["Defensen", "–3 (Fernkampf)"], ["Handicaps", "Impulsiv, Arm, Rücksichtslos, Beschämt (Leicht — Superschurken-Vater)"], ["Talente", "Elan, Rückzug, Großes Glück, Superkräfte (60)"], ["Ausrüstung", "Keine."]], "sf": [["Wachsamkeit +3 (3)", "Glückstreffer.", 1], ["Ausweichen –3 (5)", "Ablenken.", 1], ["Duplizierung (6)", "Beförderung.", 1], ["Heilung (13)", "Heilen. Erschöpfung. Erfrischen. Wiederherstellung. Wiederauferstehung. Berührung erforderlich.", 1], ["Pech bringen (6)", "Größeres Pech.", 1], ["Fehlfunktion (3)", "Es war schon immer dazu bestimmt zu zerbrechen.", 1], ["Negation (8)", "Volles Spektrum. Stark.", 1], ["Parade +4 (6)", "Ablenken.", 1], ["Teleportation (7)", "Andere teleportieren.", 1], ["Übernatürliche Reflexe (3)", "Deus ex Machina.", 1]]}, {"n": "Hunter", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 141, "bk": "sw_sup", "o": 2, "d": ["Wellington Fairbanks ist seit seiner Kindheit besessen davon, Tiere zu sammeln, sei es für Zoos oder als Trophäen an seiner Wand. Sein Ziel ist es, so viele ungewöhnliche oder gefährliche Kreaturen wie möglich zu fangen oder zu töten. Besonders fasziniert ihn jedes tierähnliche Wesen mit Superkräften. Er jagt keine „Menschen“, scheint aber zu glauben, dass jedes tierähnliche Wesen, selbst empfindungsfähige Individuen wie Lycanthropus (S. 149), Mako (S. 151) oder Ratkin (S. 161), Freiwild sind."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W8"], ["Stärke", "W8"], ["Verstand", "W12"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W6, Diebeskunst W10, Elektronik W6, Fahren W8, Fokus W6, Heimlichkeit W12, Kämpfen W8, Schießen W12+2, Wahrnehmung W8, Überleben W10, Überreden W6", "b": "8", "pa": "10", "ro": "8 (2)", "x": [["Machtniveau", "II"], ["Defensen", "–5 (Fernkampf)"], ["Handicaps", "Arrogant, Ehrenkodex, Tick (muss seine Beute anpirschen)"], ["Talente", "Aufmerksamkeit, Flink, Kühler Kopf, Meisterschütze, Naturbursche, Ruhige Hände, Superkräfte (30)"], ["Ausrüstung", "Körperpanzerung (+2*), Impulsgewehr (Reichweite 20/40/80, Schaden 3W6, PB 4), Machete (Stä+W4)."]], "sf": [["Wachsamkeit (5)", "Ignoriert 5 Punkte der Angriffsabzüge eines Gegners.", 1], ["Scharfschütze (3)", "Wellington addiert +W10 Schaden auf alle Feuerwaffenangriffe. Tödlich.", 1], ["Ausweichen –5 (5)", "–5, um von Fernkampfangriffen getroffen zu werden.", 1], ["Geschärfte Sinne (3)", "Adleraugen. Gehör. Geruch.", 1], ["Immun gegen Gift/Krankheit (2)", "Wellington hat seine Widerstandskraft aufgebaut.", 1], ["Nahkampfangriff (2)", "Stä+W6.", 1], ["Parade +4 (4)", "Training.", 1], ["Superfertigkeit (3)", "Schießen +3.", 1], ["Übernatürliche Reflexe (3)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen.", 1]]}, {"n": "Huntsman", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 142, "bk": "sw_sup", "o": 2, "d": ["Huntsman ist der beste Auftragsmörder des Spiders (S. 165). Wenn er in Aktion gerufen wird, stirbt irgendwo jemand. Niemand kennt Huntsmans richtigen Namen, doch er dient dem Spider seit Jahren loyal, ohne je Befehle zu hinterfragen oder die Wünsche seines Chefs unerfüllt zu lassen. Sein Akzent soll australisch sein, doch nur wenige, die ihn sprechen hörten, haben überlebt. Huntsman arbeitet nur für den Spider, doch manchmal verleiht der Meister seinen Killer an Verbündete. Der unsichtbare Attentäter tötet bevorzugt mit seinem charakteristischen Titandolch, setzt aber jedes nötige Mittel ein, um seine Ziele zu erreichen."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W10"], ["Stärke", "W10"], ["Verstand", "W8"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W10, Athletik W10, Diebeskunst W12, Fahren W10, Fokus W8, Heimlichkeit W12, Kämpfen W12, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "13", "ro": "11 (4)", "x": [["Machtniveau", "II"], ["Defensen", "–2 (Fernkampf)"], ["Handicaps", "Vorsichtig, Skrupellos (Schwer), Schwur (Schwer — dem Spider dienen), Gesucht (Schwer — fast jede Strafverfolgungsbehörde des Planeten)"], ["Talente", "Block (Verb.), Gegenangriff, Ausweichen, Erstschlag, Kühler Kopf, Schnell, Gassenwissen, Superkräfte (30), Lieblingswaffe (Titandolch)"], ["Ausrüstung", "Schwere Kampfrüstung (+4*), vergifteter Titandolch (Stä+W4+2W6, siehe unten), Enterhaken-Automat, Dietriche, Nachtsichtbrille (kein Abzug bei Düsteren oder Dunklen Bedingungen)."]], "sf": [["Ausweichen –2 (2)", "–2, um von Fernkampfangriffen getroffen zu werden.", 1], ["Unsichtbarkeit (7)", "–4 auf Treffer. Gerät (Lichtbrechungsanzug).", 1], ["Nahkampfangriff (7)", "Stä+2W6, PB 4, Schwere Waffe.", 1], ["Parade +2 (2)", "Training.", 1], ["Gift (1)", "Tödlich. Stark. Bedingt durch Kämpfen mit Titandolch. Gerät (Titandolch). Berührung erforderlich.", 1], ["Superattribut (6)", "Stärke +2, Konstitution +1.", 1], ["Superfertigkeit (5)", "Kämpfen +2, Heimlichkeit +2, Diebeskunst +1.", 1]]}, {"n": "The Ice Queen", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 143, "bk": "sw_sup", "o": 2, "d": ["Natalie Adams arbeitete als Nachwuchsforscherin bei einer Kryotechnikfirma. Als die Fördergelder zugunsten eines anderen Unternehmens versiegten, nahm Natalie die Sache selbst in die Hand. Sie brach ein und versuchte, den Rivalen zu sabotieren, doch der Angriff ging schief, und sie fiel in einen Bottich mit einer prototypischen gefrorenen Flüssigkeit. Sie tauchte als Ice Queen wieder auf. Natalie ist jung und nutzt ihre Kraft vor allem zum persönlichen Vorteil. Sie geht rücksichtslos mit ihrer unrechtmäßigen Beute um und ist stets auf der Suche nach einem schnellen Coup, um ihr Versteck aufzufüllen."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W10"], ["Stärke", "W6"], ["Verstand", "W10"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W8, Athletik W8, Diebeskunst W8, Fahren W6, Fokus W10, Heimlichkeit W8, Kämpfen W10, Naturwissenschaften W8, Provozieren W8, Wahrnehmung W6, Überreden W6", "b": "12", "pa": "7", "ro": "13 (6 )", "x": [["Machtniveau", "III"], ["Defensen", "–3 (Fernkampf)"], ["Handicaps", "Gierig (Leicht), Anfälligkeit für Naturgewalten (Feuer), Rachsüchtig (Leicht)"], ["Talente", "Entwaffnen (Verb.), Superkräfte (45)"], ["Ausrüstung", "Keine."]], "sf": [["Rüstung +6 (2)", "Aktivierung erforderlich.", 1], ["Schadensfeld (5)", "3W6. Flächeneffekt (MFS). Tödlich.", 1], ["Ausweichen –3 (3)", "–3, um von Fernkampfangriffen getroffen zu werden. Intelligenz und Geschick.", 1], ["Energiekontrolle (12)", "Kälte. Flächeneffekt (GFS). Macht.", 1], ["Verstricken (9)", "Flächeneffekt (GFS). Stark. (Friert Ziele fest.)", 1], ["Flug (4)", "Bewegungsweite 12 (13 km/h). (Sie gleitet auf Eis, das sich unter ihr bildet.)", 1], ["Verlangsamen (6)", "Zusätzliche Empfänger (+4). Bedingt durch Energiekontrolle.", 1], ["Supertalent (4)", "Wendiger Rückzug.", 1]]}, {"n": "Jackdaw", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 144, "bk": "sw_sup", "o": 2, "d": ["Pedro Rivera ist süchtig nach glänzenden Dingen, besonders nach Schmuck. Nach dem College-Abschluss konstruierte er ein Exoskelett mit Flügeln und kräftigen Klauen und etablierte sich als Jackdaw – nach der Dohle. Pedro stieg schnell vom Kleindiebstahl auf und nutzt seine Flugfähigkeit, um Zugang zu privaten Tresoren, Museumsoberlichtern und anderen erhöhten Einstiegspunkten zu erhalten. Pedro ist außerdem rachsüchtig und skrupellos. Helden, die versuchen, ihn aufzuhalten, werden in schwindelnde Höhen getragen – und fallen gelassen."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W8"], ["Stärke", "W12+2"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W10, Athletik W10, Diebeskunst W10, Elektronik W10, Fahren W6, Fokus W8, Heimlichkeit W10, Kämpfen W10, Naturwissenschaften W10, Reparieren W12, Wahrnehmung W6, Überreden W4", "b": "6", "pa": "7", "ro": "10 (4)", "x": [["Machtniveau", "II"], ["Defensen", "–4 (Fernkampf)"], ["Handicaps", "Neugierig, Gierig (Schwer), Fies, Skrupellos (Schwer), Rachsüchtig (Schwer)"], ["Talente", "Entwaffnen (Verb.), Erstschlag, Schnell, Superkräfte (30)"], ["Ausrüstung", "Kampfrüstung (+4*)."]], "sf": [["Ausweichen –4 (3)", "–4, um von Fernkampfangriffen getroffen zu werden. Gerät (Sensoren im Anzug, verbunden mit dem Helm-Display).", 1], ["Flug (7)", "Bewegungsweite 90 (97 km/h), –1 auf Treffer im Flug. Gerät (Flügelanzug).", 1], ["Nahkampfangriff (8)", "Stä+2W6. Klauen (+W6, PB 4). Gerät (Anzug).", 1], ["Betäuben (2)", "Berührung erforderlich. Stark. Gerät (defensives Elektrofeld im Anzug).", 1], ["Superattribut (7)", "Stärke +4. Gerät (Anzug).", 1], ["Wirbelwind (3)", "Wirbelnde Flügel.", 1]]}, {"n": "Kamchatka", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 145, "bk": "sw_sup", "o": 2, "d": ["Igor Ermakov war ein skrupelloses Mitglied der russischen Speznas. Er wurde wegen Kriegsverbrechen verurteilt, zum Tode verurteilt, hingerichtet und begraben. So behauptete es zumindest die Regierung. In Wahrheit hatte man Igor die Wahl gelassen: der Tod oder die freiwillige Teilnahme an einem neuen Programm für verbesserte Soldaten – Projekt Kamtschatka, benannt nach den großen, grizzlyartigen Bären der Halbinsel Kamtschatka. DNA dieser Tiere wurde zusammen mit anderen unbekannten Reagenzien einer Reihe von Sträflingen injiziert, um stärkere Soldaten zu schaffen, die es mit der wachsenden Zahl übermenschlicher Wesen der Welt aufnehmen könnten. Die meisten Probanden starben, doch Igor durchlief eine verblüffende Verwandlung und wurde zur Verkörperung der Größe und Stärke des Bären und seiner eigenen brutalen Wut.", "Igor schlachtete seine Aufseher ab und wütete blutig, bis er besiegt und eingesperrt wurde. Kamchatka entkam schließlich und arbeitet gelegentlich als Muskelpaket für finsterere Superschurken. Er ist ein gerissener Killer, der seine Beute gern in Fallen und Sackgassen treibt, bevor er mit seinen wilden Zähnen und Klauen angreift."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W12"], ["Stärke", "W12+4"], ["Verstand", "W8"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W4, Allgemeinwissen W6, Athletik W10, Elektronik W6, Fahren W8, Fokus W8, Heimlichkeit W10, Kriegskunst W8, Kämpfen W12+2, Wahrnehmung W10, Überleben W10, Überreden W6", "b": "8", "pa": "9", "ro": "17", "x": [["Machtniveau", "III"], ["Handicaps", "Auffälliges Aussehen (Bär), Skrupellos (Schwer), Phobie (Schwer — Nadeln)"], ["Talente", "Aufmerksamkeit, Berserker, Kräftig, Kampfreflexe, Rückzug, Erstschlag, Flink, Mächtiger Hieb, Superkräfte (45)"], ["Ausrüstung", "Keine."]], "sf": [["Wachsamkeit (3)", "Ignoriert bis zu 3 Punkte der Angriffsabzüge eines Gegners.", 1], ["Wachstum (4)", "Stufe 2 (+2 auf Größe, Stärke und Robustheit). Dauerhaft.", 1], ["Zäh (2)", "Ein zweites Ergebnis Angeschlagen verursacht keine Wunde.", 1], ["Geschärfte Sinne (1)", "Geruch.", 1], ["Nahkampfangriff (15)", "Stä+3W6. Klauen (+2W6, PB 8).", 1], ["Superattribut (8)", "Stärke +4, Konstitution +2.", 1], ["Supertalent (6)", "Berserker, Erstschlag, Flink.", 1], ["Zähigkeit +6 (6)", "Dicke Haut.", 1]]}, {"n": "Katyusha", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 146, "bk": "sw_sup", "o": 2, "d": ["Aleksandr „der Drache“ Dragovich gründete in den 1950ern die kriminelle Organisation Red Dragon (Krasni Drakon). Seine Vollstrecker, die „Drachengarde“, waren ein Trupp loyaler Soldaten in sowjetischen Kraftrüstungen aus dem Zweiten Weltkrieg. Aleksandr und die meisten der Drachengarde starben vor einem Jahrzehnt im Kampf gegen die V’sori-Invasion, und nun ist nur noch einer von ihnen übrig – der Veteran Sergei Dmitriov. Dmitriov übernahm, was von Red Dragon übrig war, und versucht, es mit Hilfe seiner brillanten Verlobten und Aleksandrs Urenkelin Veronika langsam wieder zusammenzufügen. Sergei legt noch immer seine abgenutzte Kampfrüstung an, wenn Rivalen oder superkräftige Gutmenschen ihn herausfordern. Sein Rufname ist „Katyusha“, nach den gefürchteten mobilen Raketenwerfern des Zweiten Weltkriegs."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W10"], ["Stärke", "W12+6"], ["Verstand", "W6"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W6, Athletik W6, Einschüchtern W8, Fokus W12, Heimlichkeit W8, Kämpfen W8, Reparieren W6, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "7", "ro": "13 (6)", "x": [["Machtniveau", "III"], ["Handicaps", "Arrogant, Fies, Skrupellos (Schwer), Hässlich (Schwer)"], ["Talente", "Block, Kühler Kopf, Meisterschütze, Bedrohlich, Ruhige Hände, Superkräfte (45), Der Beste (Fernkampfangriff)"], ["Ausrüstung", "Gepanzerter Kampfanzug (siehe unten)."]], "sf": [["Rüstung +6 (8)", "Schwere Rüstung. Gerät (gepanzerter Anzug). Versiegelt.", 1], ["Nahkampfangriff (9)", "Stä+3W6, PB 6, Gerät (Kraftfäustlinge), Schwere Waffe.", 1], ["Fernkampfangriff (15)", "Schießen. Reichweite 24/48/96, Schaden 5W6, FR 2. Gerät (schultermontierter Raketenwerfer). Schwere Waffe. Tödlich. Reichweite.", 1], ["Superattribut (13)", "Stärke +7. Gerät (Anzug).", 1]]}, {"n": "Kilowatt", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 147, "bk": "sw_sup", "o": 2, "d": ["Fred Nox wusste es besser, als bei einem Gewitter Telefonleitungen zu reparieren, aber er war im Verzug, und seine Chefs saßen ihm im Nacken, damit die Arbeit fertig wurde. Fred erinnert sich kaum an den Blitz, der in den Telefonmast einschlug, an dem er arbeitete, aber er erinnert sich an den sengenden Schmerz und den Geruch verbrennenden Fleisches. Fred starb an diesem Tag nicht, aber er veränderte sich. Nun ist er sein eigener Chef. Nun ist er jemand Wichtiges, jemand Gefürchteter. Nun ist er Kilowatt – der elektrisch geladene Superschurke."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W10"], ["Stärke", "W6"], ["Verstand", "W8"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W6, Athletik W4, Einschüchtern W8, Fahren W6, Fokus W10, Heimlichkeit W4, Kämpfen W8, Reparieren W6, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "6", "ro": "7", "x": [["Machtniveau", "III"], ["Handicaps", "Skrupellos (Leicht), Anfälligkeit für Naturgewalten (Wasser)"], ["Talente", "Kampfreflexe, Nerven aus Stahl (Verb.), Kühler Kopf, Superkräfte (45)"], ["Ausrüstung", "Keine."]], "sf": [["Fernkampfangriff (14)", "Reichweite 12/24/48, Schaden 4W6, FR 2. Wuchtig. Schwere Waffe. (Elektroblitz.)", 1], ["Schadensfeld (2)", "Elektrizität. Stufe 2. Schaden 3W6.", 1], ["Energiekontrolle (5)", "Elektrizität.", 1], ["Umweltresistenz (3)", "Elektrizität. Immunität.", 1], ["Kraftfeld (10)", "Stufe 5. +5 Robustheit. Verteidiger (GFS), Mobil.", 1], ["Flug (6)", "Bewegungsweite 45 (48 km/h).", 1], ["Telekinese (5)", "Stä W8. Statische Energie.", 1]]}, {"n": "Knave of Clubs", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 148, "bk": "sw_sup", "o": 2, "d": ["Jack Blunt, alias Knave of Clubs, ist ein Vollstrecker für verschiedene Gangs in Star City. Seine Waffe der Wahl ist ein Betäubungsknüppel, den er vor einigen Jahren dem Sonderkommando für Superkraft-Verbrechen abgenommen hat. Eine Reporterin der Lokalzeitung nannte Jack in einem ihrer Artikel einen „Knave“ (Schurken). Er hielt einen „Knave“ für eine Art Adligen und nahm den Namen als eigenen an. Bisher hatte keiner seiner Kumpane den Mut, ihn zu korrigieren."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W12"], ["Stärke", "W12"], ["Verstand", "W4"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W4, Athletik W8, Einschüchtern W6, Fahren W6, Fokus W6, Heimlichkeit W8, Kämpfen W10, Wahrnehmung W4, Überreden W6", "b": "6", "pa": "8", "ro": "15", "x": [["Machtniveau", "I"], ["Handicaps", "Arrogant, Gierig (Leicht)"], ["Talente", "Kräftig, Schläger, Rückzug, Superkräfte (15), Lieblingswaffe (club)"], ["Ausrüstung", "Betäubungsknüppel (Stä+W4, siehe S. 16)."]], "sf": [["Nahkampfangriff (4)", "Stä+2W6.", 1], ["Superattribut (6)", "Stärke +2, Konstitution +1.", 1], ["Zähigkeit +5 (5)", "Starker Körper und viel Selbstvertrauen.", 1]]}, {"n": "Lycanthropus", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 149, "bk": "sw_sup", "o": 2, "d": ["Leo Wolfcastle wuchs in New York City auf und las „The Tomb of Dracula“, „Werewolf by Night“ und andere Horrorcomics. Später, während des Studiums, ließen ihn mehrere persönliche Tragödien die Macht suchen, von der er in diesen warnenden Geschichten gelesen hatte. Er reiste nach Transsilvanien und fand schließlich, wonach er suchte. Leo durchsuchte alte Ruinen in den kalten Bergen, als er sich verirrte und von einem Werwolfrudel gejagt wurde. Er flehte die Kreaturen um Macht an, und aus irgendeinem seltsamen Grund wurde sie ihm gewährt.", "Nun streift Lycanthropus durch die Welt und verkauft seine Macht an jeden, der ihm etwas Interessantes bietet oder Helden zum Kämpfen. Seine Regeneration gibt ihm großes Selbstvertrauen, daher sagt er selten Nein zu einer Mission, solange sie gut bezahlt wird oder er seine Macht gegen einen würdigen Gegner einsetzen kann."], "a": [["Geschicklichkeit", "W12"], ["Konstitution", "W10"], ["Stärke", "W12+4"], ["Verstand", "W8"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W12, Fahren W4, Fokus W6, Heimlichkeit W12, Kämpfen W12, Naturwissenschaften W4, Okkultismus W6, Wahrnehmung W6, Überleben W10, Überreden W6", "b": "8", "pa": "8", "ro": "18", "x": [["Machtniveau", "IV"], ["Handicaps", "Arrogant, Gierig (Leicht), Fies, Verwandlung (Leicht — Leo kann sich als Aktion von einem Menschen in einen Werwolf verwandeln), Verwundbarkeit (Schwer — Silber)"], ["Talente", "Kräftig, Flink, Raserei (Verb.), Schnell, Superkräfte (60)"], ["Ausrüstung", "Keine."]], "sf": [["Wachsamkeit (5)", "Ignoriert bis zu 5 Punkte der Angriffsabzüge eines Gegners.", 1], ["Geschärfte Sinne (3)", "Gehör. Restlichtsicht. Geruch.", 1], ["Wachstum (6)", "Stufe 2 (+2 auf Größe, Stärke und Robustheit).", 1], ["Nahkampfangriff (19)", "Stä+3W6. Biss (+2W6, PB 4). Klauen (+2W6, PB 4).", 1], ["Regeneration (8)", "Fokusprobe, um jede Runde eine Wunde zu heilen (zwei mit einer Steigerung). Nachwachsen. Einschränkung (kann durch Säure, Feuer oder Silber verursachten Schaden nicht regenerieren).", 1], ["Superattribut (4)", "Geschicklichkeit +1, Stärke +1.", 1], ["Supertalent (4)", "Raserei (Verb.).", 1], ["Zähigkeit +8 (8)", "Dicke, kräftige Gestalt.", 1], ["Übernatürliche Reflexe (3)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen.", 1]]}, {"n": "Magnetron", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 150, "bk": "sw_sup", "o": 2, "d": ["Simon Gallowham ist schon ein paar Mal um den Block gekommen. Das Magnetron-Kostüm entwarf er erstmals in den Fünfzigern als Ingenieurstudent. Während einer glorreichen, fast 40 Jahre währenden Superschurken-Karriere wurde Magnetron zum bekannten Namen. Er tötete nie, verpasste seinen Feinden aber bei seinen zahlreichen Plänen so manche Abreibung. Er war so oft im Gefängnis und wieder draußen, dass er die meisten Richter beim Vornamen kannte. Magnetron starb im Gefängnis, doch wenige Tage später erhob sich sein Kostüm von selbst und suchte Rache an allen, die „ihn“ je besiegt hatten. Manche sagen, der Anzug werde von einer künstlichen Intelligenz gesteuert, die Simon in seinen letzten Tagen schuf, doch in Wahrheit ist es der wahnsinnige Geist des Schöpfers, der die Maschine belebt."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W10"], ["Stärke", "W12"], ["Verstand", "W8"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W6, Athletik W4, Einschüchtern W10, Elektronik W6, Fahren W4, Fokus W10, Heimlichkeit W4, Kämpfen W10, Naturwissenschaften W6, Reparieren W6, Wahrnehmung W4, Überreden W4", "b": "6", "pa": "7", "ro": "18 (9)", "x": [["Machtniveau", "III"], ["Handicaps", "Fremdgestalt (Roboter), Tick (kann sich nicht entscheiden, ob er der echte Geist Gallowhams oder eine KI ist)"], ["Talente", "Superkräfte (45)"], ["Ausrüstung", "Magnetron ist seine eigene Ausrüstung!"]], "sf": [["Rüstung +9 (9)", "Schwere Rüstung.", 1], ["Konstrukt (6)", "+2 beim Erholen von Angeschlagen, ignoriert 1 Punkt Wundabzüge, atmet nicht und isst nicht und ist immun gegen Krankheit und Gift, verblutet nicht, und Wunden werden mit Reparieren statt Heilen entfernt, ohne „Goldene Stunde“. Abhängigkeit (Elektrizität).", 1], ["Wachstum (4)", "Stufe 2 (+2 auf Größe, Stärke und Robustheit). Dauerhaft.", 1], ["Nahkampfangriff (12)", "Stä+3W6. Klauen (+2W6, Schwere Waffe).", 1], ["Fernkampfangriff (14)", "Fokus. Reichweite 12/24/48, Schaden 5W6, PB 2. Schwere Waffe. (Laser.)", 1]]}, {"n": "Mako", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 151, "bk": "sw_sup", "o": 2, "d": ["Hamilton Smythe, der Spider (S. 165), entdeckte in uralten lemurischen Ruinen eine fortschrittliche Energiequelle und stellte ein Söldnerteam zusammen, um sie zu bergen. Die Atlanteaner fingen sie ab, und nach der Schlacht lag Paul Kruger im Sterben. Was man hat, das hat man, dachte der Spider. Er wusch Kruger das Gehirn, sodass er die Atlanteaner für sein Schicksal verantwortlich machte, und bot ihm dann eine Chance auf Leben – und Rache. Kruger wurde zu einer aquatischen Waffe gemacht, die der Spider gegen die Atlanteaner einsetzen konnte, wann immer sie sich ihm widersetzten. Kruger ist noch immer schlau und gerissen, doch sobald er „Blut riecht“, ist er rücksichtslos und blutrünstig."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W10"], ["Stärke", "W12"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W4, Athletik W12, Diebeskunst W6, Einschüchtern W6, Fahren W6, Fokus W8, Heimlichkeit W8, Kämpfen W8, Wahrnehmung W6, Überleben W6, Überreden W4", "b": "6", "pa": "6", "ro": "8", "x": [["Machtniveau", "II"], ["Handicaps", "Blutrünstig, Abhängigkeit (Salzwasser), Arm, Hässlich (Schwer), Skrupellos (Schwer), Rachsüchtig (Schwer)"], ["Talente", "Kräftig, Berserker, Entwaffnen (Verb.), Schwer zu töten, Superkräfte (30)"], ["Ausrüstung", "Keine."]], "sf": [["Tierkontrolle (7)", "Sieben Punkte an Kreaturen. Telepathische Verbindung. Große Einschränkung (nur Haie).", 1], ["Wasserlebewesen (2)", "Mako kann im Wasser nicht ertrinken und bewegt sich beim Schwimmen mit voller Bewegungsweite.", 1], ["Furcht –2 (4)", "Stark.", 1], ["Geschärfte Sinne (1)", "Adleraugen, Restlichtsicht, Geruch. Einschränkung (wirkt nur unter Wasser).", 1], ["Nahkampfangriff (10)", "Stä+2W6. Biss (+2W6, PB 2, Schwere Waffe).", 1], ["Superattribut (6)", "Stärke +2, Konstitution +1.", 1]]}, {"n": "Medusa", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 152, "bk": "sw_sup", "o": 2, "d": ["Athena Minios stammt von der antiken Medusa ab! Sie hat keine Schlangen als Haare, doch ihr Blick kann ihre Opfer zu Stein erstarren lassen! Athenas Familie hat im Lauf der Zeit Schätze gehortet (besonders sehr lebensechte Statuen!) und betreibt einen großen, äußerst profitablen Schwarzmarkt für Antiquitäten. Athenas Rolle im Familiengeschäft ist die Beschaffung. Sie reist um die Welt und beraubt neu entdeckte Gräber, Museen und Privatsammlungen, wofür die Familie gerade einen Käufer findet. Sie hat sogar den Spider (S. 165) bestohlen – ein Fehltritt, für den sie bald zahlen dürfte."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W10"], ["Stärke", "W10"], ["Verstand", "W10"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Allgemeinwissen W6, Athletik W6, Diebeskunst W10, Elektronik W6, Fahren W6, Fokus W10, Heimlichkeit W10, Kämpfen W10, Schießen W10, Wahrnehmung W8, Überreden W10", "b": "6", "pa": "12", "ro": "11 (2)", "x": [["Machtniveau", "II"], ["Defensen", "–5"], ["Handicaps", "Gierig (Schwer), Kraftneutralisierung (Schwer — Spiegel), Stur"], ["Talente", "(Sehr) Attraktiv, Beziehungen, Kampfkünstler, Reich, Gassenwissen, Superkräfte (30), Schnell"], ["Ausrüstung", "Körperpanzerung (+2*)."]], "sf": [["Ausweichen –5 (5)", "–5, um von Fernkampfangriffen getroffen zu werden. (Übernatürliche Wachsamkeit.)", 1], ["Nahkampfangriff (9)", "Stä+2W6. Klauen (+W6, PB 4).", 1], ["Parade +5 (5)", "Übernatürliche Wachsamkeit.", 1], ["Gift (9)", "Flächeneffekt (GFS). Tödlich. Stark. Als Ausprägung wird jeder, der an Medusas Gift stirbt, zu Stein!", 1], ["Zähigkeit +2 (2)", "Muskulöser Körper.", 1]]}, {"n": "Mictlantecuhtli", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 153, "bk": "sw_sup", "o": 2, "d": ["Jose-Maria Barrabas verdiente sein Geld damit, aztekische Artefakte an reiche westliche Museen und Privatsammler zu verkaufen. Eine alte Legende führte ihn tief in den Dschungel, wo er einen verlorenen Tempel fand. Zu seinem Erstaunen stellte er fest, dass der Tempel die spanische Eroberung überstanden hatte und vor goldenen Artefakten überquoll. Er ignorierte die in die Wände gemeißelten Warnungen und wagte sich in die Katakomben. Der Reiz der goldenen Statuette, die er im tiefsten Gewölbe fand, war zu verlockend, und Jose-Maria griff nach ihr. Zu seinem Pech bewohnte der Geist von Mictlantecuhtli – dem aztekischen Gott des Todes – das Objekt. Mictlantecuhtli besaß Jose-Maria, zerstörte seinen Verstand und übernahm die Kontrolle über seinen Körper als physisches Gefäß.", "Seit seinem Erwachen hat Mictlantecuhtli mehrere mesoamerikanische Stämme zum alten Glauben bekehrt und schwelgt nun in den blutigen Opfern, die sie zu seinen Ehren darbringen. Im Lauf der Jahre hat sich Mictlantecuhtli der modernen Kriegsführung zugewandt. Seine Bande mittelamerikanischer Kultisten trägt Hightech-Waffen und -Rüstungen."], "a": [["Geschicklichkeit", "W12"], ["Konstitution", "W10"], ["Stärke", "W12+2"], ["Verstand", "W12"], ["Willenskraft", "W12"]], "f": "Allgemeinwissen W4, Athletik W6, Einschüchtern W12, Fokus W12, Heimlichkeit W4, Kämpfen W12, Wahrnehmung W6, Überreden W4", "b": "6", "pa": "8", "ro": "9", "x": [["Machtniveau", "IV"], ["Handicaps", "Blutrünstig, Auffälliges Aussehen, Fies, Rachsüchtig (Schwer)"], ["Talente", "Kampfreflexe, Raserei, Kühler Kopf, Nerven aus Stahl, Superkräfte (60)"], ["Ausrüstung", "Obsidianschwert (Schaden Stä+W8+4W6, Schwere Waffe)."]], "sf": [["Verfall (6)", "Flächeneffekt (GFS). Midas-Berührung. Stark.", 1], ["Furcht –2 (8)", "Flächeneffekt (GFS). Stark.", 1], ["Furchtlos (2)", "Mictlantecuhtli kennt keine Furcht und kann nicht Eingeschüchtert werden.", 1], ["Immun gegen Gift/Krankheit (2)", "Mictlantecuhtli ist immun gegen Gift und Krankheit.", 1], ["Nahkampfangriff (10)", "Stä+3W6. Spezialwaffe (Langschwert, +W6, Gerät, Schwere Waffe).", 1], ["Fernkampfangriff (13)", "Fokus. Reichweite 12/24/48 oder darf die Kegelschablone nutzen, Schaden 5W6. (Schallkreischen.)", 1], ["Superattribut (8)", "Willenskraft +2, Stärke +2.", 1], ["Übernatürliche Reflexe (3)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen.", 1], ["Untot (8)", "+2 Robustheit; +2 beim Erholen von Angeschlagen; atmet nicht; immun gegen Krankheit und Gift; kein zusätzlicher Schaden durch Gezielte Angriffe; ignoriert 1 Stufe Wundabzüge.", 1], ["Unaufhaltsam", "Der Schurke erleidet durch jeden schädigenden Angriff höchstens eine Wunde (nach dem Aufnehmen), es sei denn, die Aktionskarte des Angreifers ist ein Joker."]]}, {"n": "The Mole", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 154, "bk": "sw_sup", "o": 2, "d": ["Hank Thompson arbeitete für einen Ölkonzern und entwarf Roboter für die Öl-Exploration. Begierig, mehr Geld zu verdienen, als sein Beruf einbrachte, baute sich Hank einen speziellen Maulwurfsanzug, um unter der Erde zu tunneln – und direkt in Banktresore. Wie sich herausstellte, gefiel es Hank dort unten im Dreck sehr. Schließlich entdeckte er sogar einen Stamm unterirdischer Kreaturen, die er Troglodyten (S. 172) nannte, und schüchterte sie zur Unterwerfung ein. Er setzt die aggressiven, aber ahnungslosen Wesen häufig als Unterstützung – oder Ablenkung – bei seinen riskanteren Coups ein."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W12"], ["Stärke", "W12"], ["Verstand", "W8"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W6, Diebeskunst W8, Einschüchtern W6, Heimlichkeit W10, Kämpfen W10, Naturwissenschaften W10, Schießen W10, Wahrnehmung W8, Überreden W4", "b": "8", "pa": "7", "ro": "18 (8)", "x": [["Machtniveau", "III"], ["Handicaps", "Schlechte Augen (Leicht), Gierig (Schwer)"], ["Talente", "Anführer, Kühler Kopf, Superkräfte (45)"], ["Ausrüstung", "Maulwurfsanzug (siehe unten)."]], "sf": [["Rüstung +8 (3)", "Gerät (Maulwurfsanzug).", 1], ["Graben (3)", "Blockbuster. Gerät (Maulwurfsanzug). Bewegungsweite. Tunnelbauer.", 1], ["Erdbeben (4)", "Stark.", 1], ["Wachstum (3)", "Stufe 2 (+2 auf Größe, Stärke und Robustheit). Gerät. Dauerhaft.", 1], ["Geschärfte Sinne (1)", "Infrarotsicht. Restlichtsicht. Gerät (Maulwurfsanzug).", 1], ["Nahkampfangriff (15)", "Stä+3W6, Gerät (Maulwurfsanzug). Klauen (+2W6, PB 8, Gerät, Schwere Waffe).", 1], ["Fernkampfangriff (6)", "Handgelenklaser. Reichweite 12/24/48, Schaden 3W6. Gerät (Maulwurfsanzug). Schwere Waffe.", 1], ["Superattribut (13)", "Stärke +4, Konstitution +3. Gerät (Maulwurfsanzug).", 1]]}, {"n": "The Monster", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 155, "bk": "sw_sup", "o": 2, "d": ["Das Monster ist die Schöpfung des ursprünglichen Dr. Frankenstein, wurde seit jenen frühen, stürmischen Tagen aber viele Male neu zusammengesetzt. Das Monster verachtet Menschen – besonders Menschenmengen. Nachdem es anfangs gegen Lycanthropus gekämpft hatte, genießt das Monster nun gelegentliche Amokläufe, bevor es in die tiefen Wälder entschwindet, um sich eine Weile zu verstecken. Es wird gelegentlich angeworben (oder getäuscht), um sich einer anderen Schurkengruppe als Ablenkung oder reine Muskelkraft anzuschließen."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W12+2"], ["Stärke", "W12+5"], ["Verstand", "W4"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W4, Athletik W6, Einschüchtern W8, Fokus W8, Heimlichkeit W4, Kämpfen W10, Wahrnehmung W4, Überleben W8, Überreden W4", "b": "12", "pa": "7", "ro": "27", "x": [["Machtniveau", "IV"], ["Handicaps", "Blutrünstig, Auffälliges Aussehen (Flickenmonstrosität), Anfälligkeit für Naturgewalten (Feuer), Analphabet, Fies, Rachsüchtig (Schwer)"], ["Talente", "Kräftig, Kampfreflexe, Schwer zu töten, Nerven aus Stahl (Verb.), Superkräfte (60)"], ["Ausrüstung", "Keine."]], "sf": [["Wachstum (4)", "Stufe 2 (+2 auf Größe, Stärke und Robustheit). Dauerhaft.", 1], ["Zäh (2)", "Ein zweites Ergebnis Angeschlagen verursacht keine Wunde.", 1], ["Springen (5)", "Kann 8“ (16 m) senkrecht oder 16“ (32 m) waagerecht springen. Abprallen. Tod von oben.", 1], ["Nahkampfangriff (10)", "Stä+3W6, Schwere Waffe, Zerschmettern.", 1], ["Superattribut (18)", "Stärke +6, Konstitution +3.", 1], ["Zähigkeit +13 (13)", "Muskulöses, untotes Fleisch.", 1], ["Untot (8)", "+2 Robustheit; +2 beim Erholen von Angeschlagen; kein zusätzlicher Schaden durch Gezielte Angriffe; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Krankheit und Gift.", 1]]}, {"n": "Necromancer", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 156, "bk": "sw_sup", "o": 2, "d": ["Jean-Paul DuPois studierte Voodoo in Haiti zur Zeit der Herrschaft von „Papa Doc“ François Duvalier. Statt seine Kräfte für das Gute einzusetzen, wählte er einen dunkleren Pfad. Necromancer ist ein begabter Zauberer, der Tote erwecken kann, damit sie ihm als Zombies dienen. Er hat wenige lebende Freunde, doch das ist ihm lieber – in seinem verdrehten Geist belohnt er jemanden mit ewigem Leben, wenn er ihn zum Zombie macht. Er kleidet sich wie Baron Samedi, als Ode an die Loa."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W8"], ["Stärke", "W8"], ["Verstand", "W12"], ["Willenskraft", "W12"]], "f": "Allgemeinwissen W6, Athletik W4, Diebeskunst W6, Einschüchtern W10, Fahren W4, Fokus W6, Heimlichkeit W4, Kämpfen W6, Okkultismus W12, Wahrnehmung W6, Zaubern W12+2, Überreden W4", "b": "6", "pa": "7", "ro": "11", "x": [["Machtniveau", "V"], ["Defensen", "–3 (Fernkampf)"], ["Handicaps", "Pech, Blutrünstig, Wahnvorstellungen (Leicht — zum Zombie gemacht zu werden ist etwas Gutes), Rachsüchtig (Leicht)"], ["Talente", "Anführer, Inbrunst, Haltet die Stellung!, Superkräfte (75), Der Beste (Handlanger)"], ["Ausrüstung", "Kleine Knochen, Federbündel und anderer Voodoo-Krimskrams."]], "sf": [["Ausweichen –3 (3)", "–3, um von Fernkampfangriffen getroffen zu werden.", 1], ["Furcht –2 (4)", "Stark.", 1], ["Gedankenkontrolle (17)", "Mehrere Geister ×5. Stark.", 1], ["Handlanger (27)", "Alternatives Attribut (Zaubern). Bis zu 10 Zombies. Robust. Herbeirufbar. Superkräfte (Nahkampfangriff Stä+2W6, Superattribut (Stärke +2, Konstitution +2), Untot).", 1], ["Parade +2 (2)", "Übernatürliche Sinne.", 1], ["Fernkampfangriff (9)", "Zaubern. Reichweite 12/24/48, Schaden 4W6. (Feuriger, kreischender Schädel.)", 1], ["Superattribut (4)", "Willenskraft +2.", 1], ["Superzauberei (4)", "Voodoo.", 1], ["Zähigkeit +5 (5)", "Schutz der Loa.", 1]]}, {"n": "Nocturne", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 157, "bk": "sw_sup", "o": 2, "d": ["Jennifer Watts verliebte sich bei einer gelegenen Zusammenarbeit in den Fixer (S. 125). Die Beziehung wurde kompliziert, und der Fixer „testete“ schließlich eines ihrer Geräte an Jennifer. Die Dunkelenergiewaffe tötete das ehemalige Model und hinterließ nichts als Jennifers Schatten an der Wand. Wochen später erhob sich der Schatten als „Nocturne“. Nocturne ist ein Phantom aus rohem Hass und dunkler Energie. Sie sucht den Fixer, lässt ihre Wut in ihrem wahnsinnigen Zustand aber an allen Supers aus, besonders an Frauen, die dem Fixer auch nur im Entferntesten ähneln, oder an solchen, die Supertechnologie einsetzen.", "Jennifers Phantom kann Schatten manipulieren und Salven dunkler Energie abfeuern. Nocturne scheint lange Zeit zu überwintern – vielleicht kämpft sie darum, ihre bloße Existenz aufrechtzuerhalten. Wenn sie zurückkehrt, wird sie oft von intriganten Superschurken für deren finstere Zwecke manipuliert."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W10"], ["Stärke", "W8"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W4, Athletik W6, Diebeskunst W8, Einschüchtern W6, Fahren W6, Fokus W10, Heimlichkeit W8, Kämpfen W8, Provozieren W6, Wahrnehmung W10, Überreden W4", "b": "8", "pa": "6", "ro": "12", "x": [["Machtniveau", "III"], ["Handicaps", "Fremdgestalt (Schatten), Außenseiter (Schwer), Verwundbarkeit (Leicht — starkes Licht), Rachsüchtig (Schwer)"], ["Talente", "Starker Wille, Superkräfte (45)"], ["Ausrüstung", "Keine."]], "sf": [["Alterslos (1)", "Jennifer ist nicht mehr sterblich.", 1], ["Wachsamkeit (2)", "Ignoriert 2 Punkte der Angriffsabzüge eines Gegners.", 1], ["Energiekontrolle (7)", "Dunkelheit. Flächeneffekt.", 1], ["Kraftfeld (5)", "Eingehender Schaden wird um 5 Punkte verringert.", 1], ["Geschärfte Sinne (1)", "Restlichtsicht.", 1], ["Unberührbarkeit (3)", "Dauerhaft.", 1], ["Verschleiern (6)", "Flächeneffekt (bis zu 25“).", 1], ["Zähigkeit +5 (5)", "Kosmische Energie.", 1], ["Fernkampfangriff (15)", "Fokus. Reichweite 12/24/48, Schaden 4W6, PB 10. (Dunkelheitsblitze.)", 1]]}, {"n": "Octopon", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 158, "bk": "sw_sup", "o": 2, "d": ["Oskar Baumstein ist ein ehemaliger Pirat – und ein tobender Irrer. Er behauptet, er sei in eine andere Welt verschlagen worden, eine ertrinkende Welt, die unter einem schrecklichen Fluch leidet. Oskar behauptete außerdem, er sei dort ein Jahrzehnt gewesen, obwohl er nur wenige Monate vermisst wurde. Irgendwo auf seinen Reisen kreuzte er den Weg einer Rasse schrecklicher oktopusartiger Kreaturen, geboren aus dunkler Zauberei, und der Kontakt verwandelte seine Gliedmaßen irgendwie in die der „Oktopons“, wonach er sich benannt hat. Der verrückte Pirat konzentriert sich nun auf Ozeandampfer oder Ziele an der Küste. Mit der Beute, die er erlangt, kann er jetzt wenig anfangen, doch er sucht trotzdem weiter nach Plündergut."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W12"], ["Stärke", "W12+2"], ["Verstand", "W6"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W12, Diebeskunst W8, Einschüchtern W6, Fahren W6, Fokus W8, Heimlichkeit W10, Kämpfen W12+2, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "14", "ro": "11", "x": [["Machtniveau", "III"], ["Handicaps", "Zwei linke Hände, Auffälliges Aussehen (tentakeliger Unhold), Anfälligkeit für Naturgewalten (Feuer), Gesucht (Schwer — atlantische Behörden)"], ["Talente", "Beidhändig, Kampfreflexe, Erstschlag, Schwer zu töten, Kühler Kopf, Superkräfte (45), Rundumschlag"], ["Ausrüstung", "Zwei Säbel (Stä+3W6), zwei Impulspistolen (Reichweite 10/20/40, Schaden 2W6, PB 2)."]], "sf": [["Zusätzliche Aktionen (5)", "Ignoriert pro Zug bis zu zwei Punkte Mehrfachaktionsabzüge.", 1], ["Wasserlebewesen (4)", "Schwimm-Bewegungsweite 10, atmet unter Wasser. Schneller Schwimmer.", 1], ["Zusätzliche Gliedmaßen (9)", "Vier Tentakel, Reichweite 1. (Oskar ist eigentlich ein Sektopon, nennt sich aber Octopon.)", 1], ["Zäh (2)", "Ein zweites Ergebnis Angeschlagen verursacht keine Wunde.", 1], ["Nahkampfangriffe (4)", "Stä+2W6. Octopon führt Säbel und Impulspistolen mit seinen Tentakeln, wenn er sie erlangen kann.", 1], ["Parade +5 (5)", "Wirbelnde Tentakel.", 1], ["Superattribut (6)", "Stärke +2, Konstitution +1.", 1], ["Superfertigkeit (5)", "Athletik +2, Kämpfen +3.", 1], ["Zähigkeit +2 (2)", "Anpassung an die Tiefsee.", 1], ["Übernatürliche Reflexe (3)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen.", 1]]}, {"n": "Deader", "k": "Untote", "w": 0, "s": ["SUP"], "p": 159, "bk": "sw_sup", "o": 2, "g": "Die Omega Legion", "d": ["Diese „Superzombies“ sind keine gewöhnlichen wandelnden Toten. Diese grauenhaften Kreaturen kehrten mit bizarren Kräften ins Unleben zurück, vielleicht als Wirte für außerirdische Parasiten, mächtige Geister oder gar als Hüllen, die von dämonischen Mächten bewohnt werden. Beachte, dass diese Untoten keine Superkräfte haben – ihre Fähigkeiten sind völlig natürlich. Ein „Superzombie“ kann durch mächtige giftige Chemikalien, verrückte Wissenschaftler, mächtige Kultisten, geheime Regierungslabore oder von außerirdischen Invasoren ausgesäte Sporen entstehen."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W10"], ["Stärke", "W10"], ["Verstand", "W4"], ["Willenskraft", "W4"]], "f": "Athletik W8, Einschüchtern W8, Kämpfen W8, Schießen W6, Wahrnehmung W6", "b": "6", "pa": "6", "ro": "9", "x": [["Ausrüstung", "Keine."]], "sf": [["Biss/Klauen", "Stä+W6."], ["Furcht", "Jeder, der einen Zombie sieht, muss eine Furchtprobe ablegen."], ["Furchtlos", "Zombies sind immun gegen Furcht und Einschüchtern."], ["Infektion (1)", "Jeder, der von einem Deader gebissen oder gekratzt wird, muss eine Konstitutionsprobe ablegen oder wird infiziert. Bedingt durch Nahkampfangriff — Klauen. Tödlich. Berührung erforderlich. Vervielfältigung. Stark.", 1], ["Untot", "+2 Robustheit; +2 beim Erholen von Angeschlagen; kein zusätzlicher Schaden durch Gezielte Angriffe; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Krankheit und Gift."], ["Schwachstelle (Kopf)", "Gezielte Angriffe auf den Kopf eines Zombies verursachen den üblichen Zusatzschaden von +4."]]}, {"n": "Rülpser", "k": "Untote", "w": 0, "s": ["SUP"], "p": 159, "bk": "sw_sup", "o": 2, "g": "Die Omega Legion", "d": ["Manche Deader sind so verstärkt, dass sie Wolken giftiger Dämpfe rülpsen. Sie haben die Werte eines normalen Deaders (siehe oben) mit Athletik W10 und einer zusätzlichen Fähigkeit."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W10"], ["Stärke", "W10"], ["Verstand", "W4"], ["Willenskraft", "W4"]], "f": "Athletik W10, Einschüchtern W8, Kämpfen W8, Schießen W6, Wahrnehmung W6", "b": "6", "pa": "6", "ro": "9", "x": [["Ausrüstung", "Keine."]], "sf": [["Biss/Klauen", "Stä+W6."], ["Furcht", "Jeder, der einen Zombie sieht, muss eine Furchtprobe ablegen."], ["Furchtlos", "Zombies sind immun gegen Furcht und Einschüchtern."], ["Infektion (1)", "Jeder, der von einem Deader gebissen oder gekratzt wird, muss eine Konstitutionsprobe ablegen oder wird infiziert. Bedingt durch Nahkampfangriff — Klauen. Tödlich. Berührung erforderlich. Vervielfältigung. Stark.", 1], ["Untot", "+2 Robustheit; +2 beim Erholen von Angeschlagen; kein zusätzlicher Schaden durch Gezielte Angriffe; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Krankheit und Gift."], ["Schwachstelle (Kopf)", "Gezielte Angriffe auf den Kopf eines Zombies verursachen den üblichen Zusatzschaden von +4."], ["Leichenatem", "Immer wenn die Aktionskarte eines Rülpsers eine Bildkarte ist, kann er einen Athletikwurf ablegen, um einen Stoß üblen Atems in einer Kegelschablone auszustoßen. Jeder in der Schablone muss eine Konstitutionsprobe ablegen (mit –2, wenn der Brocken eine Steigerung erzielte) oder ist Betäubt."]]}, {"n": "Super-Konglomerat", "k": "Untote", "w": 1, "s": ["SUP"], "p": 159, "bk": "sw_sup", "o": 2, "g": "Die Omega Legion", "d": ["Ein Super-Konglomerat – kurz ’Glom – ist eine Gruppe von Leichen, die zu einer grauenhaften Masse verschmolzen sind. Das hier vorgestellte besteht aus zehn Leichen und ist eine erhebliche Herausforderung für fast jeden Super. ’Gloms nutzen ihre Gliedmaßen und jede greifbare Waffe, um jede lebende Person in Sichtweite zu töten, und fügen diese Leichen dann ihrer Masse hinzu. Konglomerate können Waffen führen, wenn welche verfügbar sind, doch ihre Gliedmaßen fuchteln wild, sodass Fernkampfschüsse mit –2 abgelegt werden. Super-’Gloms finden sich oft im Zentrum von Untotenhorden aus Superzombies und Brocken. Manche haben vielleicht zusätzliche Kräfte, die andere Untote stärken, Lebende schwächen und so weiter.", "’Gloms können Waffen tragen und nutzen, wenn gewünscht, doch die meisten bevorzugen das Gelände als Waffe – Autos, Straßenlaternen oder was sie sonst in die Finger bekommen. Siehe Große Improvisierte Waffen auf S. 32."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W12+7"], ["Stärke", "W12+7"], ["Verstand", "W4"], ["Willenskraft", "W4"]], "f": "Athletik W8, Einschüchtern W6, Heimlichkeit W4, Kämpfen W8, Schießen W6, Wahrnehmung W10", "b": "6", "pa": "6", "ro": "22", "x": [["Ausrüstung", "Keine."]], "sf": [["Furcht (–2)", "Jeder, der ein ’Glom sieht, muss eine Furchtprobe mit –2 ablegen."], ["Furchtlos", "’Gloms sind immun gegen Furcht und Einschüchtern."], ["Nahkampfangriff", "Stä+3W6. Zerschmettern."], ["Größe 9 (Riesig)", "Das hier vorgestellte ’Glom hat die Größe von 10 menschlichen Leichen und kann zwei zusätzliche Wunden einstecken."], ["Untot", "+2 Robustheit; +2 beim Erholen von Angeschlagen; ignoriert 1 Punkt Wundmodifikatoren; Gezielte Angriffe verursachen keinen Zusatzschaden; atmet nicht; immun gegen Krankheit und Gift."], ["Schwachstelle (Kopf)", "Eine Wahrnehmungsprobe mit –1 je ’glommtem Körper (max. –4) enthüllt, welcher der vielen Köpfe des ’Gloms der primäre ist. Wird er zerstört, stirbt das ganze Ding sofort."]]}, {"n": "Pied Piper", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 160, "bk": "sw_sup", "o": 2, "d": ["Beim Stöbern auf dem Dachboden seines Urgroßvaters entdeckte Klaus Werner eine kleine Panflöte und einen geheimnisvollen Brief aus dem 17. Jahrhundert. In dem Brief stand, einer von Klaus’ entfernten Verwandten sei eines der Kinder gewesen, die der Rattenfänger von Hameln der (angeblichen) Legende nach entführt hatte. Das Kind war aus dem Gefängnis des Rattenfängers entkommen und hatte dessen Flöte gestohlen, die Klaus nun in den Händen hielt. Klaus fing klein an, bezirzte Ratten, überredete Polizisten, seine Strafzettel zu erlassen, und so weiter. Seine Kontrolle wuchs rasch, ebenso seine Raubzüge. Heute ist der Pied Piper ein berüchtigter Verbrecher, der sich oft mit kriminellen Banden zusammentut und im Schatten hinter denen lauert, die mehr rohe Feuerkraft haben."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W6"], ["Stärke", "W6"], ["Verstand", "W12"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W10, Athletik W8, Darbietung W12, Diebeskunst W8, Einschüchtern W8, Fahren W6, Fokus W10, Heimlichkeit W8, Kämpfen W6, Provozieren W10, Wahrnehmung W8, Überreden W8", "b": "6", "pa": "10", "ro": "5", "x": [["Machtniveau", "III"], ["Defensen", "–5 (Fernkampf)"], ["Handicaps", "Gierig (Schwer), Skrupellos (Schwer), Rachsüchtig (Schwer)"], ["Talente", "Charismatisch, Killerinstinkt, Starker Wille, Superkräfte (45), Der Beste (Gedankenkontrolle)"], ["Ausrüstung", "Magische Panflöte (siehe unten)."]], "sf": [["Tierkontrolle (12)", "Der Flötenspieler kann bis zu 14 Punkte an Tieren kontrollieren. Gerät (Flöte).", 1], ["Ausweichen –5 (5)", "–5, um von Fernkampfangriffen getroffen zu werden. Der Flötenspieler tänzelt aus der Gefahrenzone.", 1], ["Furcht –2 (6)", "Flächeneffekt (GFS). Gerät (Flöte). Stark.", 1], ["Gedankenkontrolle (17)", "Gerät (Flöte). Vergesslich. Mehrere Geister ×5. Stark.", 1], ["Parade +5 (5)", "Der Flötenspieler tänzelt aus der Gefahrenzone.", 1]]}, {"n": "Ratkin", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 161, "bk": "sw_sup", "o": 2, "d": ["Ratkin war ein obdachloser Herumtreiber, der eines Nachts in einem illegalen Chemielager das Bewusstsein verlor. Giftige Dämpfe durchdrangen seinen Körper, und als er erwachte, war er auf Zellebene zu einem gefräßigen rattenähnlichen Humanoiden mutiert. „Ratkin“ stieg aus den Dämpfen auf und machte Jagd auf alle, die ihm seiner Meinung nach wehgetan hatten. Nun ist er ein wilder und bemitleidenswerter Killer. Er ist ein gerissener Jäger, nutzt die Kanalisation, um den Behörden zu entgehen, und flieht aus jedem Kampf, in dem er klar unterlegen ist."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W10"], ["Stärke", "W12"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W4, Athletik W8, Diebeskunst W10, Fokus W6, Heimlichkeit W10, Kämpfen W10, Provozieren W6, Wahrnehmung W6, Überreden W4", "b": "8", "pa": "10", "ro": "7", "x": [["Machtniveau", "II"], ["Defensen", "–2"], ["Handicaps", "Auffälliges Aussehen (rattenähnliche Züge), Angewohnheit (Leicht — streicht sich über die Schnurrhaare), Fies, Phobie (Schwer — Katzen)"], ["Talente", "Flink, Raserei (Verb.), Superkräfte (30)"], ["Ausrüstung", "Keine."]], "sf": [["Tierkontrolle (10)", "10 Punkte an Kreaturen. Einschränkung (nur Rattenschwärme). Telepathische Verbindung (1,6 km).", 1], ["Ausweichen –2 (2)", "Furcht davor, verletzt zu werden.", 1], ["Nahkampfangriff (9)", "Stä+2W6. Klauen (+W6, PB 4, Tödlich).", 1], ["Furcht (2)", "Jeder, der den grotesken Schurken sieht, muss eine Furchtprobe ablegen.", 1], ["Immun gegen Krankheit", "Ratkins Körper macht ihn immun gegen alle Krankheiten.", 1], ["Infektion (1)", "Jeder, der von Ratkins Klauen getroffen wird, muss eine Konstitutionsprobe ablegen oder erleidet Erschöpfung. (Bedingt durch Nahkampfangriff — Klauen.) Stark. Berührung erforderlich.", 1], ["Parade +3 (3)", "Ratkin mag Schmerz wirklich nicht!", 1], ["Superattribut (2)", "Stärke +1.", 1]]}, {"n": "The Reaper", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 162, "bk": "sw_sup", "o": 2, "d": ["Die Reederei-Erbin Claudia Shapman hätte in den 1950ern sterben sollen, schaffte es aber durch schiere Willenskraft und das Okkulte, die Sense eines Schnitters zu bergen. Die Waffe schützt sie vor einem natürlichen Tod, solange sie sie mindestens einmal täglich führt, und verleiht ihr auch viele andere Kräfte. Nun nutzt Claudia ihre kleine, aber mächtige Import-Export-Firma, um magische Artefakte aufzuspüren und an den Meistbietenden zu verkaufen (oder für sich zu behalten). Sie hat einen loyalen Kult, der jeder ihrer Launen dient, und heuert oft Superschurken oder die Purpurfaust an, wenn sie zusätzliche Muskelkraft braucht, um einen seltenen Gegenstand zu bergen, zu beschützen oder zu transportieren."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W12"], ["Stärke", "W12+2"], ["Verstand", "W12"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W10, Athletik W6, Einschüchtern W10, Fahren W8, Fokus W10, Heimlichkeit W10, Kämpfen W10, Okkultismus W12, Provozieren W10, Wahrnehmung W10, Überreden W10", "b": "6", "pa": "12", "ro": "8", "x": [["Machtniveau", "V"], ["Handicaps", "Neugierig, Gierig (Schwer), Skrupellos (Schwer)"], ["Talente", "Bedrohlich, Superkräfte (75), Rundumschlag (Verb.), Starker Wille, Lieblingswaffe (Imp—Scythe)"], ["Ausrüstung", "Sense des Schnitters (Stä+W10+5W6, PB 10, Parade –2, Reichweite +1, Schwere Waffe)."]], "sf": [["", "Alle Kräfte von Claudia sind Gerät (Sense des Schnitters)."], ["Alterslos (1)", "Sehr alt.", 1], ["Wachsamkeit (4)", "Ignoriert 4 Punkte der Angriffsabzüge eines Gegners.", 1], ["Furcht –2 (6)", "Flächeneffekt (GFS). Stark.", 1], ["Furchtlos (1)", "Immun gegen Furcht.", 1], ["Flug (4)", "Bewegungsweite 45 (48 km/h).", 1], ["Kraftfeld (8)", "Eingehender Schaden wird um 10 Punkte verringert.", 1], ["Immun gegen Gift/Krankheit (1)", "Der Schnitter stirbt nicht eines natürlichen Todes.", 1], ["Unberührbarkeit (3)", "Der Schnitter kann als begrenzte Aktion unberührbar werden.", 1], ["Eigenschaft erhöhen/senken (9)", "Zusätzliche Empfänger (5). Beliebige Eigenschaft. Absaugen. Einschränkung (nur Eigenschaft senken).", 1], ["Nahkampfangriff (14)", "Spezialwaffe (Sense des Schnitters, +5W6, PB 10, Schwere Waffe).", 1], ["Gedankenkontrolle (5)", "Stark.", 1], ["Parade +3 (1)", "Sense.", 1], ["Superattribut (12)", "Willenskraft +1, Stärke +4, Konstitution +2.", 1], ["Superfertigkeit (1)", "Kämpfen +2, Einschüchtern +2.", 1]]}, {"n": "Sickle", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 163, "bk": "sw_sup", "o": 2, "d": ["Olga Rasputinovich war eine vielversprechende Turnerin, aber nie ganz gut genug für das russische Olympiateam. Als er ihre Mühen sah, bot ihr ein Mitglied des Red-Dragon-Verbrechersyndikats (S. 146) eine experimentelle Droge an, die ihre Fähigkeiten steigern sollte. „Malevolent“ (russisch zloy) wirkte wie versprochen, machte sie aber rücksichtslos und gemein. Bald wurde sie wegen ihrer gewalttätigen Ausbrüche von Wettkämpfen ausgeschlossen, und wie geplant bot Red Dragon ihr eine Alternative: Vollstreckerin werden, in Saus und Braus leben, ein Vermögen machen und so viel zloy bekommen, wie sie will."], "a": [["Geschicklichkeit", "W12"], ["Konstitution", "W8"], ["Stärke", "W12"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W12, Diebeskunst W6, Einschüchtern W6, Fahren W4, Fokus W6, Heimlichkeit W8, Kämpfen W12, Provozieren W6, Wahrnehmung W6, Überreden W6", "b": "24", "pa": "8", "ro": "6", "x": [["Machtniveau", "II"], ["Handicaps", "Arrogant, Übermütig, Angewohnheit (Schwer — muss mindestens einmal täglich „Malevolent“ nehmen), Rücksichtslos, Skrupellos (Schwer)"], ["Talente", "Dynamisches Duo, Ausweichen, Raserei (Verb.), Kühler Kopf, Superkräfte (30), Rundumschlag"], ["Ausrüstung", "Große Sichel (Schaden Stä+W8+3W6, PB 4, Schwere Waffe)."]], "sf": [["Springen (4)", "4“ senkrecht, 8“ waagerecht. Abprallen. Tod von oben.", 1], ["Nahkampfangriff (8)", "Spezialwaffe (Große Sichel, +3W6, PB 6, Gerät, Schwere Waffe).", 1], ["Geschwindigkeit (4)", "Bewegungsweite 24.", 1], ["Superattribut (8)", "Geschicklichkeit +2, Stärke +2.", 1], ["Supertalent (6)", "Raserei, Raserei (Verb.), Kühler Kopf, Rundumschlag.", 1]]}, {"n": "Soothsayer", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 164, "bk": "sw_sup", "o": 2, "d": ["Katyana Drasilova wurde in eine arme rumänische Familie geboren. Wie ihre Mutter und Großmutter hatte sie die Gabe der Prophezeiung. Anders als ihre Vorfahrinnen hatte sie jedoch weitere magische Kräfte, mit denen sie die Wirklichkeit ihrem Willen beugen konnte. Ihre Fähigkeiten reichten allerdings nicht, um ihre Familie zu retten, die von den Red-Dragon-Agenten Hammer und Sickle (S. 136 bzw. S. 163) getötet wurde, als sie sich weigerte, der russischen Mafia bei ihren kriminellen Unternehmungen zu helfen. Katyana floh aus Osteuropa, nachdem sie sich an einigen der Gangster gerächt hatte, die ihr Unrecht getan hatten, und versteckt sich nun im Schatten, aus dem sie nur auftaucht, um ihre Kräfte zu verkaufen, wenn sie Geld braucht. Sie hat Helden und Schurken gleichermaßen geholfen – aber nie einem Mitglied von Red Dragon."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W8"], ["Stärke", "W6"], ["Verstand", "W12"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W6, Athletik W6, Diebeskunst W8, Einschüchtern W6, Fahren W6, Fokus W6, Heimlichkeit W4, Kämpfen W6, Okkultismus W12, Provozieren W6, Wahrnehmung W8, Zaubern W12, Überreden W10", "b": "6", "pa": "10", "ro": "6", "x": [["Machtniveau", "III"], ["Defensen", "–5"], ["Handicaps", "Neugierig, Außenseiter (Leicht — Roma), Rachsüchtig (Schwer)"], ["Talente", "Arkaner Hintergrund (Magie), Charismatisch, Gefahrensinn, Kühler Kopf (Verb.), Machtpunkte, Starker Wille, Superkräfte (45)"], ["Zauber", "Bannen, Tierfreund, Verwirrung, Dunkelsicht, Arkanes entdecken/verbergen, Verkleiden, Bannen, Wahrsagung, Verstricken, Fernsicht, Heilung, Illusion, Objekt auslesen, Sprachen sprechen (Machtpunkte: 20)"], ["Ausrüstung", "Keine."]], "sf": [["Wachsamkeit (4)", "Ignoriert 4 Punkte an Abzügen durch die Kräfte, Aktionen oder Fähigkeiten ihres Gegners.", 1], ["Eigenschaft erhöhen/senken (9)", "Zusätzliche Empfänger (+2). Alternatives Attribut (Zaubern). Beliebige Eigenschaft. Macht.", 1], ["Ausweichen –5 (5)", "–5, um von Fernkampfangriffen getroffen zu werden.", 1], ["Geschärfte Sinne (1)", "Adleraugen.", 1], ["Pech bringen (6)", "Größeres Pech.", 1], ["Parade +5 (5)", "Vorausschauende Bewegung.", 1], ["Supertalent (12)", "Arkaner Hintergrund (Magie), Gefahrensinn, Kühler Kopf (Verb.), Machtpunkte.", 1], ["Übernatürliche Reflexe (3)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen.", 1]]}, {"n": "The Spider", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 165, "bk": "sw_sup", "o": 2, "d": ["Hamilton Smythe ist „The Spider“ im Zentrum eines internationalen Netzes aus Verbrechen, Intrigen und Korruption. Niemand weiß, wo er lebt oder wie man ihn findet. Er unterhält keine feste Bande oder Handlanger, von denen jemand wüsste, sondern arbeitet über unzählige Mittelsmänner – von denen viele es nicht einmal wissen –, um seine Wünsche auszuführen. Doch der Spider hat ein Geheimnis … es gibt tatsächlich nicht nur einen Spider, sondern mehrere! Doch es gibt ein noch größeres Geheimnis … alle „Spiders“ sind in Wahrheit … V’sori-Agenten!", "Die V’sori-Invasion (S. 184) fand vor über einem Jahrzehnt statt, doch nicht alle außerirdischen Invasoren konnten entkommen. Eine kleine Truppe blieb zurück und schaffte es schließlich, miteinander Kontakt aufzunehmen. Nun manipuliert die „Fünfte Kolonne“ die Angelegenheiten der Erde, um auf die unvermeidliche und glorreiche Rückkehr des Overminds vorbereitet zu sein! Sie haben Geschichten gehört, eine Supergruppe habe ihren Anführer besiegt, glauben aber nicht daran und planen, für ihren „Aufstieg“ bereit zu sein. Bis zu diesem Tag wird der „Spider“ Chaos und Zwietracht unter den Verteidigern der Erde säen, einschließlich ihrer Superhelden – und ihrer Schurken."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W8"], ["Stärke", "W6"], ["Verstand", "W8"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W8, Athletik W8, Einschüchtern W8, Elektronik W10, Fokus W10, Hacken W10, Heimlichkeit W8, Kämpfen W10, Naturwissenschaften W10, Provozieren W8, Recherche W10, Schießen W10, Wahrnehmung W8, Überreden W8", "b": "6", "pa": "7", "ro": "6", "x": [["Machtniveau", "III"], ["Handicaps", "Fies, Skrupellos (Leicht)"], ["Talente", "Charismatisch, Superkräfte (51)"], ["Ausrüstung", "Die Spiders haben nach Bedarf Zugriff auf jede in Anhang A aufgeführte V’sori-Ausrüstung, tragen aber meist nur eine Impulspistole, um ihre Identität nicht zu verraten."]], "sf": [["Wasserlebewesen", "Bewegungsweite 10."], ["Chamäleon (3)", "Biometrie. Gerät (auf ein Kleidungsstück implantierter Chip).", 1], ["Energiekontrolle (12)", "Mental. Flächeneffekt (GFS). Macht.", 1], ["Restlichtsicht", "V’sori ignorieren Abzüge für Düstere und Dunkle Beleuchtung."], ["Gedankenkontrolle (9)", "Mehrere Geister × 2.", 1], ["Gedankenlesen (5)", "Stark.", 1], ["Gedankenschild (3)", "Stark.", 1], ["Betäuben (9)", "Flächeneffekt (GFS). Stark. (Psionische Synapsenschock-Salve.)", 1], ["Telekinese (10)", "Stärke W10. Reichweite 12“.", 1], ["Telepathie", "Reichweite 24“. Nur andere V’sori oder Atlanteaner."]]}, {"n": "Stealth", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 166, "bk": "sw_sup", "o": 2, "d": ["Patricia Dalgleishs Kräfte machen sie zur perfekten Spionin, Saboteurin und Auftragsmörderin. Ihre Fähigkeiten sind einfach, aber wirksam. Die verführerische Schottin nutzt ihre Chamäleon- und Nachahmer-Kräfte, um selbst in die am besten geschützten Bereiche einzudringen, Geheimnisse zu stehlen, Erpressungsmaterial zu sammeln oder ihren Zielen „einen letzten Tanz“ zu schenken. Stealth arbeitet für jeden, der sich ihre Dienste leisten kann, darunter Kunden wie der Spider (S. 165) oder der Fixer (S. 125)."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W8"], ["Stärke", "W6"], ["Verstand", "W8"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W4, Athletik W6, Diebeskunst W10, Elektronik W10, Fahren W8, Fokus W8, Hacken W10, Heimlichkeit W10, Kämpfen W10, Wahrnehmung W8, Überreden W12", "b": "6", "pa": "7", "ro": "6", "x": [["Machtniveau", "II"], ["Defensen", "–5 (Fernkampf)"], ["Handicaps", "Gierig (Schwer), Skrupellos (Schwer)"], ["Talente", "Erstschlag, Kühler Kopf, (Sehr) Attraktiv, Superkräfte (30), Der Beste (Nachahmer), Dieb"], ["Ausrüstung", "Impulspistole (Reichweite 10/20/40, Schaden 2W6, PB 2)."]], "sf": [["Chamäleon (3)", "Biometrie. Berührung erforderlich.", 1], ["Nachahmer (15)", "Stufe 17. Übergenau.", 1], ["Ausweichen –5 (5)", "Gegner ziehen 5 von ihren Fernkampfangriffen ab.", 1], ["Betäuben (3)", "Berührung erforderlich. Stark.", 1], ["Superfertigkeit (4)", "Überreden +2, Heimlichkeit +2.", 1]]}, {"n": "Supernova", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 167, "bk": "sw_sup", "o": 2, "d": ["Duke Barton war Pilot einer zurückkehrenden Raumfahrtmission, als das Raumschiff von der Strahlung einer Sonneneruption getroffen wurde. Sein Körper wurde für immer verändert und gibt tödliche Strahlungsmengen an jeden ab, der ihm nahe kommt. Da die moderne Wissenschaft kein Heilmittel finden konnte, lernte er alles über Strahlenkunde und beschloss, selbst eines zu finden. Der tragische Schurke begeht Verbrechen nur, um seine Forschung zu finanzieren, ist aber durch die vielen experimentellen Chemikalien, die seinen Körper zerstören, etwas verwirrt."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W10"], ["Stärke", "W6"], ["Verstand", "W10"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W4, Athletik W6, Diebeskunst W8, Elektronik W10, Fahren W10, Fliegen W12, Fokus W8, Heimlichkeit W4, Kämpfen W6, Naturwissenschaften W10, Reparieren W8, Schießen W8, Wahrnehmung W6, Überreden W6", "b": "6", "pa": "5", "ro": "17 (6)", "x": [["Machtniveau", "II"], ["Handicaps", "Auffälliges Aussehen (trägt immer seinen Strahlenschutzanzug), Skrupellos (Schwer), Todkrank, Schwur (Schwer — ein Heilmittel finden)"], ["Talente", "Aufmerksamkeit, Gelehrter (Naturwissenschaften), Superkräfte (30), Der Beste (Energiekontrolle)"], ["Ausrüstung", "Strahlenschutzanzug (siehe unten)."]], "sf": [["Rüstung +6 (2)", "Gerät (bleibeschichteter Anzug).", 1], ["Energiekontrolle (10)", "Strahlung. Macht.", 1], ["Umweltresistenz (3)", "Strahlung. Immunität.", 1], ["Explodieren (4)", "Strahlung. Großer Knall. Sicherung. Vorübergehende Auflösung.", 1], ["Flug (4)", "Bewegungsweite 12 (13 km/h).", 1], ["Geschärfte Sinne (2)", "Infrarotsicht, Restlichtsicht.", 1], ["Keine lebenswichtigen Organe (1)", "Supernova besteht vollständig aus Energie.", 1], ["Zähigkeit +4 (4)", "Veränderte Physiologie.", 1]]}, {"n": "Surtr", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 168, "bk": "sw_sup", "o": 2, "d": ["Surtr stammt aus einer Dimension, in der die nordische Sage Wirklichkeit war. Obwohl er nun auf der Erde gefangen ist, war er einst Herrscher der Feuerriesen. Er ist arrogant, stolz und betrachtet Menschen als bloße Insekten, die den „Alten Glauben“ und alles, was ihm einst heilig war, aufgegeben haben. Surtrs Kräfte waren schwach, als er auf der Erde ankam, doch er gewinnt sie langsam zurück. Sein Haar und sein Bart sind lebende Flammen, und sein großes Schwert ist in beständiges Feuer gehüllt."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W12"], ["Stärke", "W12+4"], ["Verstand", "W6"], ["Willenskraft", "W12"]], "f": "Allgemeinwissen W6, Athletik W6, Einschüchtern W8, Fokus W10, Heimlichkeit W4, Kämpfen W12+2, Provozieren W8, Wahrnehmung W6, Überreden W6", "b": "8", "pa": "11", "ro": "27 (10)", "x": [["Machtniveau", "V"], ["Handicaps", "Arrogant, Anfälligkeit für Naturgewalten (Wasser), Übermütig, Skrupellos (Schwer)"], ["Talente", "Kampfreflexe, Gegenangriff, Experte (Kämpfen), Flink, Block (Verb.), Erstschlag (Verb.), Rundumschlag (Verb.), Starker Wille, Den Treffer einstecken, Superkräfte (75), Zäh wie Leder, Waffenmeister"], ["Ausrüstung", "Verzauberter Brustpanzer (siehe unten), flammendes Großschwert (Stä+W10+5W6, PB 12, Schwere Waffe)."]], "sf": [["Rüstung +10 (8)", "Schwere Rüstung. Gerät (Brustpanzer).", 1], ["Wachsamkeit (5)", "Ignoriert 5 Punkte der Angriffsabzüge eines Gegners.", 1], ["Schadensfeld (10)", "Feuer. Schaden 4W6. Gerät (flammender Brustpanzer). Flächeneffekt (GFS). Tödlich. Dauerhaft.", 1], ["Energiekontrolle (12)", "Feuer. Flächeneffekt (GFS). Macht.", 1], ["Umweltresistenz (3)", "Feuer. Immunität.", 1], ["Nahkampfangriff (16)", "Stä+3W6. Spezialwaffe (flammendes Großschwert +2W6, PB 12, Gerät, Schwere Waffe).", 1], ["Gedankenschild (3)", "Stark.", 1], ["Größe 4 (Groß)", "Surtr ist 4,5 m groß."], ["Superattribut (12)", "Stärke +3, Konstitution +2, Willenskraft +1.", 1], ["Zähigkeit +5 (5)", "Überirdisches Fleisch.", 1]]}, {"n": "Tech-Ganger", "k": "Humanoide", "w": 0, "s": ["SUP"], "p": 169, "bk": "sw_sup", "o": 2, "g": "Tech-Gangs", "d": ["Tech-Gangs sind kriminelle Organisationen mit brillanten, aber nicht weniger unmoralischen Mitgliedern. Sie entwickeln gefährliche Waffen für den Meistbietenden, stehlen Technologie von legitimen Unternehmen und untergraben sogar die Weltwirtschaft. Die meisten tun es, weil sie Technologie ausnutzen können und die technisch weniger bewanderte Welt blenden, während sie sie ausrauben. Andere tun es für den reinen Nervenkitzel, damit durchzukommen, oder die rohe Macht, die ihre Geräte oft verleihen. Tech-Gangs werden oft von wohlhabenden oder technisch orientierten Superschurken angeheuert oder angeführt, etwa dem Alchemist (S. 102), dem Schwarzen Loch (S. 107), Electron (S. 123), dem Fixer (S. 125), Flux (S. 126), dem Spider (S. 165) und anderen brillanten, aber fehlgeleiteten Übeltätern.", "Die Fußsoldaten der Tech-Gangs sind überdurchschnittlich schlaue Kriminelle mit zumindest etwas Hintergrund in Wissenschaft und Mechanik."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W6"], ["Stärke", "W6"], ["Verstand", "W6"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W6, Diebeskunst W8, Einschüchtern W6, Elektronik W6, Fahren W6, Heimlichkeit W6, Kämpfen W6, Naturwissenschaften W6, Provozieren W6, Reparieren W6, Schießen W6, Wahrnehmung W6, Überreden W4", "b": "6", "pa": "5", "ro": "7 (2)", "x": [["Handicaps", "Gierig (Leicht)"], ["Talente", "Aufmerksamkeit"], ["Ausrüstung", "Kevlar-Kostüm (+2*), Impuls-MP (Reichweite 10/20/40, Schaden 2W6, PB 2, FR 3)."]], "sf": []}, {"n": "Tech-Gang-Fixer", "k": "Humanoide", "w": 1, "s": ["SUP"], "p": 169, "bk": "sw_sup", "o": 2, "g": "Tech-Gangs", "d": ["Tech-Gangs werden meist von versierten Leutnants angeführt, die einige zusätzliche Gadgets haben, um Chaos unter allen anzurichten, die ihnen im Weg stehen."], "a": [["Geschicklichkeit", "W6"], ["Konstitution", "W6"], ["Stärke", "W6"], ["Verstand", "W8"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W8, Athletik W6, Diebeskunst W10, Einschüchtern W8, Elektronik W8, Fahren W6, Hacken W8, Heimlichkeit W8, Kämpfen W6, Naturwissenschaften W10, Schießen W6, Wahrnehmung W8, Überreden W8", "b": "6", "pa": "5", "ro": "12 (2)", "x": [["Handicaps", "Gierig (Schwer), Skrupellos (Leicht)"], ["Talente", "Ansporn, Anführer, Befehlsgewalt, Inspirieren, Reparaturgenie, Superkräfte (15)"], ["Ausrüstung", "Kampfrüstung (+2*), Impuls-MP (Reichweite 10/20/40, Schaden 2W6, PB 2, FR 3)."]], "sf": [["Schadensfeld (2)", "2W6. Gerät (Neuralstörer am Gürtel).", 1], ["Ausweichen +2 (1)", "Gerät (Ablenkungsgürtel).", 1], ["Schnittstelle (4)", "Codeknacker. Gerät (Handgelenkcomputer). Schnell.", 1], ["Superwissenschaft (3)", "Überlast.", 1], ["Teleportation (2)", "Reichweite 48“. Gerät (Handteleporter).", 1], ["Zähigkeit +5 (3)", "Gerät (Kraftfeldgürtel). Aktivierung erforderlich.", 1]]}, {"n": "Tempest", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 170, "bk": "sw_sup", "o": 2, "d": ["Tempest, alias Johnny Salvatore, ist ein Mutant, geboren mit der Macht, das Wetter zu kontrollieren. Anfangs setzte er seine Kräfte für das Gute ein, doch seine Leidenschaft für Ökologie und sein Hass auf den langsamen Umweltfortschritt der Gesellschaft erwiesen sich als zu stark. Nun nutzt er sein Talent, um jene zu terrorisieren, die seiner Ansicht nach den Planeten zerstören – Konzerne, Regierungen, politische Gruppen und so weiter. Er tut sich oft mit der Crab (S. 150), Mako (S. 151) und Tsunami (S. 173) zusammen. Gemeinsam sind sie „Eco-Watch“, eine Terrororganisation, die jede Person oder Firma angreift, die sie als Bedrohung für die Umwelt ansieht – gleich, wie hoch der Kollateralschaden ist und wer im Weg steht. Ihre Ziele sind bewundernswert, die Mittel, zu denen sie bereit sind, nicht."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W10"], ["Stärke", "W10"], ["Verstand", "W8"], ["Willenskraft", "W12"]], "f": "Allgemeinwissen W10, Athletik W10, Fahren W6, Fokus W10, Heimlichkeit W6, Kämpfen W10, Naturwissenschaften W10, Wahrnehmung W8, Überreden W6", "b": "6", "pa": "7", "ro": "11 (2)", "x": [["Machtniveau", "II"], ["Handicaps", "Vorsichtig, Heldenhaft, Skrupellos (Leicht), Rachsüchtig (Schwer)"], ["Talente", "Kampfreflexe, Ausweichen, Rückzug, Superkräfte (30)"], ["Ausrüstung", "Körperanzug (+2)."]], "sf": [["Schadensfeld (7)", "Blitze. Schaden 3W6. Flächeneffekt (MFS).", 1], ["Flug (6)", "Bewegungsweite 24 (26 km/h). Wendig.", 1], ["Fernkampfangriff (10)", "Elektrizität. Fokus. Reichweite 12/24/48, Schaden 3W6. Flächeneffekt (GFS). (Blitzschläge.)", 1], ["Zähigkeit +2 (2)", "Muskeln und Willenskraft.", 1], ["Wetterkontrolle (5)", "Umweltresistenz gegen Luft, Elektrizität, Feuer, Wasser. Nur im Freien.", 1]]}, {"n": "Thuggee", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 171, "bk": "sw_sup", "o": 2, "d": ["Mohan war in den 1850ern ein dunkler Priester und Mitglied eines Thuggee-Kultes. Er verehrte und diente Kali, der hinduistischen Göttin des Todes und der Zeit, und nutzte ihre Bösartigkeit im Kampf gegen die britischen Eindringlinge in Indien. Der Kampf verlief jedoch schlecht, und in seiner Verzweiflung beschwor Mohan die Macht seiner schrecklichen Göttin und wurde augenblicklich in eine vierarmige lebende Statue verwandelt. Er nahm den Namen Thuggee an und ist seither der Schrecken Indiens. Der tragische Golem überwintert die meiste Zeit, döst Jahrzehnte vor sich hin, bevor er sich erhebt, um einen neuen Kult anzuführen oder eine vermeintliche Bedrohung der Kultur Indiens herauszufordern."], "a": [["Geschicklichkeit", "W12"], ["Konstitution", "W12"], ["Stärke", "W12"], ["Verstand", "W8"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W6, Einschüchtern W12, Fokus W10, Heimlichkeit W6, Kämpfen W12, Wahrnehmung W6, Überreden W4", "b": "6", "pa": "13", "ro": "36 (20)", "x": [["Machtniveau", "V"], ["Defensen", "(20) —"], ["Handicaps", "Blutrünstig, Vorsichtig, Auffälliges Aussehen (vierarmige, lebende Statue), Schwur (Schwer — Kali dienen)"], ["Talente", "Block (Verb.), Erstschlag, Raserei (Verb.), Kühler Kopf (Verb.), Rundumschlag (Verb.), Superkräfte (75), Beidhändiger Kampf"], ["Ausrüstung", "Zwei Langschwerter (Stä+W8+3W6)."]], "sf": [["Zusätzliche Aktionen (10)", "Ignoriert pro Zug bis zu vier Punkte Mehrfachaktionsabzüge.", 1], ["Alterslos (1)", "Thuggee ist mehr Statue als Mensch und altert nicht.", 1], ["Rüstung +20 (14)", "Schwere Rüstung.", 1], ["Konstrukt (8)", "+2 beim Erholen von Angeschlagen; atmet nicht; immun gegen Krankheit und Gift; ignoriert eine Stufe Wundabzüge.", 1], ["Schläft nicht (2)", "Unermüdlich. Thuggee schläft nicht, ruht aber gelegentlich seine Augen nach einem schweren Festmahl … der Seelen!", 1], ["Zusätzliche Gliedmaßen (4)", "Thuggee hat zwei zusätzliche Arme, wie die dunkle Göttin, die er verehrt.", 1], ["Nahkampfangriff (7)", "Stä+3W6, Schwere Waffe.", 1], ["Parade +3 (3)", "Wirbelnde Klingen.", 1], ["Superattribut (6)", "Geschicklichkeit +1, Stärke +1, Konstitution +1.", 1], ["Supertalent (10)", "Block (Verb.), Erstschlag, Raserei (Verb.)", 1], ["Superfertigkeit (2)", "Kämpfen +2.", 1], ["Zähigkeit +8 (8)", "Thuggees Körper besteht aus Stein.", 1], ["Unaufhaltsam", "Der Schurke erleidet durch jeden schädigenden Angriff höchstens eine Wunde (nach dem Aufnehmen), es sei denn, die Aktionskarte des Angreifers ist ein Joker."]], "ai": [["Das Böse erhebt sich", "Eine Gruppe gewöhnlicher Diebe wütet seit einem Jahr in Neu-Delhi. Sie hatten begrenzten Erfolg und wurden unablässig von den Behörden gejagt. Nun haben sie die ruhende Statue von Thuggee gefunden, und der Anführer der Bande, Purab, beginnt, ihre Geschichte und ihren Zweck zu verstehen. Wenn sie sich durch Mord und Raub als würdig erweisen, wird sich die Statue erheben und ihr Champion werden und sie zu großen Siegen und sagenhaftem Reichtum führen. Die Helden eilen Indien zu Hilfe, kommen aber zu spät – Thuggee erhebt sich erneut!"]]}, {"n": "Troglodyt", "k": "Humanoide", "w": 0, "s": ["SUP"], "p": 172, "bk": "sw_sup", "o": 2, "d": ["Troglodyten sind ein Volk, das tief unter der Erde lebt, fern vom Blick der Oberflächenbewohner. Sie sind ein Seitenzweig auf dem evolutionären Pfad der Menschheit, der unter die Erde floh, um einer längst vergessenen Katastrophe zu entgehen. Nun haben sie ihre ersten zaghaften Schritte zurück an die Oberfläche gewagt, begierig, eine Welt zurückzufordern, die sie als rechtmäßig die ihre ansehen. Die Troglodyten erkennen derzeit den Mole (S. 154) als ihren König an, auch wenn sich das ändern könnte, wenn er vor ihren barbarischen Massen gründlich besiegt würde."], "a": [["Geschicklichkeit", "W10"], ["Konstitution", "W10"], ["Stärke", "W12"], ["Verstand", "W4"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W4, Athletik W6, Fokus W6, Heimlichkeit W10, Kämpfen W10, Wahrnehmung W6, Überleben W8, Überreden W4", "b": "6", "pa": "7", "ro": "16 (8)", "x": [["Machtniveau", "II"], ["Handicaps", "Auffälliges Aussehen (unterirdischer Untermensch), Hässlich (Schwer), Verwundbarkeit (Leicht — Licht)"], ["Talente", "Kampfreflexe, Superkräfte (30), Den Treffer einstecken, Der Beste (Nahkampfangriff)"], ["Ausrüstung", "Keine."]], "sf": [["Rüstung +8 (4)", "Felsharte Haut.", 1], ["Graben (4)", "Bewegungsweite 6. Blockbuster. Tunnelbauer.", 1], ["Zäh (2)", "Ein zweites Ergebnis Angeschlagen verursacht keine Wunde.", 1], ["Geschärfte Sinne (4)", "Gehör. Infrarotsicht. Restlichtsicht. Geruch.", 1], ["Nahkampfangriff (12)", "Stä+2W6. (Klauen, +2W6, PB 6.)", 1], ["Zähigkeit +1 (1)", "Dicke Haut.", 1], ["Übernatürliche Reflexe (3)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen.", 1]]}, {"n": "Tsunami", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 173, "bk": "sw_sup", "o": 2, "d": ["Wayne Andrews wurde mit der Fähigkeit geboren, Wasser zu manipulieren. Anfangs nutzte er sie, um das Surfen zu lernen, dann um Surfwettbewerbe zu gewinnen, und schließlich, um Profi zu werden. Schließlich geriet er in eine Bande von Draufgängern und führt sie bei Plänen an, die sich um verschiedene Extremsportarten drehen und es den Behörden schwer machen, ihnen zu folgen. Er arbeitet manchmal mit Tempest, hält den Sturmkontrolleur aber für die meisten Jobs für zu gewalttätig."], "a": [["Geschicklichkeit", "W12"], ["Konstitution", "W10"], ["Stärke", "W10"], ["Verstand", "W12"], ["Willenskraft", "W10"]], "f": "Allgemeinwissen W6, Athletik W12, Fahren W12, Fokus W10, Heimlichkeit W4, Kämpfen W8, Provozieren W6, Wahrnehmung W6, Überreden W8", "b": "6", "pa": "6", "ro": "12", "x": [["Machtniveau", "II"], ["Handicaps", "Neugierig, Arm, Tick (redet wie ein Surfer)"], ["Talente", "(Sehr) Attraktiv, Erstschlag, Schnell, Superkräfte (30)"], ["Ausrüstung", "Keine."]], "sf": [["Wasserlebewesen (1)", "Halbaquatisch.", 1], ["Umweltresistenz (3)", "Wasser. Immunität.", 1], ["Materiekontrolle (12)", "Wasser. Flächeneffekt (GFS). Macht.", 1], ["Superattribut (6)", "Geschicklichkeit +3.", 1], ["Zähigkeit +5 (5)", "Wassergetränkter Körper.", 1], ["Übernatürliche Reflexe (3)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen.", 1]]}, {"n": "Vulcan", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 174, "bk": "sw_sup", "o": 2, "d": ["Bei einer der Invasionen Stygias auf der Erde verlor Asmodeus seinen wertvollsten Leutnant – seinen Sohn Blackstar. Etwas, das an Trauer erinnert, überkam den sonst kalten Meister der Dunklen Welt, und er sann auf Vergeltung. Der Tyrann von Stygia nahm John Abrahams, alias Infernus, gefangen und brach Körper und Seele des mächtigen Feuerwerfers, bis er ein loyaler Diener der Hölle wurde – Vulcan, Sohn der Schwarzen Flamme. Vulcan erscheint als dunkle Verhöhnung seiner früheren Pracht. Wo seine Flammen einst gelb und karmesinrot brannten, brennen sie nun schwarz und blau, wie das Feuer Stygias selbst."], "a": [["Geschicklichkeit", "W12"], ["Konstitution", "W12"], ["Stärke", "W12+5"], ["Verstand", "W8"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W6, Athletik W6, Einschüchtern W8, Fokus W12+2, Heimlichkeit W6, Kämpfen W6, Wahrnehmung W6, Überreden W4", "b": "6", "pa": "5", "ro": "13", "x": [["Machtniveau", "V"], ["Handicaps", "Wahnvorstellungen (Schwer — glaubt, in Stygia geboren zu sein), Fies, Skrupellos (Schwer)"], ["Talente", "Kampfreflexe, Volltreffer, Ausweichen (Verb.), Wendiger Rückzug, Meisterschütze, Superkräfte (75)"], ["Ausrüstung", "Keine."]], "sf": [["Schadensfeld (12)", "Feuer. Schaden 4W6. Flächeneffekt (GFS). Tödlich. Schwere Waffe. Dauerhaft. Selektiv.", 1], ["Verdammnis", "Vulcan kehrt in den Abgrund zurück, wenn er Kampfunfähig ist."], ["Energiekontrolle (7)", "Feuer. Flächeneffekt (GFS).", 1], ["Umweltresistenz (3)", "Feuer. Immunität.", 1], ["Flug (16)", "Überschallgeschwindigkeit, –8 auf Treffer im Flug.", 1], ["Geschärfte Sinne (2)", "Infrarotsicht, Restlichtsicht.", 1], ["Fernkampfangriff (18)", "Feuer. Fokus. Reichweite 12/24/48 oder Kegelschablone, Schaden 5W6, PB 10. Schwere Waffe. (Feuerblitze.)", 1], ["Größe 5", "Vulcan ist 4,9 m groß."], ["Superattribut (10)", "Geschicklichkeit +1, Stärke +2, Konstitution +2.", 1], ["Übernatürliche Reflexe (3)", "Ignoriere den –2-Abzug bei Ausweichversuchen; kann Flächenangriffen, die dies normalerweise nicht erlauben, mit –2 ausweichen.", 1], ["Unaufhaltsam", "Der Schurke erleidet durch jeden schädigenden Angriff höchstens eine Wunde (nach dem Aufnehmen), es sei denn, die Aktionskarte des Angreifers ist ein Joker."], ["Zähigkeit +4", "Höllengebundene Haut."]], "ai": [["Aus Liebe", "John, der Mensch, hat sich an die Oberfläche seiner Psyche zurückgekämpft. Er sucht seine Frau Tabitha irgendwo in der Heimatstadt der Helden. Die Vulcan-Persönlichkeit ist jedoch noch da, und wenn die Ordnungskräfte ihn angreifen, kann John nicht anders, als mit seinen tödlichen Schwarzfeuerblitzen zurückzufeuern. Asmodeus hat John darauf konditioniert, Helden zu hassen, daher stottert und kreischt er, wenn er seine Bemühungen erklären will – und feuert schließlich aus Frustration seine Salven auf sie ab. Das Monster stampft durch Wohnviertel auf der Suche nach Tabitha und findet sie, wenn es niemand aufhält. Dort verebbt die brutale Bestie, und John übernimmt für einen kurzen Moment. Er küsst seine Frau zum Abschied und nennt den Helden dann den Ort eines Kultes, der Asmodeus erneut beschwören will. Vulcan verblasst dann ins Schwarze und kehrt in die Hölle und seine ewige Knechtschaft zurück."]]}, {"n": "Warden", "k": "Humanoide", "w": 1, "s": ["SUP"], "p": 175, "bk": "sw_sup", "o": 2, "d": ["Dr. Jordan Jones gehörte dem Einsatz-Unterstützungsteam der Vanguard Defense Force an, der Abteilung der Heimatschutzbehörde, die für die Festsetzung superkräftiger Krimineller zuständig ist. Dr. Jones entwarf viele der Geräte der VDF-Feldagenten, darunter für seinen Bruder Ricochet. Als sein Bruder bei einem Undercover-Einsatz starb, trat Dr. Jones aus der VDF aus und nahm viele seiner Erfindungen mit. Nach dem Aufbau einer Operationsbasis nahm Dr. Jones den Mantel des Warden an und schwor, es besser zu machen als die Führung der VDF. Warden nutzt Hightech-Geräte eigener Konstruktion im Kampf gegen die Feinde der Erde, darunter ein Nanitenschwert, einen hochmodernen Energieschild und einen maßgeschneiderten Hightech-Anzug, der eingehenden Schaden absorbiert und seine körperlichen Fähigkeiten steigert.", "Seine Gadgets, sein natürlicher Verstand und sein starker moralischer Kompass verschafften ihm die Mitgliedschaft in der Doom Guard, und durch seine Führung und die Bewunderung seiner Heldenkollegen stieg Warden binnen weniger Jahre zu ihrem Anführer auf. Warden hat geschworen, die Erde vor außerirdischen Invasoren, dunklen Dimensionen und anderen existenziellen Bedrohungen zu schützen und seine Mitglieder nach besten Kräften zu schützen – ein Balanceakt, der seine geplagte Seele ständig belastet. Jordan adoptierte den Sohn seines Bruders, Jamal, einen neugierigen Jugendlichen, der das Geheimnis seines Onkels durchschaut hat und ständig nach einem Weg sucht, Superheld zu werden und seinen toten Vater zu ehren. Er ist ein heller, aber rücksichtsloser Junge, der seinem Onkel oft beträchtlichen Ärger bereitet. Trotz der schrecklichen Last steht Warden stets an der Spitze, wenn die Welt bedroht ist. Was geschieht, wenn er dem unmöglichen Maßstab, den er sich selbst gesetzt hat, nicht mehr gerecht werden kann, bleibt abzuwarten."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W8"], ["Stärke", "W10"], ["Verstand", "W8"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W6, Athletik W8, Elektronik W6, Fliegen W8, Fokus W8, Heimlichkeit W6, Kämpfen W8, Naturwissenschaften W12, Reparieren W8, Wahrnehmung W6, Überreden W8", "b": "6", "pa": "11", "ro": "12 (6)", "x": [["Machtniveau", "II"], ["Handicaps", "Abhängiger (Leicht — Neffe), Heldenhaft, Loyal"], ["Talente", "Attraktiv, Anführer, Gemeinsames Band, Eisenkiefer, Geborener Anführer, Superkräfte (30), Teamleiter"], ["Ausrüstung", "Verstärkter Superanzug (siehe unten), Nanitenklinge (Stä+2W6, PB 8, ignoriert die Rüstung unbelebter Objekte und Fahrzeuge)."]], "sf": [["Rüstung +6 (6)", "Schwere Rüstung. Gerät (maßgeschneiderter Superanzug).", 1], ["Furchtlos (4)", "Besonnen.", 1], ["Genie (2)", "Brillanter Verstand und gut ausgebildet.", 1], ["Springen (4)", "Stufe 4. 16“ senkrecht, 32“ waagerecht. Tod von oben. Gerät (maßgeschneiderter Superanzug).", 1], ["Parade +5 (6)", "Beschützer. Gerät (Superanzug).", 1], ["Stoßen (2)", "Stark. Gerät (maßgeschneiderter Superanzug).", 1], ["Scan (3)", "Menschen. Zusätzliche Machttypen (Elektrizität). Distanz (16 km). Gerät (Visier mit Sensoren und Helm-Display).", 1], ["Superattribut (3)", "Stärke +2. Gerät (Superanzug).", 1]]}, {"n": "Whirling Dervish", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 176, "bk": "sw_sup", "o": 2, "d": ["Sara Boucher begann mit fünf Jahren zu zittern. In ihren Teenagerjahren erkannte sie, dass sie Kräfte hatte, und versuchte, Verbrechensbekämpferin zu werden. Das führte zur Tragödie, und um dem Gefängnis zu entgehen, erlaubten ihre Eltern, dass sie in ein staatliches Trainingsprogramm namens Projekt Spartan aufgenommen wurde. Sara rebellierte gegen das Training und floh, geriet schließlich zum Fixer (S. 125) und zum Spider (S. 165). Sie stiehlt, um einen luxuriösen Lebensstil zu finanzieren, und schlägt häufig gegen die Regierungen der Welt los, für das, was sie als ihre verlorene Kindheit ansieht."], "a": [["Geschicklichkeit", "W12"], ["Konstitution", "W8"], ["Stärke", "W6"], ["Verstand", "W8"], ["Willenskraft", "W8"]], "f": "Allgemeinwissen W6, Athletik W12, Diebeskunst W8, Einschüchtern W8, Fahren W6, Fokus W10, Heimlichkeit W10, Kämpfen W10, Provozieren W12, Wahrnehmung W12, Überreden W6", "b": "1152", "pa": "12", "ro": "6", "x": [["Machtniveau", "III"], ["Defensen", "–5 (Fernkampf)"], ["Handicaps", "Arrogant, Große Klappe, Tick (unglaublich ruhelos)"], ["Talente", "Erstschlag, Kühler Kopf (Verb.), Superkräfte (45), Der Beste (Geschwindigkeit)"], ["Ausrüstung", "Keine."]], "sf": [["Zusätzliche Aktionen (8)", "Ignoriert pro Zug bis zu zwei Punkte Mehrfachaktionsabzüge. Konzentration. Schnelle Aktion. Nur körperlich.", 1], ["Ausweichen –5 (5)", "–5, um von Fernkampfangriffen getroffen zu werden.", 1], ["Nahkampfangriff (6)", "Stä+3W6.", 1], ["Parade +5 (5)", "Superschnelligkeit.", 1], ["Geschwindigkeit (21)", "Überschallgeschwindigkeit, –8 auf Treffer. Wendig. Traktieren. Oberflächenspannung.", 1]]}, {"n": "Witch Hunter", "k": "Superschurken", "w": 1, "s": ["SUP"], "p": 177, "bk": "sw_sup", "o": 2, "d": ["Josef Olegski war 1916 ein junger Jäger und Fallensteller in Sibirien. Während eines schrecklichen Sturms suchte er Zuflucht in einer seltsamen Hütte und schnappte vor Entsetzen nach Luft, als sie sich auf zwei dürren Hühnerbeinen erhob. Es war die wandelnde Hütte der berüchtigten russischen Hexe Baba Yaga. Im Austausch für sein Leben willigte Josef ein, ihr persönlicher Jäger zu werden und zauberische Rivalen aufzuspüren, damit sie die unangefochtene Herrin der magischen Künste blieb. Über ein Jahrhundert später ist der „Witch Hunter“ noch immer jugendlich und kräftig, wenn auch desillusioniert vom Leben und dem ständigen Töten. Er geht methodisch vor, beobachtet seine Beute wochenlang, testet ihre Kräfte mit Ablenkungen und bezahlten Schlägern oder inszenierten Katastrophen und schlägt dann zu, wenn sie am verwundbarsten ist. Im Lauf der Jahre sind Dutzende junger Magier, die Baba Yagas überirdische Augen auf sich zogen, dem kalten, berechnenden Witch Hunter zum Opfer gefallen."], "a": [["Geschicklichkeit", "W8"], ["Konstitution", "W12"], ["Stärke", "W10"], ["Verstand", "W10"], ["Willenskraft", "W6"]], "f": "Allgemeinwissen W10, Athletik W8, Fahren W6, Fokus W10, Heimlichkeit W12+2, Kämpfen W10, Schießen W12+2, Wahrnehmung W12, Überleben W12, Überreden W8", "b": "6", "pa": "7", "ro": "13", "x": [["Machtniveau", "III"], ["Handicaps", "Nichtschwimmer, Vorsichtig, Grimmig"], ["Talente", "Berechnend, Kampfreflexe, Gefahrensinn, Kühler Kopf (Verb.), Superkräfte (45)"], ["Ausrüstung", "Impulsgewehr (Reichweite 20/40/80, Schaden 3W6, PB 4)."]], "sf": [["Absorption (10)", "Magie. Zusätzliche Machttypen (alle).", 1], ["Alterslos (1)", "Josef sieht noch immer aus wie ein Zwanzigjähriger, obwohl er seit 1897 lebt.", 1], ["Wachsamkeit (5)", "Ignoriert 5 Punkte der Angriffsabzüge eines Gegners.", 1], ["Umweltresistenz (3)", "Zauberei. Immunität.", 1], ["Negation (12)", "Volles Spektrum. Reichweite (24“). Stark.", 1], ["Superattribut (4)", "Konstitution +2.", 1], ["Superfertigkeit (5)", "Fokus +1, Heimlichkeit +2, Schießen +2.", 1], ["Zähigkeit +5 (5)", "Magische Verstärkung.", 1]]}]);
